import { describe, expect, it } from "vitest";

import {
  DEFAULT_LIGHT_MODE,
  DUOTONE_INK,
  DUOTONE_PAPER,
  LIGHT_MODES,
  duotoneColor,
  inkColor,
  isLightMode,
  lightPalette,
  lightScene,
  paperOf,
  sceneColors,
} from "../src/light.ts";
import { PAPER_BAND, contrastRatio, parseHex, relativeLuminance, toHsl } from "../src/palette.ts";

const hex = (value: string): { r: number; g: number; b: number } => {
  const rgb = parseHex(value);
  if (rgb === null) throw new Error(`${value} is not a colour`);
  return rgb;
};

/** A stand-in for one scene: near-black ground, pale ink plus two hues. */
const SCENE = { ground: "#090c18", palette: ["#0e1430", "#fffbea", "#ff4d4d", "#0070f3"] };

describe("the mode vocabulary", () => {
  it("offers exactly the two treatments and defaults to ink", () => {
    expect(LIGHT_MODES).toEqual(["ink", "duotone"]);
    expect(DEFAULT_LIGHT_MODE).toBe("ink");
    for (const mode of LIGHT_MODES) expect(isLightMode(mode)).toBe(true);
  });

  it("refuses anything else, so a hand-edited document cannot pick a treatment", () => {
    for (const bad of ["paper", "", "Ink", null, 0, {}]) expect(isLightMode(bad)).toBe(false);
  });
});

describe("paperOf", () => {
  it("turns a near-black ground into paper", () => {
    expect(relativeLuminance(hex(paperOf("#000000")))).toBeGreaterThan(0.6);
    expect(relativeLuminance(hex(paperOf("#090c18")))).toBeGreaterThan(0.6);
  });

  it("drops the ground's hue, because paper is not a tinted slab", () => {
    expect(toHsl(hex(paperOf("#090c18"))).s).toBe(0);
    expect(toHsl(hex(paperOf("#ff4d4d"))).s).toBe(0);
  });

  it("stays in the paper band even for a mid-dark ground", () => {
    for (const ground of ["#000000", "#090c18", "#3d2058", "#ff4d4d"]) {
      const l = toHsl(hex(paperOf(ground))).l;
      expect(l).toBeGreaterThanOrEqual(PAPER_BAND.min);
      // 8-bit channels move lightness by up to half a step, which is not a bug.
      expect(l).toBeLessThanOrEqual(PAPER_BAND.max + 0.005);
    }
  });

  it("returns unusable input unchanged rather than throwing", () => {
    expect(paperOf("not-a-colour")).toBe("not-a-colour");
  });
});

describe("inkColor", () => {
  it("turns a pale highlight into dark ink and a black shadow into paper", () => {
    expect(relativeLuminance(hex(inkColor("#ffffff")))).toBeLessThan(0.05);
    expect(relativeLuminance(hex(inkColor("#000000")))).toBeGreaterThan(0.9);
  });

  it("keeps the hue, so a sunset stays warm and a dusk stays plum", () => {
    expect(toHsl(hex(inkColor("#ff4d4d"))).h).toBeCloseTo(toHsl(hex("#ff4d4d")).h, 0);
    expect(toHsl(hex(inkColor("#3d2058"))).h).toBeCloseTo(toHsl(hex("#3d2058")).h, 0);
  });

  it("is its own inverse, because mirroring lightness twice is the identity", () => {
    for (const value of ["#fffbea", "#0070f3", "#0e1430"]) {
      expect(inkColor(inkColor(value))).toBe(value);
    }
  });

  it("returns unusable input unchanged rather than throwing", () => {
    expect(inkColor("not-a-colour")).toBe("not-a-colour");
  });
});

describe("duotoneColor", () => {
  it("puts the darkest colour on the paper and the brightest on the ink", () => {
    expect(duotoneColor("#000000")).toBe(DUOTONE_PAPER);
    expect(duotoneColor("#ffffff")).toBe(DUOTONE_INK);
  });

  it("moves monotonically from paper to ink as the colour brightens", () => {
    const luminances = ["#000000", "#3d2058", "#808080", "#fffbea"].map((value) =>
      relativeLuminance(hex(duotoneColor(value))),
    );
    for (let i = 1; i < luminances.length; i++) {
      expect(luminances[i] as number).toBeLessThan(luminances[i - 1] as number);
    }
  });

  it("keeps enough contrast against the paper to be a picture", () => {
    const ink = hex(duotoneColor("#ffffff"));
    const paper = hex(duotoneColor("#000000"));
    expect(contrastRatio(ink, paper)).toBeGreaterThan(12);
  });

  it("returns unusable input unchanged rather than throwing", () => {
    expect(duotoneColor("not-a-colour")).toBe("not-a-colour");
  });
});

describe("lightPalette", () => {
  it("keeps every entry in its index and every mode distinct", () => {
    for (const mode of LIGHT_MODES) {
      const result = lightPalette(SCENE.palette, mode);
      expect(result).toHaveLength(SCENE.palette.length);
      expect(result[0]).not.toBe(result[1]);
    }
  });

  it("gives the two modes different colours for the same entry", () => {
    const ink = lightPalette(SCENE.palette, "ink");
    const duotone = lightPalette(SCENE.palette, "duotone");
    expect(ink).not.toEqual(duotone);
  });
});

describe("lightScene and sceneColors", () => {
  it("gives the ink mode a paper ground and the duotone mode the plate's stock", () => {
    expect(lightScene(SCENE, "ink").ground).toBe(paperOf(SCENE.ground));
    expect(lightScene(SCENE, "duotone").ground).toBe(DUOTONE_PAPER);
  });

  it("leaves the dark scheme exactly as the piece declared it, whatever the mode", () => {
    for (const mode of LIGHT_MODES) {
      const colors = sceneColors(SCENE, "dark", mode);
      expect(colors.ground).toBe(SCENE.ground);
      expect(colors.palette).toEqual(SCENE.palette);
    }
  });

  it("reads dark marks on a light ground in the light scheme", () => {
    for (const mode of LIGHT_MODES) {
      const colors = sceneColors(SCENE, "light", mode);
      const ground = hex(colors.ground);
      // The picture is only a picture if its marks are darker than its page.
      const marks = colors.palette.map((colour) => relativeLuminance(hex(colour)));
      expect(Math.min(...marks)).toBeLessThan(relativeLuminance(ground));
    }
  });
});

import { describe, expect, it } from "vitest";

import {
  DEFAULT_APPEARANCE,
  DEFAULT_REGIONS,
  DEFAULT_SCENE_OPTIONS,
  DEFAULT_SETTINGS,
  normalizeAppearance,
  RESOLUTION_RANGE,
  normalizeRegions,
  normalizeSceneOptions,
  NEW_CHAT_SPLASH_RANGE,
  normalizeSettings,
  settingsEqual,
} from "../src/options.ts";
import { normalizeCatalog } from "../src/catalog.ts";

const catalog = normalizeCatalog({
  scenes: [
    {
      id: "salt-flat",
      name: "salt flat",
      note: "the vercel triangle over a mirror of salt",
      cols: 200,
      rows: 100,
      cell: 1,
      fps: 15,
      ground: "#000000",
      palette: ["#0d0d0e", "#ffffff"],
      still: 0,
    },
    {
      id: "kyoto-dusk",
      name: "kyoto dusk",
      note: "a temple roof at dusk",
      cols: 120,
      rows: 60,
      cell: 2,
      fps: 12,
      ground: "#0b0a16",
      palette: ["#0b0a16", "#ffffff"],
      still: 0,
    },
  ],
}).scenes;

describe("normalizeSceneOptions", () => {
  it("returns the defaults for nothing at all", () => {
    expect(normalizeSceneOptions(undefined)).toEqual(DEFAULT_SCENE_OPTIONS);
    expect(normalizeSceneOptions(null)).toEqual(DEFAULT_SCENE_OPTIONS);
    expect(normalizeSceneOptions("garbage")).toEqual(DEFAULT_SCENE_OPTIONS);
  });

  it("clamps a hand-edited value into its documented range", () => {
    const read = normalizeSceneOptions({ zoom: 100, fit: "stretch", anchor: "middle", lightMode: "sepia" });
    expect(read.zoom).toBe(4);
    // An unknown fit, anchor or light treatment is not a new mode: it falls back.
    expect(read.fit).toBe(DEFAULT_SCENE_OPTIONS.fit);
    expect(read.anchor).toBe(DEFAULT_SCENE_OPTIONS.anchor);
    expect(read.lightMode).toBe(DEFAULT_SCENE_OPTIONS.lightMode);
  });

  it("keeps a light treatment this build knows", () => {
    expect(normalizeSceneOptions({ lightMode: "duotone" }).lightMode).toBe("duotone");
    expect(normalizeSceneOptions({ lightMode: "ink" }).lightMode).toBe("ink");
  });

  it("reads a fit mode and an anchor", () => {
    const read = normalizeSceneOptions({ fit: "contain", anchor: "bottom-left" });
    expect(read.fit).toBe("contain");
    expect(read.anchor).toBe("bottom-left");
  });

  it("recovers an anchor from the offsets an older build stored", () => {
    // The previous document had two continuous offsets; rounding each to its
    // nearest edge recovers the corner the reader had effectively chosen.
    expect(normalizeSceneOptions({ offsetX: -0.9, offsetY: -0.9 }).anchor).toBe("top-left");
    expect(normalizeSceneOptions({ offsetX: 0.9, offsetY: 0.9 }).anchor).toBe("bottom-right");
    expect(normalizeSceneOptions({ offsetX: 0, offsetY: 0 }).anchor).toBe("center");
    expect(normalizeSceneOptions({ offsetX: 0.02, offsetY: -0.9 }).anchor).toBe("top");
  });

  it("falls back per field, so one bad value does not reset the rest", () => {
    const read = normalizeSceneOptions({ lightMode: "duotone", zoom: Number.NaN });
    expect(read.lightMode).toBe("duotone");
    expect(read.zoom).toBe(DEFAULT_SCENE_OPTIONS.zoom);
  });
});

describe("normalizeAppearance", () => {
  it("returns the defaults for nothing at all", () => {
    expect(normalizeAppearance(undefined)).toEqual(DEFAULT_APPEARANCE);
  });

  it("clamps and coerces", () => {
    const read = normalizeAppearance({ opacity: 5, blur: -3, veil: 2, still: "yes", fps: 900 });
    expect(read.opacity).toBe(1);
    expect(read.blur).toBe(0);
    expect(read.veil).toBe(1);
    expect(read.still).toBe(DEFAULT_APPEARANCE.still);
    expect(read.fps).toBe(30);
  });

  it("keeps the render density inside the range a display can honour", () => {
    // A stored 0 would divide the backing store to nothing, and 8 would spend
    // thirty-two times the fill rate of a 2x display for no visible gain.
    expect(normalizeAppearance({ resolution: 0 }).resolution).toBe(RESOLUTION_RANGE.min);
    expect(normalizeAppearance({ resolution: 8 }).resolution).toBe(RESOLUTION_RANGE.max);
    expect(normalizeAppearance({ resolution: 1.5 }).resolution).toBe(1.5);
    expect(normalizeAppearance({}).resolution).toBe(DEFAULT_APPEARANCE.resolution);
  });
});

describe("normalizeRegions", () => {
  it("defaults every region to its calibrated reveal", () => {
    expect(normalizeRegions(undefined)).toEqual(DEFAULT_REGIONS);
  });

  it("reads each region independently and clamps it", () => {
    const read = normalizeRegions({ sidebar: 0.3, main: -1, rightbar: 9 });
    expect(read.sidebar).toBe(0.3);
    // An out-of-range value is clamped, and the omitted region keeps its default.
    expect(read.main).toBe(0);
    expect(read.rightbar).toBe(1);
    expect(read.bottom).toBe(DEFAULT_REGIONS.bottom);
  });

  it("falls back per region, so one bad value does not reset the others", () => {
    const read = normalizeRegions({ sidebar: 0.4, main: "sealed" });
    expect(read.sidebar).toBe(0.4);
    expect(read.main).toBe(DEFAULT_REGIONS.main);
  });
});

describe("the scrim and focus settings", () => {
  it("defaults to no scrim and to pausing while unfocused", () => {
    expect(DEFAULT_APPEARANCE.scrim).toBe(0);
    expect(DEFAULT_APPEARANCE.pauseOnBlur).toBe(true);
  });

  it("reads a scrim angle and wraps nothing silently", () => {
    const read = normalizeAppearance({ scrim: 0.4, scrimAngle: 999, pauseOnBlur: false });
    expect(read.scrim).toBe(0.4);
    // The angle is clamped to one turn rather than folded: 999deg and 279deg
    // are the same gradient, but storing 999 would keep growing every save.
    expect(read.scrimAngle).toBe(360);
    expect(read.pauseOnBlur).toBe(false);
  });
});

describe("normalizeSettings", () => {
  it("reads a document this build wrote", () => {
    const settings = normalizeSettings(
      { scene: "kyoto-dusk", options: { lightMode: "duotone" }, appearance: { veil: 0.4 } },
      catalog,
    );
    expect(settings.scene).toBe("kyoto-dusk");
    expect(settings.options.lightMode).toBe("duotone");
    expect(settings.appearance.veil).toBe(0.4);
  });

  it("rejects a scene id this build no longer ships", () => {
    expect(normalizeSettings({ scene: "removed-upstream" }, catalog).scene).toBe(DEFAULT_SETTINGS.scene);
  });

  it("accepts an empty scene as a deliberate choice", () => {
    // An empty id is not "missing": it is the reader asking for no scene at all.
    expect(normalizeSettings({ scene: "" }, catalog).scene).toBe("");
  });

  it("fills every missing branch", () => {
    const settings = normalizeSettings({}, catalog);
    expect(settings.options).toEqual(DEFAULT_SCENE_OPTIONS);
    expect(settings.appearance).toEqual(DEFAULT_APPEARANCE);
  });

  it("plays the splash for a document that predates it", () => {
    // The splash is a fresh-install default, so an upgrade has to turn it on:
    // a document written before the field existed reads as missing, not as off.
    expect(DEFAULT_SETTINGS.splash).toBe(true);
    expect(normalizeSettings({}, catalog).splash).toBe(true);
    expect(normalizeSettings({ scene: "kyoto-dusk" }, catalog).splash).toBe(true);
  });

  it("keeps a splash the reader turned off", () => {
    expect(normalizeSettings({ splash: false }, catalog).splash).toBe(false);
  });

  it("falls back to playing the splash for a value that is not a boolean", () => {
    // "false" as a string is a hand-edited document, not a decision: reading it
    // as off would be trusting a shape this build never wrote.
    expect(normalizeSettings({ splash: "false" }, catalog).splash).toBe(true);
    expect(normalizeSettings({ splash: 0 }, catalog).splash).toBe(true);
    expect(normalizeSettings({ splash: null }, catalog).splash).toBe(true);
  });

  it("keeps the new-chat splash off for a document that predates it", () => {
    // The opposite default from the cold-start splash, and deliberately so: a
    // splash on every new conversation is an interruption, not an opening, so
    // an upgrade must not turn it on for a reader who never asked.
    expect(DEFAULT_SETTINGS.splashOnNewChat).toBe(false);
    expect(normalizeSettings({}, catalog).splashOnNewChat).toBe(false);
    expect(normalizeSettings({ scene: "kyoto-dusk" }, catalog).splashOnNewChat).toBe(false);
  });

  it("keeps a new-chat splash the reader turned on", () => {
    expect(normalizeSettings({ splashOnNewChat: true }, catalog).splashOnNewChat).toBe(true);
  });

  it("falls back to off for a new-chat splash that is not a boolean", () => {
    expect(normalizeSettings({ splashOnNewChat: "true" }, catalog).splashOnNewChat).toBe(false);
    expect(normalizeSettings({ splashOnNewChat: 1 }, catalog).splashOnNewChat).toBe(false);
    expect(normalizeSettings({ splashOnNewChat: null }, catalog).splashOnNewChat).toBe(false);
  });

  it("holds the new-chat splash for half the cold-start minimum by default", () => {
    // A new conversation is opened as often as the reader clicks, so the same
    // 1200ms that reads as a deliberate opening on a cold start reads as a
    // hold-up on the fifth one. Half of it is the default, not the floor.
    expect(DEFAULT_SETTINGS.newChatSplashMs).toBe(600);
    expect(normalizeSettings({}, catalog).newChatSplashMs).toBe(600);
    expect(normalizeSettings({ scene: "kyoto-dusk" }, catalog).newChatSplashMs).toBe(600);
  });

  it("keeps a new-chat splash duration the reader chose", () => {
    expect(normalizeSettings({ newChatSplashMs: 250 }, catalog).newChatSplashMs).toBe(250);
    expect(normalizeSettings({ newChatSplashMs: 2500 }, catalog).newChatSplashMs).toBe(2500);
  });

  it("clamps a new-chat splash duration to the range the slider offers", () => {
    // The slider and the read path share one range, so a hand-edited document
    // cannot ask for a splash the control could never have produced.
    expect(NEW_CHAT_SPLASH_RANGE).toEqual({ min: 200, max: 3000, step: 100 });
    expect(normalizeSettings({ newChatSplashMs: 50 }, catalog).newChatSplashMs).toBe(200);
    expect(normalizeSettings({ newChatSplashMs: 99_999 }, catalog).newChatSplashMs).toBe(3000);
  });

  it("falls back to the default for a new-chat splash duration that is not a number", () => {
    expect(normalizeSettings({ newChatSplashMs: "900" }, catalog).newChatSplashMs).toBe(600);
    expect(normalizeSettings({ newChatSplashMs: null }, catalog).newChatSplashMs).toBe(600);
    expect(normalizeSettings({ newChatSplashMs: Number.NaN }, catalog).newChatSplashMs).toBe(600);
  });
});

describe("settingsEqual", () => {
  it("compares by value, not identity", () => {
    const a = normalizeSettings({ scene: "kyoto-dusk" }, catalog);
    const b = normalizeSettings({ scene: "kyoto-dusk" }, catalog);
    expect(a).not.toBe(b);
    expect(settingsEqual(a, b)).toBe(true);
  });

  it("notices a single changed number", () => {
    const a = normalizeSettings({}, catalog);
    const b = normalizeSettings({ appearance: { veil: 0.9 } }, catalog);
    expect(settingsEqual(a, b)).toBe(false);
  });

  it("notices a changed render density", () => {
    // The store drops a write it judges equal, so a setting left out of this
    // comparison is a control that silently does nothing.
    const base = normalizeSettings({}, catalog);
    expect(settingsEqual(base, normalizeSettings({ appearance: { resolution: 1.5 } }, catalog))).toBe(false);
  });

  it("notices a moved anchor and a changed region", () => {
    const base = normalizeSettings({}, catalog);
    expect(settingsEqual(base, normalizeSettings({ options: { anchor: "top-left" } }, catalog))).toBe(false);
    expect(settingsEqual(base, normalizeSettings({ regions: { sidebar: 0.5 } }, catalog))).toBe(false);
    expect(settingsEqual(base, normalizeSettings({ appearance: { scrim: 0.5 } }, catalog))).toBe(false);
    expect(settingsEqual(base, normalizeSettings({ appearance: { pauseOnBlur: false } }, catalog))).toBe(false);
  });

  it("notices a splash turned off", () => {
    const base = normalizeSettings({}, catalog);
    expect(settingsEqual(base, normalizeSettings({ splash: false }, catalog))).toBe(false);
    expect(settingsEqual(base, normalizeSettings({ splash: true }, catalog))).toBe(true);
  });

  it("notices the new-chat splash being turned on", () => {
    const base = normalizeSettings({}, catalog);
    expect(settingsEqual(base, normalizeSettings({ splashOnNewChat: true }, catalog))).toBe(false);
    expect(settingsEqual(base, normalizeSettings({ splashOnNewChat: false }, catalog))).toBe(true);
  });

  it("notices a changed new-chat splash duration", () => {
    // The store drops a write it judges equal, so a duration left out of this
    // comparison is a slider that moves and never saves.
    const base = normalizeSettings({}, catalog);
    expect(settingsEqual(base, normalizeSettings({ newChatSplashMs: 1200 }, catalog))).toBe(false);
    expect(settingsEqual(base, normalizeSettings({ newChatSplashMs: 600 }, catalog))).toBe(true);
  });
});

import { describe, expect, it } from "vitest";

import {
  contrastRatio,
  formatHex,
  fromHsl,
  parseHex,
  relativeLuminance,
  toHsl,
} from "../src/palette.ts";

describe("parseHex", () => {
  it("reads the two forms a palette uses", () => {
    expect(parseHex("#ffffff")).toEqual({ r: 255, g: 255, b: 255 });
    expect(parseHex("#000000")).toEqual({ r: 0, g: 0, b: 0 });
    expect(parseHex("#abc")).toEqual({ r: 0xaa, g: 0xbb, b: 0xcc });
  });

  it("refuses anything that is not a hex colour", () => {
    for (const bad of ["black", "#ffff", "#gggggg", "rgb(0,0,0)", ""]) {
      expect(parseHex(bad)).toBeNull();
    }
  });
});

describe("formatHex", () => {
  it("rounds and pads", () => {
    expect(formatHex({ r: 0, g: 0, b: 0 })).toBe("#000000");
    expect(formatHex({ r: 255.4, g: 128, b: -3 })).toBe("#ff8000");
  });
});

describe("HSL round trip", () => {
  it("recovers a colour it decomposed", () => {
    for (const hex of ["#ff0000", "#0070f3", "#c5a468", "#123456", "#808080", "#ffffff"]) {
      const rgb = parseHex(hex);
      expect(rgb).not.toBeNull();
      if (rgb === null) continue;
      expect(formatHex(fromHsl(toHsl(rgb)))).toBe(hex);
    }
  });

  it("keeps grey grey", () => {
    const grey = toHsl({ r: 128, g: 128, b: 128 });
    expect(grey.s).toBe(0);
    expect(grey.h).toBe(0);
  });
});

describe("relativeLuminance and contrastRatio", () => {
  it("anchors black and white", () => {
    expect(relativeLuminance({ r: 0, g: 0, b: 0 })).toBeCloseTo(0, 5);
    expect(relativeLuminance({ r: 255, g: 255, b: 255 })).toBeCloseTo(1, 5);
    expect(contrastRatio({ r: 0, g: 0, b: 0 }, { r: 255, g: 255, b: 255 })).toBeCloseTo(21, 1);
    expect(contrastRatio({ r: 10, g: 10, b: 10 }, { r: 10, g: 10, b: 10 })).toBeCloseTo(1, 5);
  });
});

