    await until(() => host.querySelector("[data-arch-body] svg") !== null);
    expect(host.querySelector('button[data-view-id="index"]')?.getAttribute("aria-pressed")).toBe("true");
    expect(viewportTransform(host)).toBe(before);
    dispose();
  });
});

