/** A seam that records what the click drove. */
function fakeSeam(overrides: Partial<ArchReferenceSeam> = {}) {
  const calls: string[] = [];
  const clickTab = vi.fn(() => {
    calls.push("clickTab");
    return true;
  });
  const seam: ArchReferenceSeam = {
    currentSessionId: () => "s1",
    activeTab: () => false,
    clickTab,
    ...overrides,
  };
  return { seam, calls, clickTab };
}

describe("openArchReference", () => {
  beforeEach(() => {
