  it("refuses a chip from another session without filing anything", () => {
    const { seam, clickTab } = fakeSeam();
    const ref = archReferencePayload(ID, FACTS, SOURCE, CODE).ref;
    expect(openArchReference(seam, "s2", ref)).toBe(false);
