/**
 * Relationship decoding: the pure functions behind the relations pane.
 *
 * The real repo model writes relation records as `{ id, source: { model },
 * target: { model }, title }` and omits technology/description entirely, so
 * the soft-probe behaviour is the normal case here, not an edge case.
 */
import { describe, expect, it } from "vitest";

import {
  groupRelations,
  readAllRelations,
  readRelation,
  readRelations,
  relationsOfElement,
  shortNameOf,
} from "../src/client/relations-data.ts";

/** A record shaped like the dump's: identity only, no optional fields. */
const bare = {
  id: "r1",
  source: { model: "dshPlugins.skin" },
  target: { model: "dshHost" },
  title: "boot(require) 安装加载器",
};

/** A record with every optional field present. */
const full = {
  id: "r2",
  source: { model: "a" },
  target: { model: "b" },
  title: "calls",
  technology: "HTTP",
  description: { txt: "the long form" },
};

describe("shortNameOf", () => {
  it("takes the last dot-separated segment", () => {
    expect(shortNameOf("dshPlugins.skin.entry")).toBe("entry");
    expect(shortNameOf("dshPlugins")).toBe("dshPlugins");
    expect(shortNameOf("a.b.c.d")).toBe("d");
  });
});

describe("readRelation", () => {
  it("decodes a bare record and leaves absent fields null", () => {
    const relation = readRelation(bare, "r1");
    expect(relation).toEqual({
      id: "r1",
      source: "dshPlugins.skin",
      target: "dshHost",
      title: "boot(require) 安装加载器",
      technology: null,
      description: null,
    });
  });

  it("decodes a full record including the { txt } description form", () => {
    const relation = readRelation(full, "r2");
    expect(relation?.technology).toBe("HTTP");
    expect(relation?.description).toBe("the long form");
  });

  it("accepts a plain-string description as the export dumps write it", () => {
    const relation = readRelation({ ...full, description: "plain" }, "r2");
    expect(relation?.description).toBe("plain");
  });

  it("falls back to the record key when the record omits its id", () => {
    const relation = readRelation({ source: { model: "a" }, target: { model: "b" } }, "from-key");
    expect(relation?.id).toBe("from-key");
  });

  it("rejects a record that cannot be drawn", () => {
    // Not an object, no endpoints, or only one endpoint: a half relation has
    // nothing to render, so it is dropped rather than shown as a blank row.
    expect(readRelation(null, "x")).toBeNull();
    expect(readRelation("nope", "x")).toBeNull();
    expect(readRelation({ title: "orphan" }, "x")).toBeNull();
    expect(readRelation({ source: { model: "a" } }, "x")).toBeNull();
    expect(readRelation({ target: { model: "b" } }, "x")).toBeNull();
  });
});

describe("readRelations", () => {
  const catalogue = { r1: bare, r2: full };

  it("decodes the requested ids in the order the edge lists them", () => {
    const decoded = readRelations(catalogue, ["r2", "r1"]);
    expect(decoded.map(relation => relation.id)).toEqual(["r2", "r1"]);
  });

  it("drops unknown ids instead of rendering blanks", () => {
    const decoded = readRelations(catalogue, ["r1", "missing", "r2"]);
    expect(decoded.map(relation => relation.id)).toEqual(["r1", "r2"]);
  });

  it("returns nothing for a missing catalogue", () => {
    expect(readRelations(undefined, ["r1"])).toEqual([]);
    expect(readRelations({}, ["r1"])).toEqual([]);
  });
});

describe("readAllRelations", () => {
  it("decodes every usable entry", () => {
    const all = readAllRelations({ r1: bare, r2: full, bad: null });
    expect(all.map(relation => relation.id)).toEqual(["r1", "r2"]);
  });

  it("returns nothing for a missing catalogue", () => {
    expect(readAllRelations(undefined)).toEqual([]);
  });
});

describe("groupRelations", () => {
  it("splits by endpoint identity, not by count", () => {
    const relations = readRelations(
      {
        direct: { id: "direct", source: { model: "a" }, target: { model: "b" }, title: "same pair" },
        nested: { id: "nested", source: { model: "a.child" }, target: { model: "b" }, title: "from a child" },
      },
      ["direct", "nested"],
    );
    const groups = groupRelations(relations, "a", "b");
    expect(groups.direct.map(row => row.id)).toEqual(["direct"]);
    expect(groups.nested.map(row => row.id)).toEqual(["nested"]);
  });

  it("puts a single-relation edge in direct", () => {
    const groups = groupRelations(readRelations({ r1: bare }, ["r1"]), "dshPlugins.skin", "dshHost");
    expect(groups.direct).toHaveLength(1);
    expect(groups.nested).toHaveLength(0);
  });

  it("puts every relation of a fully nested aggregate in the nested group", () => {
    // The real aggregated edge: dshPlugins -> dshHost, whose 11 relations all
    // start at a nested child, so the direct group is legitimately empty.
    const relations = readRelations(
      {
        a: { id: "a", source: { model: "dshPlugins.skin.entry" }, target: { model: "dshHost" } },
        b: { id: "b", source: { model: "dshPlugins.jump.jumpEntry" }, target: { model: "dshHost" } },
      },
      ["a", "b"],
    );
    const groups = groupRelations(relations, "dshPlugins", "dshHost");
    expect(groups.direct).toHaveLength(0);
    expect(groups.nested).toHaveLength(2);
  });

  it("carries the short and full endpoint names for the capsules", () => {
    const groups = groupRelations(readRelations({ r1: bare }, ["r1"]), "dshPlugins.skin", "dshHost");
    const row = groups.direct[0];
    expect(row?.source.short).toBe("skin");
    expect(row?.source.full).toBe("dshPlugins.skin");
    expect(row?.target.short).toBe("dshHost");
  });
});

describe("relationsOfElement", () => {
  it("collects both directions and separates descendant-only relations", () => {
    const relations = readRelations(
      {
        out: { id: "out", source: { model: "a" }, target: { model: "b" }, title: "out" },
        in: { id: "in", source: { model: "c" }, target: { model: "a" }, title: "in" },
        child: { id: "child", source: { model: "a.child" }, target: { model: "d" }, title: "child" },
        unrelated: { id: "unrelated", source: { model: "x" }, target: { model: "y" } },
      },
      ["out", "in", "child", "unrelated"],
    );
    const groups = relationsOfElement(relations, "a");
    expect(groups.direct.map(row => row.id)).toEqual(["out", "in"]);
    expect(groups.nested.map(row => row.id)).toEqual(["child"]);
  });

  it("does not treat a prefix-sharing sibling as nested", () => {
    // `ab` must not count as a descendant of `a`; only a dot boundary does.
    const relations = readRelations(
      { r: { id: "r", source: { model: "ab" }, target: { model: "c" } } },
      ["r"],
    );
    const groups = relationsOfElement(relations, "a");
    expect(groups.direct).toHaveLength(0);
    expect(groups.nested).toHaveLength(0);
  });
});

// @vitest-environment jsdom
/**
 * The relations pane wired into the chrome: an edge press opens it, the three
 * dismissal paths close it, and the relations catalogue is fetched once.
 *
 * Drives the real renderer through the real mount point, so the assertions
 * cover the whole chain from a pointer press on an edge's hit path to the DOM
 * of the floating card.
 */
import { readFileSync } from "node:fs";
import { join } from "node:path";

import { beforeEach, describe, expect, it } from "vitest";

import { mountArchChrome, type MountArchView } from "../src/client/chrome.tsx";
import { mountArchDiagram } from "../src/client/entry.ts";
import { createDiagram } from "../src/client/chunk/diagram.ts";
import type { DiagramHandle, DiagramView } from "../src/client/chunk/diagram.ts";
import type { WireModelResponse, WireViewsResponse } from "../src/shared.ts";

interface DumpView {
  id: string;
  title: string | null;
  nodes: Array<{ id: string }>;
  edges: Array<{ id: string; source: string; target: string; relations?: string[] }>;
  bounds: { x: number; y: number; width: number; height: number };
}

const dump = JSON.parse(
  readFileSync(join(import.meta.dirname, "fixtures", "fixture-dump.json"), "utf8"),
) as {
  views: Record<string, DumpView>;
  elements: Record<string, unknown>;
  relations: Record<string, unknown>;
};

const view = (id: string): DiagramView => structuredClone(dump.views[id]) as unknown as DiagramView;

const loadRealChunk = async () => ({ createDiagram });

function jsonResponse(body: unknown, ok = true, status = 200): Response {
  return { ok, status, json: async () => body } as Response;
}

function viewsResponse(): WireViewsResponse {
  return {
    workspace: "/w/dsh-plugins",
    projectId: "dsh-plugins",
    views: [view("index")],
    hasErrors: false,
    errors: [],
  };
}

function modelResponse(): WireModelResponse {
  return {
    workspace: "/w/dsh-plugins",
    projectId: "dsh-plugins",
    elements: dump.elements,
    relations: dump.relations,
    specification: null,
  };
}

/** A fetch double that counts the model route, so caching is observable. */
function fakeFetch(): { fetch: typeof fetch; modelCalls: () => number } {
  let modelCalls = 0;
  const impl = ((input: RequestInfo | URL): Promise<Response> => {
    const url = String(input);
    if (url.includes("/arch/api/views")) return Promise.resolve(jsonResponse(viewsResponse()));
    if (url.includes("/arch/api/state")) return Promise.resolve(jsonResponse({ state: null, degraded: false }));
    if (url.includes("/arch/api/model")) {
      modelCalls += 1;
      return Promise.resolve(jsonResponse(modelResponse()));
    }
    return Promise.resolve(jsonResponse({ error: url }, false, 404));
  }) as typeof fetch;
  return { fetch: impl, modelCalls: () => modelCalls };
}

async function until(predicate: () => boolean, ticks = 80): Promise<void> {
  for (let index = 0; index < ticks; index += 1) {
    if (predicate()) return;
    await new Promise(resolve => setTimeout(resolve, 2));
  }
  expect(predicate()).toBe(true);
}

function mountHost(): HTMLElement {
  const dock = document.createElement("section");
  dock.setAttribute("data-workbench-dock", "term-dock");
  dock.setAttribute("data-dock-mode", "docked");
  const host = document.createElement("div");
  dock.append(host);
  document.body.append(dock);
  return host;
}

function capturingMount(): { mountView: MountArchView; handle: () => DiagramHandle | undefined } {
  let captured: DiagramHandle | undefined;
  const mountView: MountArchView = async (host, target, state, load, interactions) => {
    captured = await mountArchDiagram(host, target, state, load, interactions);
    return captured;
  };
  return { mountView, handle: () => captured };
}

/** The aggregated edge in the index view: dshPlugins -> dshHost, 11 relations. */
const AGGREGATED_EDGE = "7tzb4g";

beforeEach(() => {
  document.body.replaceChildren();
});

describe("relations pane wiring", () => {
  function panel(): { host: HTMLElement; handle: () => DiagramHandle | undefined; modelCalls: () => number } {
    const host = mountHost();
    const { fetch, modelCalls } = fakeFetch();
    const mount = capturingMount();
    mountArchChrome(host, {
      sessionId: "s1",
      fetchImpl: fetch,
      mountView: mount.mountView,
      load: loadRealChunk,
    });
    return { host, handle: mount.handle, modelCalls };
  }

  const hitOf = (host: HTMLElement, edgeId: string): SVGPathElement =>
    host.querySelector(`path.arch-edge-hit[data-edge-id="${edgeId}"]`) as SVGPathElement;

  it("opens the pane with both groups when an edge is pressed", async () => {
    const { host } = panel();
    await until(() => host.querySelector("path.arch-edge-hit") !== null);

    hitOf(host, AGGREGATED_EDGE).dispatchEvent(
      new PointerEvent("pointerdown", { clientX: 200, clientY: 200, cancelable: true, bubbles: true }),
    );
    await until(() => host.querySelector("[data-arch-relations]") !== null);

    const headings = [...host.querySelectorAll("[data-arch-relations-group]")].map(node => node.textContent);
    // This edge's 11 relations all start at nested children, so only the nested
    // group has rows; the direct group is correctly absent rather than empty.
    expect(headings).toEqual(["RESOLVED FROM NESTED"]);
    const rows = host.querySelectorAll("[data-arch-relation-row]");
    expect(rows).toHaveLength(11);
  });

  it("fetches the model catalogue once for repeated pane opens", async () => {
    const { host, modelCalls } = panel();
    await until(() => host.querySelector("path.arch-edge-hit") !== null);

    for (const edgeId of [AGGREGATED_EDGE, "1icru9q"]) {
      hitOf(host, edgeId).dispatchEvent(
        new PointerEvent("pointerdown", { clientX: 200, clientY: 200, cancelable: true, bubbles: true }),
      );
      await until(() => host.querySelector("[data-arch-relations]") !== null);
    }
    // One model fetch, reused: the cache is the point of relationsOf().
    expect(modelCalls()).toBe(1);
  });

  it("closes on Escape", async () => {
    const { host } = panel();
    await until(() => host.querySelector("path.arch-edge-hit") !== null);
    hitOf(host, AGGREGATED_EDGE).dispatchEvent(
      new PointerEvent("pointerdown", { clientX: 200, clientY: 200, cancelable: true, bubbles: true }),
    );
    await until(() => host.querySelector("[data-arch-relations]") !== null);

    // The chrome marks its own host element; the keydown listener is bound there.
    expect(host.hasAttribute("data-arch-chrome")).toBe(true);
    host.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true }));
    expect(host.querySelector("[data-arch-relations]")).toBeNull();
  });

  it("closes on the × button", async () => {
    const { host } = panel();
    await until(() => host.querySelector("path.arch-edge-hit") !== null);
    hitOf(host, AGGREGATED_EDGE).dispatchEvent(
      new PointerEvent("pointerdown", { clientX: 200, clientY: 200, cancelable: true, bubbles: true }),
    );
    await until(() => host.querySelector("[data-arch-relations]") !== null);

    (host.querySelector("[data-arch-relations-close]") as HTMLElement).click();
    expect(host.querySelector("[data-arch-relations]")).toBeNull();
  });

  it("closes when the blank canvas is pressed", async () => {
    const { host } = panel();
    await until(() => host.querySelector("path.arch-edge-hit") !== null);
    hitOf(host, AGGREGATED_EDGE).dispatchEvent(
      new PointerEvent("pointerdown", { clientX: 200, clientY: 200, cancelable: true, bubbles: true }),
    );
    await until(() => host.querySelector("[data-arch-relations]") !== null);

    // A press on the SVG itself (not on an edge or a node) is the blank canvas.
    (host.querySelector("svg") as SVGSVGElement).dispatchEvent(
      new PointerEvent("pointerdown", { clientX: 5, clientY: 5, cancelable: true, bubbles: true }),
    );
    expect(host.querySelector("[data-arch-relations]")).toBeNull();
  });

  it("opens the element pane from the browse button and marks the edge selected", async () => {
    const { host, handle } = panel();
    await until(() => host.querySelector("path.arch-edge-hit") !== null);

    hitOf(host, AGGREGATED_EDGE).dispatchEvent(
      new PointerEvent("pointerdown", { clientX: 200, clientY: 200, cancelable: true, bubbles: true }),
    );
    await until(() => host.querySelector("[data-arch-relations]") !== null);
    // The pressed edge is the selected one, so it stays thick and flowing.
    const visible = host.querySelector(`path.arch-edge-path[data-edge-id="${AGGREGATED_EDGE}"]`);
    expect(visible?.getAttribute("stroke-width")).toBe("2.5");

    handle()?.select("dshPlugins");
    await until(() => host.querySelector('[data-arch-action="relationships"]') !== null);
    (host.querySelector('[data-arch-action="relationships"]') as SVGGElement).dispatchEvent(
      new PointerEvent("pointerdown", { clientX: 200, clientY: 200, cancelable: true, bubbles: true }),
    );
    await until(() => host.querySelector("[data-arch-relations]") !== null);
    // The element pane lists the element's own relationships, both directions.
    expect(host.querySelectorAll("[data-arch-relation-row]").length).toBeGreaterThan(0);
  });
});

