/**
 * Route dispatch over a fake web server.
 *
 * Pins two product decisions: every arch route answers same-origin under the
 * registered prefix (no absolute URL survives), and a degraded store is a 200
 * with a flag, not an error — the client must keep working offline.
 */
import type { IncomingMessage, ServerResponse } from "node:http";

import { describe, expect, it } from "vitest";

import { registerArchRoutes, type ArchRouteDeps, type WebServerFace } from "../src/host/routes.ts";
import { ROUTE_PREFIX, type ArchStateChanges, type ArchWorkspaceState } from "../src/shared.ts";

type RouteHandler = Parameters<WebServerFace["register"]>[0]["handler"];

interface CapturedResponse {
  status: number;
  body: unknown;
}

function fakeWebServer(): { webServer: WebServerFace; registered: string[]; handler: () => RouteHandler } {
  const registered: string[] = [];
  let handler: RouteHandler | undefined;
  const webServer: WebServerFace = {
    register(route) {
      registered.push(`${route.kind} ${route.path}`);
      handler = route.handler;
      return () => {
        handler = undefined;
      };
    },
  };
  return { webServer, registered, handler: () => handler! };
}

const deps: ArchRouteDeps = {
  resolveWorkspaceRoot: async sessionId => (sessionId === "known" ? "/w/root" : undefined),
  loadViews: async workspace => ({ workspace, projectId: "p", views: [], hasErrors: false, errors: [] }),
  loadModel: async workspace => ({
    workspace,
    projectId: "p",
    elements: {},
    relations: {},
    specification: null,
  }),
  loadState: async () => undefined,
  saveState: async () => false,
};

async function request(
  handler: RouteHandler,
  method: string,
  url: string,
  body?: string,
): Promise<CapturedResponse> {
  const chunks = body === undefined ? [] : [Buffer.from(body, "utf8")];
  const req = {
    method,
    url,
    async *[Symbol.asyncIterator]() {
      yield* chunks;
    },
  };
  const captured: CapturedResponse = { status: 0, body: null };
  const res = {
    writeHead(status: number) {
      captured.status = status;
    },
    end(text: string) {
      captured.body = JSON.parse(text) as unknown;
    },
  };
  await handler(req as IncomingMessage, res as ServerResponse);
  return captured;
}

describe("registerArchRoutes", () => {
  const { webServer, registered, handler } = fakeWebServer();
  const disposer = registerArchRoutes(webServer, deps);

  it("registers exactly one prefix route at /arch/api", () => {
    expect(registered).toEqual([`prefix ${ROUTE_PREFIX}`]);
  });

  it("answers views for a known session", async () => {
    const captured = await request(handler(), "GET", "/arch/api/views?sessionId=known");
    expect(captured.status).toBe(200);
    expect(captured.body).toMatchObject({ workspace: "/w/root", projectId: "p" });
  });

  it("answers model for a known session", async () => {
    const captured = await request(handler(), "GET", "/arch/api/model?sessionId=known");
    expect(captured.status).toBe(200);
    expect(captured.body).toMatchObject({ workspace: "/w/root" });
  });

  it("rejects a missing sessionId with 400", async () => {
    const captured = await request(handler(), "GET", "/arch/api/views");
    expect(captured.status).toBe(400);
  });

  it("reports unknown sessions with 404", async () => {
    const captured = await request(handler(), "GET", "/arch/api/views?sessionId=nope");
    expect(captured.status).toBe(404);
  });

  it("reports a degraded store as 200 with a flag, not an error", async () => {
    const get = await request(handler(), "GET", "/arch/api/state?sessionId=known");
    expect(get.status).toBe(200);
    expect(get.body).toEqual({ state: null, degraded: true });

    const put = await request(
      handler(),
      "POST",
      "/arch/api/state",
      JSON.stringify({
        sessionId: "known",
        viewId: "index",
        viewports: { index: { scale: 0.8, tx: 0, ty: 0 } },
        offsets: {},
      }),
    );
    expect(put.status).toBe(200);
    expect(put.body).toEqual({ ok: false, degraded: true });
  });

  it("accepts the legacy single-viewport state body and migrates it per view", async () => {
    const saved: ArchWorkspaceState[] = [];
    const { webServer, handler: legacyHandler } = fakeWebServer();
    registerArchRoutes(webServer, {
      ...deps,
      loadState: async () => null,
      saveState: async (_workspace, state) => {
        saved.push(state);
        return true;
      },
    });
    const put = await request(
      legacyHandler(),
      "POST",
      "/arch/api/state",
      JSON.stringify({
        sessionId: "known",
        viewId: "skin",
        viewport: { scale: 0.6, tx: -40, ty: 12 },
        viewHash: "hash-1",
        offsets: { skin: { title: { dx: 4, dy: 0, baseX: 0, baseY: 8 } } },
      }),
    );
    expect(put.status).toBe(200);
    expect(put.body).toEqual({ ok: true, degraded: false });
    expect(saved[0]?.viewId).toBe("skin");
    expect(saved[0]?.viewports).toEqual({ skin: { scale: 0.6, tx: -40, ty: 12 } });
    expect(saved[0]?.offsets.skin?.title).toEqual({ dx: 4, dy: 0, baseX: 0, baseY: 8 });
  });

  it("forwards the touched slices to the store", async () => {
    const captured: Array<{ changes: ArchStateChanges | undefined }> = [];
    const { webServer, handler: changeHandler } = fakeWebServer();
    registerArchRoutes(webServer, {
      ...deps,
      loadState: async () => null,
      saveState: async (_workspace, _state, changes) => {
        captured.push({ changes });
        return true;
      },
    });
    const put = await request(
      changeHandler(),
      "POST",
      "/arch/api/state",
      JSON.stringify({
        sessionId: "known",
        viewId: "skin",
        viewports: { skin: { scale: 0.5, tx: 5, ty: 6 } },
        offsets: {},
        changes: { viewports: ["skin"], offsetViews: ["skin"], selection: true },
      }),
    );
    expect(put.status).toBe(200);
    expect(captured[0]?.changes).toEqual({ viewports: ["skin"], offsetViews: ["skin"], selection: true });
  });

  it("treats a body without changes as a full-state write", async () => {
    const captured: Array<{ changes: ArchStateChanges | undefined }> = [];
    const { webServer, handler: fullHandler } = fakeWebServer();
    registerArchRoutes(webServer, {
      ...deps,
      loadState: async () => null,
      saveState: async (_workspace, _state, changes) => {
        captured.push({ changes });
        return true;
      },
    });
    const put = await request(
      fullHandler(),
      "POST",
      "/arch/api/state",
      JSON.stringify({
        sessionId: "known",
        viewId: "index",
        viewports: { index: { scale: 0.8, tx: 0, ty: 0 } },
        offsets: {},
      }),
    );
    expect(put.status).toBe(200);
    expect(captured[0]?.changes).toBeUndefined();
  });

  it("drops a malformed change list instead of failing the save", async () => {
    const captured: Array<{ changes: ArchStateChanges | undefined }> = [];
    const { webServer, handler: badHandler } = fakeWebServer();
    registerArchRoutes(webServer, {
      ...deps,
      loadState: async () => null,
      saveState: async (_workspace, _state, changes) => {
        captured.push({ changes });
        return true;
      },
    });
    const put = await request(
      badHandler(),
      "POST",
      "/arch/api/state",
      JSON.stringify({
        sessionId: "known",
        viewId: "index",
        viewports: { index: { scale: 0.8, tx: 0, ty: 0 } },
        offsets: {},
        changes: { viewports: "nope", offsetViews: [1, "index"], selection: "yes" },
      }),
    );
    expect(put.status).toBe(200);
    expect(captured[0]?.changes).toEqual({ viewports: [], offsetViews: ["index"], selection: false });
  });

  it("rejects an array viewport container with 400", async () => {
    const captured = await request(
      handler(),
      "POST",
      "/arch/api/state",
      JSON.stringify({
        sessionId: "known",
        viewId: "index",
        viewports: [{ scale: 1, tx: 0, ty: 0 }],
        offsets: {},
      }),
    );
    expect(captured.status).toBe(400);
  });

  it("rejects a malformed state body with 400", async () => {
    const captured = await request(
      handler(),
      "POST",
      "/arch/api/state",
      JSON.stringify({ sessionId: "known", nonsense: true }),
    );
    expect(captured.status).toBe(400);
  });

  it("returns 404 for an unknown suffix", async () => {
    const captured = await request(handler(), "GET", "/arch/api/other?sessionId=known");
    expect(captured.status).toBe(404);
  });

  it("returns a disposer", () => {
    expect(typeof disposer).toBe("function");
  });
});

/**
 * Normalization of persisted workspace state: the per-view viewport shape, the
 * legacy single-viewport shape written before viewports were cached per view,
 * and the tolerated damage (one unreadable viewport costs that view's framing,
 * not every node offset stored beside it).
 */
import { describe, expect, it } from "vitest";

import {
  mergeArchWorkspaceState,
  readArchViewport,
  readArchWorkspaceState,
  type ArchWorkspaceState,
} from "../src/shared.ts";

describe("readArchViewport", () => {
  it("reads a finite scale/tx/ty triple", () => {
    expect(readArchViewport({ scale: 0.75, tx: 10, ty: -20 })).toEqual({ scale: 0.75, tx: 10, ty: -20 });
  });

  it("rejects non-numbers, NaN and infinities", () => {
    expect(readArchViewport(null)).toBeNull();
    expect(readArchViewport("viewport")).toBeNull();
    expect(readArchViewport({ scale: "1", tx: 0, ty: 0 })).toBeNull();
    expect(readArchViewport({ scale: Number.NaN, tx: 0, ty: 0 })).toBeNull();
    expect(readArchViewport({ scale: 1, tx: Number.POSITIVE_INFINITY, ty: 0 })).toBeNull();
    expect(readArchViewport({ scale: 1, tx: 0 })).toBeNull();
  });
});

describe("readArchWorkspaceState", () => {
  const offsets = { index: { user: { dx: 40, dy: 0, baseX: 100, baseY: 200 } } };

  it("reads the per-view shape", () => {
    const state = readArchWorkspaceState({
      viewId: "skin",
      viewports: {
        index: { scale: 0.75, tx: 10, ty: 20 },
        skin: { scale: 0.6, tx: -40, ty: 12 },
      },
      viewHash: "h1",
      offsets,
      updatedAt: "2026-11-01T00:00:00.000Z",
    });
    expect(state).toEqual({
      viewId: "skin",
      viewports: {
        index: { scale: 0.75, tx: 10, ty: 20 },
        skin: { scale: 0.6, tx: -40, ty: 12 },
      },
      viewHash: "h1",
      offsets,
      updatedAt: "2026-11-01T00:00:00.000Z",
    });
  });

  it("migrates the legacy single viewport onto the view it belonged to", () => {
    const state = readArchWorkspaceState({
      viewId: "skin",
      viewport: { scale: 0.6, tx: -40, ty: 12 },
      viewHash: "h1",
      offsets,
      updatedAt: "2026-11-01T00:00:00.000Z",
    });
    expect(state?.viewports).toEqual({ skin: { scale: 0.6, tx: -40, ty: 12 } });
    expect(state?.offsets).toEqual(offsets);
  });

  it("drops one unreadable viewport instead of the whole record", () => {
    const state = readArchWorkspaceState({
      viewId: "index",
      viewports: {
        index: { scale: 0.75, tx: 10, ty: 20 },
        broken: { scale: "nope", tx: 0, ty: 0 },
      },
      viewHash: "h1",
      offsets,
      updatedAt: "2026-11-01T00:00:00.000Z",
    });
    expect(state?.viewports).toEqual({ index: { scale: 0.75, tx: 10, ty: 20 } });
  });

  it("drops malformed node offsets one by one", () => {
    const state = readArchWorkspaceState({
      viewId: "index",
      viewports: {},
      offsets: {
        index: {
          user: { dx: 40, dy: 0, baseX: 100, baseY: 200 },
          broken: { dx: "nope", dy: 0, baseX: 0, baseY: 0 },
          alsoBroken: null,
        },
        notAView: "nope",
      },
    });
    expect(state?.offsets).toEqual({ index: { user: { dx: 40, dy: 0, baseX: 100, baseY: 200 } } });
  });

  it("rejects a record with no view id or no usable offsets", () => {
    expect(readArchWorkspaceState(null)).toBeNull();
    expect(readArchWorkspaceState({ viewports: {}, offsets })).toBeNull();
    expect(readArchWorkspaceState({ viewId: "index", viewports: {} })).toBeNull();
    expect(readArchWorkspaceState({ viewId: "index", offsets: [] })).toBeNull();
  });

  it("defaults a missing hash and stamps a missing updatedAt", () => {
    const state = readArchWorkspaceState({
      viewId: "index",
      viewports: {},
      offsets: {},
    });
    expect(state?.viewHash).toBe("");
    expect(typeof state?.updatedAt).toBe("string");
  });
});

describe("mergeArchWorkspaceState", () => {
  const stored: ArchWorkspaceState = {
    viewId: "index",
    viewports: {
      index: { scale: 0.6, tx: 1, ty: 2 },
      skin: { scale: 0.4, tx: 3, ty: 4 },
    },
    viewHash: "h1",
    offsets: {
      index: { user: { dx: 1, dy: 0, baseX: 10, baseY: 20 } },
      skin: { title: { dx: 2, dy: 0, baseX: 30, baseY: 40 } },
    },
    updatedAt: "2026-11-09T00:00:00.000Z",
  };
  const incoming: ArchWorkspaceState = {
    viewId: "skin",
    viewports: {
      index: { scale: 0.9, tx: 9, ty: 8 },
      skin: { scale: 0.5, tx: 5, ty: 6 },
    },
    viewHash: "h2",
    offsets: {
      index: { user: { dx: 99, dy: 0, baseX: 10, baseY: 20 } },
      skin: { title: { dx: 7, dy: 0, baseX: 30, baseY: 40 } },
    },
    updatedAt: "2026-11-10T00:00:00.000Z",
  };

  it("replaces only the slices the writer touched and keeps the rest stored", () => {
    const merged = mergeArchWorkspaceState(stored, incoming, {
      viewports: ["skin"],
      offsetViews: ["skin"],
      selection: false,
    });
    // The stale copy of `index` in the incoming snapshot must not roll back
    // what the stored record already holds.
    expect(merged.viewports.index).toEqual(stored.viewports.index);
    expect(merged.viewports.skin).toEqual(incoming.viewports.skin);
    expect(merged.offsets.index).toEqual(stored.offsets.index);
    expect(merged.offsets.skin).toEqual(incoming.offsets.skin);
    expect(merged.viewId).toBe(stored.viewId);
    expect(merged.viewHash).toBe(incoming.viewHash);
    expect(merged.updatedAt).toBe(incoming.updatedAt);
  });

  it("follows the reader's selection when the writer changed it", () => {
    const merged = mergeArchWorkspaceState(stored, incoming, { viewports: [], offsetViews: [], selection: true });
    expect(merged.viewId).toBe("skin");
  });

  it("ignores touched ids the incoming state does not carry", () => {
    const merged = mergeArchWorkspaceState(stored, incoming, {
      viewports: ["ghost"],
      offsetViews: ["ghost"],
      selection: false,
    });
    expect(merged.viewports).toEqual(stored.viewports);
    expect(merged.offsets).toEqual(stored.offsets);
  });
});

