  it("paints itself with the host's own theme tokens", () => {
    const sheet = LINK_HOVER_SHEET.replace(/\/\*[\s\S]*?\*\//g, "");
    const index = sheet.indexOf(`.${LINK_HOVER_PANEL_CLASS} {`);
