      "--dsw-radius-sm",
    ]);
    const referenced = [...LINK_HOVER_SHEET.matchAll(/var\((--dsw-[a-z0-9-]+)/g)].map(match => match[1] ?? "");
    expect(referenced.filter(token => !defined.has(token))).toEqual([]);
