/**
 * Watching for a new conversation page.
 *
 * The host renders an empty conversation as a hero page, and the only stable
 * way to tell "the reader just opened a new conversation" from "the reader is
 * looking at the one they already had" is the pair of attributes the host puts
 * on its content root: `data-content-phase` and `data-conversation-session`.
 * These tests drive that pair directly, because the module's whole job is the
 * transition between two values of it.
 *
 * The watcher is built over a real jsdom document and a real MutationObserver
 * from that document's own window, so the observation path is exercised rather
 * than mocked. Mutations are delivered asynchronously, hence the `settle` helper.
 */
import { JSDOM } from "jsdom";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import { createNewChatWatcher, type NewChatWatcherOptions } from "../src/client/new-chat-splash.ts";

let dom: JSDOM;
let doc: Document;

/** The host's content root, carrying the two attributes the watcher reads. */
function contentRoot(phase: string, session: string): HTMLElement {
  const element = doc.createElement("div");
  element.setAttribute("data-conversation-content", "");
  element.setAttribute("data-content-phase", phase);
  element.setAttribute("data-conversation-session", session);
  return element;
}

/** Let the document's MutationObserver deliver what has been queued. */
async function settle(): Promise<void> {
  await Promise.resolve();
  await new Promise((resolve) => setTimeout(resolve, 0));
}

function watcher(overrides: Partial<NewChatWatcherOptions> = {}) {
  const onOpen = vi.fn();
  const handle = createNewChatWatcher({
    doc,
    enabled: () => true,
    armed: () => true,
    busy: () => false,
    onOpen,
    ...overrides,
  });
  return { handle, onOpen };
}

beforeEach(() => {
  dom = new JSDOM("<!doctype html><html><body></body></html>", { url: "http://127.0.0.1/" });
  doc = dom.window.document;
});

afterEach(() => {
  dom.window.close();
});

describe("createNewChatWatcher", () => {
  it("opens once when the page becomes the hero page", async () => {
    const root = contentRoot("active", "s1");
    doc.body.append(root);
    const { handle, onOpen } = watcher();

    root.setAttribute("data-content-phase", "hero");
    await settle();

    expect(onOpen).toHaveBeenCalledTimes(1);
    handle.dispose();
  });

  it("does not open again while the same empty conversation stays on screen", async () => {
    // The host re-renders the hero page on unrelated state changes, and each of
    // those is a mutation. Only the transition into a new page is the event.
    const root = contentRoot("hero", "s1");
    doc.body.append(root);
    const { handle, onOpen } = watcher();

    root.setAttribute("data-content-phase", "hero");
    await settle();
    root.setAttribute("data-conversation-session", "s1");
    await settle();

    expect(onOpen).not.toHaveBeenCalled();
    handle.dispose();
  });

  it("opens when a second empty conversation replaces the first", async () => {
    // Consecutive new conversations never leave the hero phase, so the session
    // value is the only thing that changes between them.
    const root = contentRoot("hero", "s1");
    doc.body.append(root);
    const { handle, onOpen } = watcher();

    root.setAttribute("data-conversation-session", "s2");
    await settle();

    expect(onOpen).toHaveBeenCalledTimes(1);
    handle.dispose();
  });

  it("does not open when the hero page gains its first session id", async () => {
    // The host assigns the blank page its session id a moment after the hero
    // renders. That is the app opening a session, not the reader creating one:
    // the page was already there and nothing was replaced. Treating it as a new
    // conversation splashes once at every page load when the cold-start splash
    // is switched off.
    const root = contentRoot("hero", "s1");
    root.removeAttribute("data-conversation-session");
    doc.body.append(root);
    const { handle, onOpen } = watcher();

    root.setAttribute("data-conversation-session", "s1");
    await settle();

    expect(onOpen).not.toHaveBeenCalled();
    handle.dispose();
  });

  it("does nothing while the setting is off", async () => {
    const root = contentRoot("active", "s1");
    doc.body.append(root);
    const { handle, onOpen } = watcher({ enabled: () => false });

    root.setAttribute("data-content-phase", "hero");
    await settle();

    expect(onOpen).not.toHaveBeenCalled();
    handle.dispose();
  });

  it("does nothing before the cold start has finished", async () => {
    // The hero page the app opens on is the cold start's own page, not a new
    // conversation the reader asked for.
    const root = contentRoot("active", "s1");
    doc.body.append(root);
    const { handle, onOpen } = watcher({ armed: () => false });

    root.setAttribute("data-content-phase", "hero");
    await settle();

    expect(onOpen).not.toHaveBeenCalled();
    handle.dispose();
  });

  it("does not stack a second splash on top of one that is still up", async () => {
    const root = contentRoot("active", "s1");
    doc.body.append(root);
    const { handle, onOpen } = watcher({ busy: () => true });

    root.setAttribute("data-content-phase", "hero");
    await settle();

    expect(onOpen).not.toHaveBeenCalled();
    handle.dispose();
  });

  it("keeps watching after the host replaces its content root", async () => {
    // React remounts the conversation on a layout change, and the new element
    // carries none of the old one's identity. A watcher bound to the first node
    // would go quiet for the rest of the session.
    const first = contentRoot("active", "s1");
    doc.body.append(first);
    const { handle, onOpen } = watcher();

    const second = contentRoot("active", "s1");
    first.replaceWith(second);
    await settle();

    second.setAttribute("data-content-phase", "hero");
    await settle();

    expect(onOpen).toHaveBeenCalledTimes(1);
    handle.dispose();
  });

  it("survives a document with no content root at all", async () => {
    const { handle, onOpen } = watcher();

    // The root appears later, which is the normal case: the skin applies before
    // the shell has rendered anything, and the watcher must not have given up.
    const root = contentRoot("active", "s1");
    doc.body.append(root);
    await settle();

    root.setAttribute("data-content-phase", "hero");
    await settle();

    expect(onOpen).toHaveBeenCalledTimes(1);
    handle.dispose();
  });

  it("disposes idempotently and stops reporting", async () => {
    const root = contentRoot("active", "s1");
    doc.body.append(root);
    const { handle, onOpen } = watcher();

    handle.dispose();
    handle.dispose();

    root.setAttribute("data-content-phase", "hero");
    await settle();

    expect(onOpen).not.toHaveBeenCalled();
  });
});

/**
 * Finding and painting the shell's four surfaces.
 *
 * The shell is faked here in the shape the real one publishes: a frame element
 * whose children are the sidebar, the centre column, the right column and the
 * bottom row, with `data-rightbar-col` and `data-shell-bottom` as the two stable
 * anchors. The point of these tests is that the discovery is structural: it must
 * work with the shell's hashed class names and without them.
 */
import { JSDOM } from "jsdom";
import { beforeEach, describe, expect, it } from "vitest";

import {
  clearRegionPaint,
  clearRegions,
  locateRegions,
  paintRegions,
  REGION_ATTRIBUTE,
  regionsAreCurrent,
  stampRegions,
  type RegionSurfaces,
} from "../src/client/regions.ts";

let dom: JSDOM;

/**
 * Build a shell with the real layout's shape.
 *
 * The class names carry a fake hash, exactly like the host's: if discovery ever
 * starts depending on them, these tests keep passing for the wrong reason only
 * until the hash changes, so the attributes are what the assertions rely on.
 */
function buildShell(options: { collapsed?: boolean } = {}): Document {
  dom = new JSDOM(
    `<!doctype html><html><body>
      <div id="root">
        <div class="x_f1a2b_frame">
          ${options.collapsed === true ? "" : '<div class="x_f1a2b_sidebarCol" id="sidebar"></div>'}
          <div class="x_f1a2b_centerCol" id="main"></div>
          <div class="x_f1a2b_rightbarCol" id="rightbar" data-rightbar-col></div>
          <div class="x_f1a2b_bottomRow" id="bottom" data-shell-bottom></div>
        </div>
      </div>
    </body></html>`,
    { url: "http://127.0.0.1/" },
  );
  return dom.window.document;
}

describe("locateRegions", () => {
  it("finds all four surfaces from the two stable anchors", () => {
    const doc = buildShell();
    const regions = locateRegions(doc);
    expect(regions).not.toBeNull();
    expect(regions?.sidebar.id).toBe("sidebar");
    expect(regions?.main.id).toBe("main");
    expect(regions?.rightbar.id).toBe("rightbar");
    expect(regions?.bottom.id).toBe("bottom");
  });

  it("returns null when the shell is not there yet", () => {
    dom = new JSDOM("<!doctype html><html><body></body></html>", { url: "http://127.0.0.1/" });
    expect(locateRegions(dom.window.document)).toBeNull();
  });

  it("returns null rather than mislabelling a collapsed frame", () => {
    // With the sidebar gone, the frame's first child is the centre column; calling
    // that the sidebar would paint the main panel with the sidebar's settings.
    const doc = buildShell({ collapsed: true });
    expect(locateRegions(doc)).toBeNull();
  });
});

describe("stamping and painting", () => {
  let regions: RegionSurfaces;

  beforeEach(() => {
    const doc = buildShell();
    regions = locateRegions(doc) as RegionSurfaces;
    stampRegions(regions);
  });

  it("stamps each surface with its own key", () => {
    expect(regions.sidebar.getAttribute(REGION_ATTRIBUTE)).toBe("sidebar");
    expect(regions.main.getAttribute(REGION_ATTRIBUTE)).toBe("main");
    expect(regions.rightbar.getAttribute(REGION_ATTRIBUTE)).toBe("rightbar");
    expect(regions.bottom.getAttribute(REGION_ATTRIBUTE)).toBe("bottom");
    expect(regionsAreCurrent(regions)).toBe(true);
  });

  it("finds the surfaces stale once the shell replaced them", () => {
    const doc = buildShell();
    const replaced = locateRegions(doc) as RegionSurfaces;
    // A freshly discovered set is unstamped, so the old references are no longer
    // the elements the shell is showing.
    expect(regionsAreCurrent(replaced)).toBe(false);
  });

  it("paints each region's colour on the element and on the token its subtree reads", () => {
    paintRegions(regions, {
      sidebar: "#111111aa",
      main: "#222222bb",
      rightbar: "#333333cc",
      bottom: "#444444dd",
    });
    expect(regions.sidebar.style.backgroundColor).toBe("rgba(17, 17, 17, 0.667)");
    // The token override is what makes cards and panels inside the region agree
    // with the column they sit in.
    expect(regions.main.style.getPropertyValue("--dsw-alias-bg-base")).toBe("#222222bb");
    expect(regions.sidebar.style.getPropertyValue("--dsw-specific-sidebar-fill")).toBe("#111111aa");
  });

  it("drops the paint but keeps the stamps, so the surfaces stay claimed", () => {
    paintRegions(regions, {
      sidebar: "#111111aa",
      main: "#222222bb",
      rightbar: "#333333cc",
      bottom: "#444444dd",
    });
    clearRegionPaint(regions);

    expect(regions.sidebar.style.backgroundColor).toBe("");
    expect(regions.main.style.getPropertyValue("--dsw-alias-bg-base")).toBe("");
    // Still claimed: without this the shell observer would re-locate the four
    // surfaces on every frame it paints.
    expect(regionsAreCurrent(regions)).toBe(true);
  });

  it("leaves the host's own styling in charge after clearing", () => {
    paintRegions(regions, {
      sidebar: "#111111aa",
      main: "#222222bb",
      rightbar: "#333333cc",
      bottom: "#444444dd",
    });
    clearRegions(regions);

    expect(regions.sidebar.hasAttribute(REGION_ATTRIBUTE)).toBe(false);
    expect(regions.sidebar.style.backgroundColor).toBe("");
    // Removed, not written back to a remembered value: the host may have changed
    // its token since, and a stale copy would outrank the live one.
    expect(regions.main.style.getPropertyValue("--dsw-alias-bg-base")).toBe("");
  });
});

/**
 * The scene loader, at the seam where the bug lived.
 *
 * A piece module is `{ meta, default }` with two named exports. The built-in
 * salt-flat is imported as a namespace, but that is a property of one import
 * statement and easy to lose in a refactor, so the shape is asserted here rather
 * than trusted: the failure mode is a renderer crash at frame zero, which no
 * type checks and no other test would have caught.
 */
import { beforeEach, describe, expect, it } from "vitest";

import { chunkFile, chunkSpecifier, describeMismatch, forgetLoadedScenes, loadScene } from "../src/client/scenes.ts";
import { installLoader } from "../src/client/loader.ts";

beforeEach(() => {
  forgetLoadedScenes();
});

