/**
 * The colours the background canvas paints.
 *
 * The renderer fills the whole canvas with the piece's `ground` before it draws a
 * single glyph, so the ground is not a hint passed down for decoration: it is the
 * colour the reader sees wherever no character is. A piece mounted with the dark
 * ground on a light page paints a black slab over the paper surface the token
 * layer just made translucent, which is the bug this file exists to prevent.
 *
 * These tests mock the renderer because jsdom has no canvas context, and because
 * the piece handed to `mount` is the contract under test.
 */
import { JSDOM } from "jsdom";
import { beforeEach, describe, expect, it, vi } from "vitest";

const { mountSpy } = vi.hoisted(() => ({
  // Typed as a variadic so `mock.calls` keeps the arguments: the piece is the
  // second one, and reading it back is the whole point of this file.
  mountSpy: vi.fn((..._args: unknown[]) =>
    Object.assign(() => {}, {
      pause: () => {},
      resume: () => {},
      now: () => 0,
    }),
  ),
}));

vi.mock("../src/mount.ts", () => ({ mount: mountSpy }));

import { DUOTONE_PAPER, sceneColors, type LightMode } from "ascii-rest-scenes";

import { DARK_ATTRIBUTE, presentScene, type Presentation } from "../src/client/surface.ts";

/** A scene the renderer accepts: one static frame, one colour per cell. */
const SCENE = {
  id: "salt-flat",
  name: "salt flat",
  note: "a triangle over a mirror of salt",
  cols: 20,
  rows: 10,
  cell: 1,
  fps: 15,
  ground: "#000000",
  palette: ["#ffffff", "#888888", "#333333"],
  still: 0,
};

const module = {
  meta: SCENE,
  default: () => () => " ".repeat(SCENE.cols),
};

function presentation(overrides: Partial<Presentation> = {}): Presentation {
  return {
    scene: SCENE as unknown as Presentation["scene"],
    module: module as unknown as Presentation["module"],
    pieceOptions: {},
    opacity: 1,
    blur: 0,
    veil: 0.1,
    scrim: 0,
    scrimAngle: 180,
    still: false,
    fps: 0,
    resolution: 1,
    lightMode: "ink",
    pauseOnBlur: true,
    geometry: { fit: "cover", anchor: "center", zoom: 1 },
    ...overrides,
  };
}

let dom: JSDOM;
let doc: Document;

/** The piece the renderer was last handed, which is where the colours live. */
function mountedPiece(): { meta: { ground?: string; palette?: readonly string[] } } {
  const call = mountSpy.mock.calls[mountSpy.mock.calls.length - 1];
  if (call === undefined) throw new Error("the renderer was never mounted");
  return call[1] as unknown as { meta: { ground?: string; palette?: readonly string[] } };
}

const expected = (mode: LightMode) => sceneColors(SCENE, "light", mode);

beforeEach(() => {
  mountSpy.mockClear();
  dom = new JSDOM("<!doctype html><html><body></body></html>", {
    url: "http://127.0.0.1/",
    pretendToBeVisual: true,
  });
  doc = dom.window.document;
  const { window } = dom;
  window.ResizeObserver = class {
    observe(): void {}
    disconnect(): void {}
  } as unknown as typeof ResizeObserver;
  window.IntersectionObserver = class {
    observe(): void {}
    disconnect(): void {}
  } as unknown as typeof IntersectionObserver;
  window.matchMedia = ((query: string) => ({
    matches: false,
    media: query,
    addEventListener: () => {},
    removeEventListener: () => {},
    addListener: () => {},
    removeListener: () => {},
    onchange: null,
    dispatchEvent: () => false,
  })) as unknown as typeof matchMedia;
  (globalThis as unknown as { window: unknown }).window = window;
  (globalThis as unknown as { document: unknown }).document = doc;
});

describe("the canvas colours", () => {
  it("keeps the piece's own ground and palette in the dark scheme", () => {
    doc.body.setAttribute(DARK_ATTRIBUTE, "");
    const surface = presentScene(presentation(), doc);

    expect(mountedPiece().meta.ground).toBe(SCENE.ground);
    expect(mountedPiece().meta.palette).toEqual(SCENE.palette);
    surface.dispose();
  });

  it("turns the picture into ink on paper in the light scheme", () => {
    const surface = presentScene(presentation({ lightMode: "ink" }), doc);

    expect(mountedPiece().meta.ground).toBe(expected("ink").ground);
    expect(mountedPiece().meta.palette).toEqual(expected("ink").palette);
    surface.dispose();
  });

  it("paints the duotone plate's paper in the light scheme when that mode is chosen", () => {
    const surface = presentScene(presentation({ lightMode: "duotone" }), doc);

    expect(mountedPiece().meta.ground).toBe(DUOTONE_PAPER);
    expect(mountedPiece().meta.palette).toEqual(expected("duotone").palette);
    surface.dispose();
  });

  it("never hands the renderer the scene's dark ground on a light page", () => {
    for (const mode of ["ink", "duotone"] as const) {
      const surface = presentScene(presentation({ lightMode: mode }), doc);
      expect(mountedPiece().meta.ground).not.toBe(SCENE.ground);
      surface.dispose();
    }
  });

  it("re-mounts with the other scheme's colours when the host flips the theme", () => {
    const surface = presentScene(presentation(), doc);
    expect(mountedPiece().meta.ground).toBe(expected("ink").ground);

    doc.body.setAttribute(DARK_ATTRIBUTE, "");
    surface.rescheme();

    expect(mountedPiece().meta.ground).toBe(SCENE.ground);
    surface.dispose();
  });
});

/**
 * The splash layer: what it puts on the page, when it leaves, and what it does
 * when the scene will not mount.
 *
 * The layer is the first thing a reader sees on a cold start, so the timing is
 * the feature. These tests drive the clock by hand and assert the boundaries
 * (ready plus the minimum, the maximum wait, the fade itself) instead of
 * sleeping through them, which is the only way to catch an off-by-one on a
 * deadline that a reader would feel but never report.
 *
 * jsdom has no canvas context, so the renderer degrades to its detached handle:
 * the layer and its canvas still exist in the DOM, which is exactly what the
 * layer's own behaviour is about.
 */
import { JSDOM } from "jsdom";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import { sceneColors } from "ascii-rest-scenes";
import type { SceneModule } from "ascii-rest-scenes";

import { DEFAULT_SPLASH_TIMING, playSplash, type SplashOptions } from "../src/client/splash.ts";

let dom: JSDOM;
let doc: Document;

const SCENE = {
  id: "salt-flat",
  name: "salt flat",
  note: "the vercel triangle over a mirror of salt",
  cols: 20,
  rows: 10,
  cell: 1,
  fps: 15,
  ground: "#000000",
  palette: ["#ffffff", "#888888"],
  still: 0,
};

/** A scene module the renderer accepts: a factory returning one static frame. */
const MODULE = {
  meta: SCENE,
  default: () => () => " ".repeat(SCENE.cols),
};

/** A module whose factory throws, standing in for a chunk that will not play. */
const BROKEN_MODULE = {
  meta: SCENE,
  default: () => {
    throw new Error("ascii.rest: salt-flat has no piece");
  },
};

function splashOptions(overrides: Partial<SplashOptions> = {}): SplashOptions {
  return {
    doc,
    scene: SCENE as unknown as SplashOptions["scene"],
    module: MODULE as unknown as SplashOptions["module"],
    pieceOptions: {},
    lightMode: "ink",
    still: false,
    fps: 15,
    resolution: 1,
    ...overrides,
  };
}

/** The layer as it is on the page right now, or null once it is gone. */
function layer(): HTMLElement | null {
  return doc.querySelector("[data-ascii-rest-splash]");
}

/**
 * The colour a browser would report for a hex value.
 *
 * jsdom normalises `backgroundColor` to `rgb(...)`, so comparing against the
 * hex directly would assert jsdom's serialiser rather than the layer's colour.
 */
function rgbOf(hex: string): string {
  const probe = doc.createElement("div");
  probe.style.backgroundColor = hex;
  return probe.style.backgroundColor;
}

function stubMatchMedia(reducedMotion: boolean): void {
  const stub = ((query: string) => ({
    matches: reducedMotion && query.includes("prefers-reduced-motion"),
    media: query,
    addEventListener: () => {},
    removeEventListener: () => {},
    addListener: () => {},
    removeListener: () => {},
    onchange: null,
    dispatchEvent: () => false,
  })) as unknown as typeof matchMedia;
  (globalThis as unknown as { matchMedia: unknown }).matchMedia = stub;
  (dom.window as unknown as { matchMedia: unknown }).matchMedia = stub;
}

beforeEach(() => {
  vi.useFakeTimers();
  dom = new JSDOM("<!doctype html><html><body></body></html>", {
    url: "http://127.0.0.1/",
    pretendToBeVisual: true,
  });
  doc = dom.window.document;
  const { window } = dom;
  window.ResizeObserver = class {
    observe(): void {}
    disconnect(): void {}
  } as unknown as typeof ResizeObserver;
  window.IntersectionObserver = class {
    observe(): void {}
    disconnect(): void {}
  } as unknown as typeof IntersectionObserver;
  stubMatchMedia(false);
  // `splash.ts` reads the ambient `window` and `document`, the way `surface.ts`
  // does: in the browser they are the same realm as the page it paints into.
  (globalThis as unknown as { window: unknown }).window = window;
  (globalThis as unknown as { document: unknown }).document = doc;
  // The renderer also tests `el instanceof HTMLCanvasElement` against the bare
  // global, so the constructor has to be reachable without `window.`.
  (globalThis as unknown as { HTMLCanvasElement: unknown }).HTMLCanvasElement = window.HTMLCanvasElement;
  (globalThis as unknown as { devicePixelRatio: unknown }).devicePixelRatio = 1;

  Object.defineProperty(window.HTMLCanvasElement.prototype, "getContext", {
    configurable: true,
    value: () => null,
  });
});

afterEach(() => {
  vi.useRealTimers();
  dom.window.close();
});

describe("playSplash", () => {
  it("puts a full-screen layer on the page before it returns", () => {
    const splash = playSplash(splashOptions());
    const element = layer();

    expect(element).not.toBeNull();
    expect(splash.element).toBe(element);
    expect(element?.getAttribute("aria-hidden")).toBe("true");
    expect(element?.style.position).toBe("fixed");
    expect(element?.style.inset).toMatch(/^0(px)?$/);
    expect(element?.style.zIndex).toBe("2147483500");
    expect(element?.style.overflow).toBe("hidden");
    expect(element?.style.contain).toBe("strict");
    expect(element?.style.pointerEvents).toBe("auto");
    expect(element?.style.opacity).toBe("1");
    // The layer is opaque from the first frame: the boot page underneath is the
    // thing it exists to cover, so a transparent start would show both.
    expect(element?.style.backgroundColor).toBe(rgbOf(sceneColors(SCENE, "light", "ink").ground));
  });

  it("mounts the scene inside the layer, above the layer's own ground", () => {
    playSplash(splashOptions());
    const element = layer();
    const canvas = element?.querySelector("canvas");

    expect(canvas).not.toBeNull();
    // The scene layer is `presentScene`'s, which defaults to -1 so it can sit
    // behind the shell. Inside the splash there is nothing behind it to sit
    // behind, and a negative index would put it under the ground colour.
    expect((canvas?.parentElement as HTMLElement | null)?.style.zIndex).toBe("0");
  });

  it("stays put while the host is still showing its boot page", () => {
    doc.body.innerHTML = '<div data-dsh-boot></div>';
    playSplash(splashOptions());

    vi.advanceTimersByTime(3000);

    expect(layer()?.style.opacity).toBe("1");
  });

  it("stays put when the boot page is gone but the shell has not rendered", () => {
    playSplash(splashOptions());

    vi.advanceTimersByTime(3000);

    expect(layer()?.style.opacity).toBe("1");
  });

  it("fades once the shell is ready and the minimum has passed", () => {
    doc.body.innerHTML = '<div data-shell-bottom></div>';
    const onEnd = vi.fn();
    playSplash(splashOptions({ onEnd }));

    vi.advanceTimersByTime(DEFAULT_SPLASH_TIMING.minVisibleMs - DEFAULT_SPLASH_TIMING.pollMs);
    expect(layer()?.style.opacity).toBe("1");

    vi.advanceTimersByTime(DEFAULT_SPLASH_TIMING.pollMs);
    expect(layer()?.style.opacity).toBe("0");
    expect(layer()?.style.transition).toBe(`opacity ${String(DEFAULT_SPLASH_TIMING.fadeMs)}ms ease-out`);
    expect(onEnd).not.toHaveBeenCalled();

    vi.advanceTimersByTime(DEFAULT_SPLASH_TIMING.fadeMs);
    expect(layer()).toBeNull();
    expect(onEnd).toHaveBeenCalledTimes(1);
  });

  it("fades at the deadline even if the host never says it is ready", () => {
    doc.body.innerHTML = '<div data-dsh-boot></div>';
    const onEnd = vi.fn();
    playSplash(splashOptions({ onEnd }));

    vi.advanceTimersByTime(DEFAULT_SPLASH_TIMING.maxWaitMs);
    expect(layer()?.style.opacity).toBe("0");

    vi.advanceTimersByTime(DEFAULT_SPLASH_TIMING.fadeMs);
    expect(layer()).toBeNull();
    expect(onEnd).toHaveBeenCalledTimes(1);
  });

  it("disposes once, stops the clock, and never reports an end", () => {
    const onEnd = vi.fn();
    const splash = playSplash(splashOptions({ onEnd }));

    splash.dispose();
    splash.dispose();

    expect(layer()).toBeNull();
    expect(vi.getTimerCount()).toBe(0);

    vi.advanceTimersByTime(10_000);
    expect(onEnd).not.toHaveBeenCalled();
  });

  it("fades without a transition when the reader asked for less motion", () => {
    stubMatchMedia(true);
    doc.body.innerHTML = '<div data-shell-bottom></div>';
    const onEnd = vi.fn();
    playSplash(splashOptions({ onEnd }));

    vi.advanceTimersByTime(DEFAULT_SPLASH_TIMING.minVisibleMs);
    expect(layer()?.style.transition).toBe("opacity 0ms ease-out");
    expect(layer()?.style.opacity).toBe("0");

    vi.advanceTimersByTime(1);
    expect(layer()).toBeNull();
    expect(onEnd).toHaveBeenCalledTimes(1);
  });

  it("covers the page before the scene has even arrived", async () => {
    // The boot page is already painted when this runs, so the layer and its
    // ground cannot wait for a chunk fetch: only the canvas may.
    let deliver: (module: SceneModule) => void = () => {};
    const pending = new Promise<SceneModule>((resolve) => {
      deliver = resolve;
    });
    playSplash(splashOptions({ module: pending }));

    expect(layer()).not.toBeNull();
    expect(layer()?.style.backgroundColor).toBe(rgbOf(sceneColors(SCENE, "light", "ink").ground));
    expect(layer()?.querySelector("canvas")).toBeNull();

    deliver(MODULE as unknown as SceneModule);
    await Promise.resolve();

    expect(layer()?.querySelector("canvas")).not.toBeNull();
  });

  it("reports a scene promise that never delivers and leaves nothing behind", async () => {
    const onError = vi.fn();
    playSplash(splashOptions({ module: Promise.reject(new Error("chunk 404")), onError }));

    await Promise.resolve();
    await Promise.resolve();

    expect(onError).toHaveBeenCalledTimes(1);
    expect(layer()).toBeNull();
  });

  it("does not mount a scene that arrives after the layer was disposed", async () => {
    let deliver: (module: SceneModule) => void = () => {};
    const pending = new Promise<SceneModule>((resolve) => {
      deliver = resolve;
    });
    const splash = playSplash(splashOptions({ module: pending }));
    splash.dispose();

    deliver(MODULE as unknown as SceneModule);
    await Promise.resolve();

    expect(layer()).toBeNull();
  });

  it("honours a shorter minimum when the caller asks for one", () => {
    // A new conversation reuses this engine with the reader's own duration, so
    // the minimum has to be the caller's, not the cold start's.
    doc.body.innerHTML = '<div data-shell-bottom></div>';
    const onEnd = vi.fn();
    playSplash(splashOptions({ timing: { minVisibleMs: 600 }, onEnd }));

    vi.advanceTimersByTime(600 - DEFAULT_SPLASH_TIMING.pollMs);
    expect(layer()?.style.opacity).toBe("1");

    vi.advanceTimersByTime(DEFAULT_SPLASH_TIMING.pollMs);
    expect(layer()?.style.opacity).toBe("0");
    expect(onEnd).not.toHaveBeenCalled();

    vi.advanceTimersByTime(DEFAULT_SPLASH_TIMING.fadeMs);
    expect(layer()).toBeNull();
    expect(onEnd).toHaveBeenCalledTimes(1);
  });

  it("reports a scene that will not mount and leaves nothing behind", () => {
    const onError = vi.fn();
    const onEnd = vi.fn();
    playSplash(
      splashOptions({ module: BROKEN_MODULE as unknown as SplashOptions["module"], onError, onEnd }),
    );

    expect(onError).toHaveBeenCalledTimes(1);
    expect(layer()).toBeNull();

    // A failed splash is not a slow one: nothing is left polling behind it.
    vi.advanceTimersByTime(10_000);
    expect(onError).toHaveBeenCalledTimes(1);
    expect(onEnd).not.toHaveBeenCalled();
  });
});

/**
 * Repainting an already-mounted surface.
 *
 * The settings page and the tuning panel both reach the picture through
 * `restyle`, and every field it accepts has to reach `paintChrome`: a field that
 * is read in the type but never assigned leaves a live control that does nothing,
 * which is worse than having no control at all.
 *
 * The renderer needs a canvas and observers that jsdom lacks, so mounting here
 * fails by design (`onError` is called, the layer is torn down). These tests call
 * `restyle` on a surface built with no canvas context by asserting on the layer's
 * inline style instead, through a small fake element tree.
 */
import { JSDOM } from "jsdom";
import { beforeEach, describe, expect, it, vi } from "vitest";

import { presentScene, type Presentation } from "../src/client/surface.ts";

/**
 * A stand-in mount handle, so the focus switch can be observed.
 *
 * The real renderer cannot produce a handle here: jsdom has no canvas context
 * and no global `HTMLCanvasElement`, so `mount` throws and `presentScene` tears
 * the layer down having kept nothing. A stub is the only way to see which of
 * `pause`/`resume` the surface calls, and those calls are the whole subject of
 * the focus tests below.
 */
const handle = {
  pause: vi.fn(),
  resume: vi.fn(),
};

vi.mock("../src/mount.ts", () => ({
  mount: vi.fn(() => Object.assign(vi.fn(), { pause: handle.pause, resume: handle.resume, now: () => 0 })),
}));

let dom: JSDOM;
let doc: Document;

const SALT_FLAT = {
  id: "salt-flat",
  name: "salt flat",
  cols: 20,
  rows: 10,
  cell: 1,
  fps: 15,
  resolution: 1,
  ground: "#000000",
  palette: ["#ffffff", "#888888", "#333333"],
  options: {},
};

/** A scene module the renderer accepts: a factory returning one static frame. */
const module = {
  meta: SALT_FLAT,
  default: () => () => " ".repeat(SALT_FLAT.cols),
};

function presentation(overrides: Partial<Presentation> = {}): Presentation {
  return {
    scene: SALT_FLAT as unknown as Presentation["scene"],
    module: module as unknown as Presentation["module"],
    pieceOptions: {},
    opacity: 1,
    blur: 0,
    veil: 0.1,
    scrim: 0,
    scrimAngle: 180,
    still: false,
    fps: 0,
    resolution: 1,
    lightMode: "ink",
    pauseOnBlur: true,
    geometry: { fit: "cover", anchor: "center", zoom: 1 },
    ...overrides,
  };
}

/** The layer's scrim element, which is the last child by construction. */
function scrimOf(surface: { element: HTMLElement }): HTMLElement {
  const kids = [...surface.element.children];
  return kids[kids.length - 1] as HTMLElement;
}

/** Dispatch one of the two window events the focus switch listens for. */
function fire(type: "focus" | "blur"): void {
  dom.window.dispatchEvent(new dom.window.Event(type));
}

beforeEach(() => {
  // One handle is shared by every surface these tests build, so its counts have
  // to start from zero or they accumulate across cases.
  handle.pause.mockClear();
  handle.resume.mockClear();
  dom = new JSDOM("<!doctype html><html><body></body></html>", {
    url: "http://127.0.0.1/",
    pretendToBeVisual: true,
  });
  doc = dom.window.document;
  const { window } = dom;
  window.ResizeObserver = class {
    observe(): void {}
    disconnect(): void {}
  } as unknown as typeof ResizeObserver;
  window.IntersectionObserver = class {
    observe(): void {}
    disconnect(): void {}
  } as unknown as typeof IntersectionObserver;
  window.matchMedia = ((query: string) => ({
    matches: false,
    media: query,
    addEventListener: () => {},
    removeEventListener: () => {},
    addListener: () => {},
    removeListener: () => {},
    onchange: null,
    dispatchEvent: () => false,
  })) as unknown as typeof matchMedia;
  // `surface.ts` reads the ambient `window` (it runs in the browser, where the
  // document and the window are the same realm), so the test has to offer the
  // jsdom window as the global one before mounting.
  (globalThis as unknown as { window: unknown }).window = window;
  (globalThis as unknown as { document: unknown }).document = doc;

  // jsdom has no canvas context; the renderer reports the failure and tears the
  // layer down, so the tests below run against the layer while it exists.
  Object.defineProperty(window.HTMLCanvasElement.prototype, "getContext", {
    configurable: true,
    value: () => null,
  });
});

describe("restyle", () => {
  it("applies the scrim and its angle instead of leaving the mount-time value", () => {
    const surface = presentScene(presentation(), doc);
    const scrim = scrimOf(surface);
    expect(scrim.style.opacity).toBe("0");

    surface.restyle({
      opacity: 1,
      blur: 0,
      veil: 0.1,
      scrim: 0.8,
      scrimAngle: 90,
      still: false,
      fps: 0,
      resolution: 1,
      pauseOnBlur: true,
    });

    expect(scrim.style.opacity).toBe("0.8");
    expect(scrim.style.background).toContain("90deg");
    // The gradient has to be spelled in the ground's own colour, so the fade does
    // not pass through transparent black and grey the pale light scheme.
    expect(scrim.style.background).toContain("rgba");
    surface.dispose();
  });

  it("clears the gradient when the strength returns to zero", () => {
    const surface = presentScene(presentation({ scrim: 0.6 }), doc);
    expect(scrimOf(surface).style.background).not.toBe("");

    surface.restyle({
      opacity: 1,
      blur: 0,
      veil: 0.1,
      scrim: 0,
      scrimAngle: 180,
      still: false,
      fps: 0,
      resolution: 1,
      pauseOnBlur: true,
    });
    expect(scrimOf(surface).style.background).toBe("");
    surface.dispose();
  });

  it("binds and unbinds the focus listeners as the switch changes", () => {
    // Count the listeners by intercepting registration: jsdom offers no way to
    // read them back, and "the switch did nothing" is exactly the bug this
    // guards against.
    const bound = new Map<string, number>();
    const add = dom.window.addEventListener.bind(dom.window);
    const remove = dom.window.removeEventListener.bind(dom.window);
    dom.window.addEventListener = ((type: string, ...rest: unknown[]) => {
      bound.set(type, (bound.get(type) ?? 0) + 1);
      return (add as (...args: unknown[]) => void)(type, ...rest);
    }) as typeof dom.window.addEventListener;
    dom.window.removeEventListener = ((type: string, ...rest: unknown[]) => {
      bound.set(type, (bound.get(type) ?? 0) - 1);
      return (remove as (...args: unknown[]) => void)(type, ...rest);
    }) as typeof dom.window.removeEventListener;

    const surface = presentScene(presentation({ pauseOnBlur: true }), doc);
    expect(bound.get("blur")).toBe(1);
    expect(bound.get("focus")).toBe(1);

    const restyle = (pauseOnBlur: boolean): void =>
      surface.restyle({
        opacity: 1,
        blur: 0,
        veil: 0.1,
        scrim: 0,
        scrimAngle: 180,
        still: false,
        fps: 0,
        resolution: 1,
        pauseOnBlur,
      });

    restyle(false);
    expect(bound.get("blur")).toBe(0);
    expect(bound.get("focus")).toBe(0);

    // Turning it off twice must not go negative: `bindBlur` is idempotent.
    restyle(false);
    expect(bound.get("blur")).toBe(0);

    restyle(true);
    expect(bound.get("blur")).toBe(1);
    surface.dispose();
    // Disposal unbinds whatever is still bound.
    expect(bound.get("blur")).toBe(0);
  });

  it("pauses and resumes the frame loop, and survives a remount while paused", () => {
    // jsdom has no canvas context, so the renderer hands back its detached
    // handle: the calls are what this asserts, not the pixels. A pause that a
    // remount silently dropped would show the splash's own scene playing behind
    // a splash that is meant to be the only thing moving.
    const surface = presentScene(presentation({ fps: 15 }), doc);

    expect(() => {
      surface.pause();
      surface.pause();
      surface.resume();
      surface.resume();
    }).not.toThrow();

    // A density change re-mounts the renderer, which is the path that used to
    // start a fresh loop with no memory of the pause.
    surface.pause();
    surface.restyle({
      opacity: 1,
      blur: 0,
      veil: 0.1,
      scrim: 0,
      scrimAngle: 180,
      still: false,
      fps: 15,
      resolution: 2,
      pauseOnBlur: true,
    });
    expect(() => surface.resume()).not.toThrow();

    surface.dispose();
    // Disposal after a pause is the teardown path the splash takes.
    expect(() => {
      surface.pause();
      surface.resume();
    }).not.toThrow();
  });

  it("does not restart the frame loop on focus while the surface is held paused", () => {
    // Regression: the splash holds the background paused with `surface.pause()`,
    // but the focus listener only spoke to the mount handle. Losing and
    // regaining focus during the splash therefore resumed the loop underneath an
    // opaque layer, which is frames nobody can see. Focus is one reason to play,
    // not the only one, so it may not overrule a pause taken elsewhere.
    const surface = presentScene(presentation({ fps: 15 }), doc);

    surface.pause();
    expect(handle.pause).toHaveBeenCalledTimes(1);

    fire("focus");
    expect(handle.resume, "a paused surface stays paused through a focus").not.toHaveBeenCalled();

    // Blur keeps pausing the handle directly: that path was never the bug, and
    // it must not start routing through the surface's own state.
    fire("blur");
    expect(handle.pause).toHaveBeenCalledTimes(2);

    // Once the surface is genuinely resumed, focus plays again.
    surface.resume();
    handle.resume.mockClear();
    fire("focus");
    expect(handle.resume).toHaveBeenCalledTimes(1);

    surface.dispose();
  });
});

import { describe, expect, it } from "vitest";

import { parseHex, relativeLuminance } from "ascii-rest-scenes";
import { buildTokens, pickAccent, withAlpha } from "../src/client/tokens.ts";

const saltFlatPalette = [
  "#0d0d0e",
  "#ffffff",
  "#50e3c2",
  "#0070f3",
  "#7928ca",
  "#ff0080",
  "#ff4d4d",
  "#f9cb28",
];

const tokens = buildTokens({
  scene: { ground: "#000000", palette: saltFlatPalette },
  surfaceOpacity: 1,
  lightMode: "ink",
});

describe("withAlpha", () => {
  it("appends the alpha as a hex pair", () => {
    expect(withAlpha("#000000", 1)).toBe("#000000ff");
    expect(withAlpha("#000000", 0)).toBe("#00000000");
    expect(withAlpha("#0070f3", 0.5)).toBe("#0070f380");
  });

  it("clamps rather than emitting an invalid colour", () => {
    expect(withAlpha("#0070f3", -1)).toBe("#0070f300");
    expect(withAlpha("#0070f3", 9)).toBe("#0070f3ff");
  });
});

describe("buildTokens", () => {
  it("returns a light and a dark value for every token it claims", () => {
    for (const [name, pair] of Object.entries(tokens)) {
      expect(name.startsWith("--dsw-"), `${name} is a theme token`).toBe(true);
      expect(typeof pair.light, `${name} light`).toBe("string");
      expect(typeof pair.dark, `${name} dark`).toBe("string");
      expect(pair.light, `${name} light is usable`).not.toBe("");
      expect(pair.dark, `${name} dark is usable`).not.toBe("");
    }
  });

  it("covers the tokens the theme service requires both schemes for", () => {
    const required = [
      "--dsw-alias-bg-base",
      "--dsw-alias-bg-layer-1",
      "--dsw-alias-bg-layer-2",
      "--dsw-alias-bg-overlay",
      "--dsw-alias-border-l1",
      "--dsw-alias-border-l2",
      "--dsw-alias-brand-primary",
      "--dsw-alias-label-primary",
      "--dsw-alias-label-secondary",
      "--dsw-alias-state-error-primary",
      "--dsw-alias-state-idle-primary",
      "--dsw-alias-state-success-primary",
      "--dsw-alias-state-warn-primary",
      "--dsw-specific-sidebar-fill",
    ];
    for (const token of required) expect(tokens, token).toHaveProperty([token]);
  });

  it("makes the light base light and the dark base dark", () => {
    const light = parseHex(tokens["--dsw-alias-bg-base"]!.light.slice(0, 7));
    const dark = parseHex(tokens["--dsw-alias-bg-base"]!.dark.slice(0, 7));
    expect(light).not.toBeNull();
    expect(dark).not.toBeNull();
    if (light === null || dark === null) return;
    expect(relativeLuminance(light)).toBeGreaterThan(relativeLuminance(dark));
  });

  it("keeps the base translucent, so the picture is visible at all", () => {
    // A fully opaque base hides the whole surface, which makes the skin a no-op.
    for (const scheme of ["light", "dark"] as const) {
      const value = tokens["--dsw-alias-bg-base"]![scheme];
      expect(value, `${scheme} base carries an alpha`).toMatch(/^#[0-9a-f]{6}[0-9a-f]{2}$/i);
      const alpha = Number.parseInt(value.slice(7, 9), 16);
      expect(alpha, `${scheme} base is not opaque`).toBeLessThan(255);
      expect(alpha, `${scheme} base is not clear`).toBeGreaterThan(0);
    }
  });

  it("derives an accent from the picture instead of inventing one", () => {
    // salt-flat's most vivid entry is one of its saturated spectrum colours.
    const accent = tokens["--dsw-alias-brand-primary"]!.dark;
    expect(saltFlatPalette).toContain(accent);
    expect(pickAccent(saltFlatPalette, "dark")).toBe(accent);
  });

  it("keeps labels legible against both bases", () => {
    for (const scheme of ["light", "dark"] as const) {
      const base = parseHex(tokens["--dsw-alias-bg-base"]![scheme].slice(0, 7));
      const label = parseHex(tokens["--dsw-alias-label-primary"]![scheme]);
      expect(base).not.toBeNull();
      expect(label).not.toBeNull();
      if (base === null || label === null) continue;
      const baseL = relativeLuminance(base);
      const labelL = relativeLuminance(label);
      // The label must sit on the far side of the base, not next to it.
      expect(Math.abs(baseL - labelL), `${scheme} label separation`).toBeGreaterThan(0.5);
    }
  });

  it("honours a lower surface opacity by opening the surfaces further", () => {
    const clear = buildTokens({
      scene: { ground: "#000000", palette: saltFlatPalette },
      surfaceOpacity: 0.2,
      lightMode: "ink",
    });
    const alphaOf = (value: string): number => Number.parseInt(value.slice(7, 9), 16);
    expect(alphaOf(clear["--dsw-alias-bg-base"]!.dark)).toBeLessThan(
      alphaOf(tokens["--dsw-alias-bg-base"]!.dark),
    );
  });

  it("falls back to a brand colour when the palette has no usable accent", () => {
    const grey = buildTokens({
      scene: { ground: "#000000", palette: ["#000000", "#111111", "#222222"] },
      surfaceOpacity: 1,
      lightMode: "ink",
    });
    expect(grey["--dsw-alias-brand-primary"]!.dark).toMatch(/^#[0-9a-f]{6}$/i);
  });
});

/**
 * Executor tests.
 *
 * Every catalogue row ends in one client service call, so each case asserts the
 * call and, where it can fail, the sentence the reader sees instead. The failure
 * cases matter more than the happy ones: a panel action that fails silently is
 * the thing this layer exists to prevent.
 */

import { afterEach, describe, expect, it, vi } from "vitest";

import { failureCode, runCatalogAction, seatActions, type ActionDeps } from "../src/client/actions.ts";
import { copyFor } from "../src/client/copy.ts";
import type { HostShutdownRemote, RemoteResult, SlotEntry } from "../src/client/dsh.ts";
import type { ShutdownRequestResult } from "../src/shared.ts";
import { SESSION_A, SESSION_B, fakeSessions, fakeWorkspaces, sessionList, workspaceSnapshot } from "./fixtures.ts";

const copy = copyFor("zh");

interface Harness {
  readonly deps: ActionDeps;
  readonly notices: { readonly text: string; readonly tone: string }[];
  readonly closed: () => number;
  readonly inserted: () => readonly string[];
  readonly shortcutInvoke: ReturnType<typeof vi.fn>;
  readonly shutdownRequest: ReturnType<typeof vi.fn>;
}

interface HarnessOptions {
  readonly currentSessionId?: string | null;
  readonly sessionState?: ReturnType<typeof sessionList>;
  readonly pinned?: readonly string[];
  readonly insertOutcome?: "ok" | "no-session" | "failed";
  readonly seatEntries?: readonly SlotEntry[];
  readonly overlayEntries?: readonly SlotEntry[];
  readonly createThrows?: unknown;
  readonly archiveThrows?: unknown;
  readonly unarchiveThrows?: unknown;
  readonly openTabThrows?: unknown;
  readonly colorScheme?: "light" | "dark";
  /**
   * The remote shutdown face; `null` means the namespace is absent, `undefined`
   * (left out) installs a face answering `requested`.
   */
  readonly shutdownFace?: HostShutdownRemote | null;
  /** What the installed face answers; meaningless without a face. */
  readonly shutdownResult?: ShutdownRequestResult;
  /** Make the installed face reject, standing in for a transport failure. */
  readonly shutdownThrows?: unknown;
  /** Make the installed face answer a business failure instead of a value. */
  readonly shutdownError?: { readonly code: string };
  readonly absent?: readonly ("uiWorkspace" | "layout" | "theme" | "pluginNavigation" | "sidebarRight" | "slots" | "workspaces" | "sessions" | "shortcuts")[];
  readonly invokeThrows?: unknown;
}

function harness(options: HarnessOptions = {}): Harness {
  const notices: { text: string; tone: string }[] = [];
  let closedCount = 0;
  const inserted: string[] = [];
  const state = options.sessionState ?? sessionList([SESSION_A, SESSION_B]);
  const absent = new Set(options.absent ?? []);

  const sessions = absent.has("sessions")
    ? undefined
    : fakeSessions(state, {
        createThrows: options.createThrows,
        face: { cancel: async (): Promise<RemoteResult<unknown>> => ({ ok: true, value: {} }) },
      });
  const workspaces = absent.has("workspaces")
    ? undefined
    : fakeWorkspaces({ ...workspaceSnapshot(), pinnedSessionIds: options.pinned ?? [] });
  const layout = absent.has("layout") ? undefined : { toggleSidebar: vi.fn() };
  const theme = absent.has("theme")
    ? undefined
    : {
        getTheme: () => ({
          preference: options.colorScheme ?? "dark",
          active: { id: "x", colorScheme: options.colorScheme ?? "dark" },
        }),
        setTheme: vi.fn(),
      };
  const pluginNavigation = absent.has("pluginNavigation")
    ? undefined
    : { openList: vi.fn(), openBundle: vi.fn() };
  const sidebarRight = absent.has("sidebarRight")
    ? undefined
    : {
        mounted: { getSnapshot: () => SESSION_A.id as string | undefined, subscribe: () => () => undefined },
        openTab: vi.fn(() => {
          if (options.openTabThrows !== undefined) throw options.openTabThrows;
        }),
        toggleExpanded: vi.fn(),
        isExpanded: () => false,
      };
  const slots = absent.has("slots")
    ? undefined
    : {
        inject: () => () => undefined,
        register: () => () => undefined,
        entries: (key: string) =>
          key === "sidebar.settings"
            ? (options.seatEntries ?? [])
            : key === "shell.overlay"
              ? (options.overlayEntries ?? [])
              : [],
      };
  const shortcutInvoke = vi.fn(() => {
    if (options.invokeThrows !== undefined) throw options.invokeThrows;
  });
  const shortcuts = absent.has("shortcuts")
    ? undefined
    : { registry: { invoke: shortcutInvoke as (id: string, context: unknown) => void } };

  const uiWorkspace = {
    openSession: vi.fn(),
    startSession: vi.fn(),
    archiveSession: vi.fn(async () => {
      if (options.archiveThrows !== undefined) throw options.archiveThrows;
    }),
    unarchiveSession: vi.fn(async () => {
      if (options.unarchiveThrows !== undefined) throw options.unarchiveThrows;
    }),
    forkSession: vi.fn(async () => "sess-forked"),
    pinSession: vi.fn(async () => undefined),
    unpinSession: vi.fn(async () => undefined),
  };

  /**
   * The remote shutdown call, recorded so cases can assert exactly one fire.
   * The harness installs no other channel: there is no `appExit` anywhere in
   * reach, which is the point of the executor contract.
   */
  const shutdownRequest = vi.fn(async (): Promise<RemoteResult<ShutdownRequestResult>> => {
    if (options.shutdownThrows !== undefined) throw options.shutdownThrows;
    if (options.shutdownError !== undefined) return { ok: false, error: { code: options.shutdownError.code } };
    return { ok: true, value: options.shutdownResult ?? "requested" };
  });
  const shutdownAvailable = vi.fn(async (): Promise<RemoteResult<boolean>> => ({ ok: true, value: true }));
  const shutdownFace: HostShutdownRemote | undefined =
    options.shutdownFace === null
      ? undefined
      : (options.shutdownFace ?? { available: shutdownAvailable, request: shutdownRequest });

  const deps: ActionDeps = {
    sessions: () => sessions,
    workspaces: () => workspaces,
    uiWorkspace: () => (absent.has("uiWorkspace") ? undefined : uiWorkspace),
    layout: () => layout,
    theme: () => theme,
    pluginNavigation: () => pluginNavigation,
    sidebarRight: () => sidebarRight,
    slots: () => slots,
    shortcuts: () => shortcuts as never,
    shutdownRequest: () => shutdownFace,
    currentSessionId: () => options.currentSessionId === undefined ? SESSION_A.id : options.currentSessionId,
    insert: text => {
      inserted.push(text);
      return options.insertOutcome ?? "ok";
    },
    close: () => {
      closedCount += 1;
    },
    notify: (text, tone = "info") => {
      notices.push({ text, tone });
    },
    copy: () => copy,
  };

  return { deps, notices, closed: () => closedCount, inserted: () => inserted, shortcutInvoke, shutdownRequest };
}

/** A seat whose `create()` returns the given actions. */
function seat(actions: Record<string, () => void>, id?: string): SlotEntry {
  return { options: id === undefined ? undefined : { id }, store: { create: () => ({ actions }) } };
}

describe("create-session", () => {
  it("delegates workspace creation to startSession, which inherits the current workspace", async () => {
    const h = harness();
    await runCatalogAction({ kind: "create-session", scope: "workspace" }, h.deps);
    expect(h.deps.uiWorkspace()!.startSession).toHaveBeenCalledWith();
    expect(h.closed()).toBe(1);
    expect(h.notices).toEqual([]);
  });

  it("hands a named workspace to startSession when the row carries one", async () => {
    const h = harness();
    await runCatalogAction(
      { kind: "create-session", scope: "workspace", workspaceId: "ws-nine" },
      h.deps,
    );
    expect(h.deps.uiWorkspace()!.startSession).toHaveBeenCalledWith("ws-nine");
    expect(h.closed()).toBe(1);
  });

  it("needs the current session's directory for an ungrouped session", async () => {
    const h = harness({ currentSessionId: null });
    await runCatalogAction({ kind: "create-session", scope: "ungrouped" }, h.deps);
    expect(h.notices[0]?.text).toBe(copy.actions.needsCwd);
    expect(h.closed()).toBe(0);
  });

  it("reports a failed creation instead of closing quietly", async () => {
    const h = harness({ createThrows: { rpcError: { code: "workspace/not-found" } } });
    await runCatalogAction({ kind: "create-session", scope: "ungrouped" }, h.deps);
    expect(h.notices[0]?.text).toBe(copy.actions.failed(copy.actionLabels["session.newUngrouped"]!, "workspace/not-found"));
    expect(h.notices[0]?.tone).toBe("error");
  });
});

describe("copy-session-id", () => {
  afterEach(() => vi.unstubAllGlobals());

  it("copies the current session ID and confirms success", async () => {
    const writeText = vi.fn().mockResolvedValue(undefined);
    vi.stubGlobal("navigator", { clipboard: { writeText } });
    const h = harness({ currentSessionId: "session-current" });
    expect(await runCatalogAction({ kind: "copy-session-id" }, h.deps)).toBe(true);
    expect(writeText).toHaveBeenCalledExactlyOnceWith("session-current");
    expect(h.closed()).toBe(1);
    expect(h.notices).toEqual([{ text: copy.actions.sessionIdCopied, tone: "info" }]);
  });

  it("keeps the panel open on rejected or unavailable clipboard access", async () => {
    for (const clipboard of [{ writeText: vi.fn().mockRejectedValue(new Error("denied")) }, undefined]) {
      vi.stubGlobal("navigator", { clipboard });
      const h = harness();
      await runCatalogAction({ kind: "copy-session-id" }, h.deps);
      expect(h.closed()).toBe(0);
      expect(h.notices).toEqual([{ text: copy.actions.sessionIdCopyFailed, tone: "error" }]);
    }
  });

  it("does not write if the session disappears before selection", async () => {
    const writeText = vi.fn();
    vi.stubGlobal("navigator", { clipboard: { writeText } });
    const h = harness({ currentSessionId: null });
    await runCatalogAction({ kind: "copy-session-id" }, h.deps);
    expect(writeText).not.toHaveBeenCalled();
    expect(h.closed()).toBe(0);
    expect(h.notices).toEqual([{ text: copy.actions.sessionIdNoSession, tone: "error" }]);
  });
});

