    const h = harness();
    expect(await runCatalogAction({ kind: "open-mode", mode: "navigate" }, h.deps)).toBe(false);
    expect(await runCatalogAction({ kind: "open-session", sessionId: "sess-a" }, h.deps)).toBe(false);
    expect(h.closed()).toBe(0);
