/**
 * Host-half tests for the filesystem exploration service.
 *
 * Driven the way the seams doc prescribes: the class method directly, against
 * real directories in tmp, with no mocks inside. Every case pins a product
 * decision the panel's absolute-path branch stands on.
 */

import { chmod, mkdir, mkdtemp, realpath, rm, symlink, writeFile } from "node:fs/promises";
import { homedir, tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { Context } from "@deepseek-ai/cordis";
import { remoteMethods } from "@deepseek-ai/dsh-typert-protocol";

import { PathExplorerService, PATH_SERVICE } from "../src/index.ts";

let root: string;
const explorer = new PathExplorerService(new Context());

beforeEach(async () => {
  root = await mkdtemp(join(tmpdir(), "dcp-paths-"));
});

afterEach(async () => {
  await chmod(root, 0o755).catch(() => undefined);
  await rm(root, { recursive: true, force: true }).catch(() => undefined);
});

describe("PathExplorerService activation", () => {
  it("publishes one resolve endpoint and waits on no host service", () => {
    expect(PathExplorerService.inject).toEqual([]);
    const markers = remoteMethods(new PathExplorerService(new Context()));
    expect(markers.map(marker => marker.exportName ?? marker.method)).toEqual(["resolve", "inspect"]);
    expect(PATH_SERVICE).toBe("pathExplorer");
  });
});

describe("listing symlinks", () => {
  it("reports a link as what it points at and carries the target", async () => {
    const base = await realpath(root);
    await mkdir(join(root, "real-dir"));
    await writeFile(join(root, "real.md"), "x");
    await symlink(join(root, "real-dir"), join(root, "dir-link"));
    await symlink(join(root, "real.md"), join(root, "file-link"));

    const result = await explorer.resolve({ query: `${root}/` });
    if (!result.ok) throw new Error("unreachable");
    const byPath = new Map(result.entries.map(entry => [entry.path, entry]));

    // A directory link lists as a directory, or the tree cursor could never
    // enter it; the target is what both the cursor and the sidebar follow.
    expect(byPath.get(join(root, "dir-link"))).toMatchObject({
      kind: "directory",
      link: join(base, "real-dir"),
    });
    expect(byPath.get(join(root, "file-link"))).toMatchObject({
      kind: "file",
      link: join(base, "real.md"),
    });
  });

  it("answers the typed path itself the same way", async () => {
    const base = await realpath(root);
    await writeFile(join(root, "real.md"), "x");
    await symlink(join(root, "real.md"), join(root, "link.md"));

    const result = await explorer.resolve({ query: join(root, "link.md") });
    if (!result.ok) throw new Error("unreachable");

    expect(result.entries[0]).toMatchObject({ path: join(root, "link.md"), kind: "file", link: join(base, "real.md") });
  });
});

describe("inspect", () => {
  /** The temporary root with its links resolved, which is what the answer reports. */
  async function canonical(): Promise<string> {
    return await realpath(root);
  }

  it("names what a plain path is, including a path that is gone", async () => {
    await writeFile(join(root, "a.md"), "x");
    await mkdir(join(root, "notes"));

    expect(await explorer.inspect({ path: join(root, "a.md") })).toEqual({ kind: "file" });
    expect(await explorer.inspect({ path: join(root, "notes") })).toEqual({ kind: "directory" });
    expect(await explorer.inspect({ path: join(root, "nothing.md") })).toEqual({ kind: "missing" });
  });

  it("resolves one link and reports what it points at", async () => {
    // The host's file reads refuse a final symlink, so this answer is the only
    // way a surface can show the file behind one.
    const target = join(root, "AGENTS.md");
    await writeFile(target, "x");
    await symlink(target, join(root, "CLAUDE.md"));

    expect(await explorer.inspect({ path: join(root, "CLAUDE.md") })).toEqual({
      kind: "symlink",
      target: await canonical().then(base => join(base, "AGENTS.md")),
      targetKind: "file",
    });
  });

  it("keeps a dangling link a link, with nowhere to send the reader", async () => {
    await symlink(join(root, "nothing.md"), join(root, "gone.md"));

    const answer = await explorer.inspect({ path: join(root, "gone.md") });

    expect(answer.kind).toBe("symlink");
    expect(answer.target).toBeUndefined();
  });

  it("reports a directory link as a link, not as a walkable directory", async () => {
    await mkdir(join(root, "real-dir"));
    await symlink(join(root, "real-dir"), join(root, "dir-link"));

    const answer = await explorer.inspect({ path: join(root, "dir-link") });

    expect(answer.kind).toBe("symlink");
    expect(answer.targetKind).toBe("directory");
  });

  it("refuses a relative path as a contract breach", async () => {
    await expect(explorer.inspect({ path: "a.md" })).rejects.toThrow(/absolute/);
  });
});

describe("resolve", () => {
  it("lists a directory's direct children unfiltered, directories first", async () => {
    await mkdir(join(root, "notes"));
    await writeFile(join(root, "b.txt"), "");
    await writeFile(join(root, "a.md"), "");

    const result = await explorer.resolve({ query: `${root}/` });

    expect(result).toMatchObject({ ok: true, home: homedir() });
    if (!result.ok) throw new Error("unreachable");
    expect(result.entries.map(entry => [entry.path, entry.kind, entry.exists])).toEqual([
      [`${root}/notes`, "directory", true],
      [`${root}/a.md`, "file", true],
      [`${root}/b.txt`, "file", true],
    ]);
  });

  it("prefix-filters children on the last segment, case-insensitively", async () => {
    await mkdir(join(root, "notes"));
    await writeFile(join(root, "note.md"), "");
    await writeFile(join(root, "README.md"), "");
    await writeFile(join(root, "other.ts"), "");

    const result = await explorer.resolve({ query: `${root}/NOT` });

    if (!result.ok) throw new Error("unreachable");
    expect(result.entries.map(entry => entry.path)).toEqual([`${root}/notes`, `${root}/note.md`]);
  });

  it("keeps the typed path's own row when it already exists", async () => {
    await mkdir(join(root, "notes"));
    await writeFile(join(root, "note.md"), "");

    const result = await explorer.resolve({ query: `${root}/note.md` });

    if (!result.ok) throw new Error("unreachable");
    expect(result.entries).toEqual([{ path: `${root}/note.md`, kind: "file", exists: true }]);
  });

  it("expands a tilde to the home directory, bare or with a path", async () => {
    const home = homedir();
    const bare = await explorer.resolve({ query: "~" });
    const withSlash = await explorer.resolve({ query: "~/" });

    for (const result of [bare, withSlash]) {
      if (!result.ok) throw new Error("unreachable");
      expect(result.home).toBe(home);
      expect(result.entries.every(entry => entry.path.startsWith(`${home}/`))).toBe(true);
    }
  });

  it("answers an empty list for a path that does not exist", async () => {
    const result = await explorer.resolve({ query: `${root}/missing/deep` });
    expect(result).toMatchObject({ ok: true });
    if (!result.ok) throw new Error("unreachable");
    expect(result.entries).toEqual([]);
  });

  it("rejects queries that cannot name a filesystem location", async () => {
    await expect(explorer.resolve({ query: "bareword" })).resolves.toMatchObject({
      ok: false,
      error: { code: "invalid-request" },
    });
    await expect(explorer.resolve({ query: "relative/path" })).resolves.toMatchObject({
      ok: false,
      error: { code: "invalid-request" },
    });
  });

  it("truncates the filtered answer to the default limit", async () => {
    for (let index = 0; index < 25; index += 1) {
      await writeFile(join(root, `f${String(index).padStart(2, "0")}.txt`), "");
    }

    const result = await explorer.resolve({ query: `${root}/f` });

    if (!result.ok) throw new Error("unreachable");
    expect(result.entries).toHaveLength(20);
  });

  it("degrades an unreadable directory to no children instead of failing", async () => {
    const guarded = join(root, "guarded");
    await mkdir(guarded);
    await chmod(guarded, 0o000);

    const result = await explorer.resolve({ query: `${guarded}/` });

    expect(result).toMatchObject({ ok: true });
    if (!result.ok) throw new Error("unreachable");
    expect(result.entries).toEqual([]);
  });
});

describe("resolve: relative bases and dotted segments", () => {
  it("climbs one level for a leading .. against the session base", async () => {
    await mkdir(join(root, "outer", "inner"), { recursive: true });
    await writeFile(join(root, "outer", "readme.md"), "");

    const result = await explorer.resolve({ query: "../rea", base: join(root, "outer", "inner") });

    if (!result.ok) throw new Error("unreachable");
    expect(result.entries.map(entry => entry.path)).toEqual([join(root, "outer", "readme.md")]);
  });

  it("lists the parent itself when the query is a bare ..", async () => {
    await mkdir(join(root, "outer", "inner"), { recursive: true });
    await writeFile(join(root, "outer", "readme.md"), "");

    const result = await explorer.resolve({ query: "..", base: join(root, "outer", "inner") });

    if (!result.ok) throw new Error("unreachable");
    // The parent's children, base itself included, directories first.
    expect(result.entries.map(entry => entry.path)).toEqual([
      join(root, "outer", "inner"),
      join(root, "outer", "readme.md"),
    ]);
  });

  it("folds dotted segments out of an absolute query before splitting", async () => {
    await mkdir(join(root, "nested"));
    await writeFile(join(root, "sib.txt"), "");

    const result = await explorer.resolve({ query: `${root}/nested/../sib` });

    if (!result.ok) throw new Error("unreachable");
    expect(result.entries.map(entry => entry.path)).toEqual([join(root, "sib.txt")]);
  });

  it("refuses a relative query without a base", async () => {
    const result = await explorer.resolve({ query: "../sibling" });

    expect(result).toMatchObject({ ok: false, error: { code: "invalid-request" } });
  });
});

