import { describe, expect, it } from "vitest";

import {
  composeInsertion,
  displayPath,
  escapesWorkspace,
  hexRefQuery,
  isAbsolutePath,
  isTypedAbsolutePath,
  separatorOf,
  tildeForm,
  toAbsolutePath,
} from "../src/client/paths.ts";

/**
 * The navigation mode's only irreversible step is writing into the composer, and
 * the two ways to get it wrong are a glued path and a Windows path built with
 * the wrong separator. Both are decided here.
 */

describe("toAbsolutePath", () => {
  const cwd = "/Users/lionad/Github/Lionad-Morotar/dsh-plugins";

  it("joins a relative candidate onto the session cwd", () => {
    expect(toAbsolutePath(cwd, "src/client/panel.ts")).toBe(`${cwd}/src/client/panel.ts`);
  });

  it("keeps a directory candidate's trailing separator", () => {
    expect(toAbsolutePath(cwd, "src/client/")).toBe(`${cwd}/src/client/`);
  });

  it("strips a leading ./ before joining", () => {
    expect(toAbsolutePath(cwd, "./README.md")).toBe(`${cwd}/README.md`);
  });

  it("leaves an absolute candidate untouched", () => {
    expect(toAbsolutePath(cwd, "/etc/hosts")).toBe("/etc/hosts");
  });

  it("does not duplicate the separator when cwd ends with one", () => {
    expect(toAbsolutePath("/tmp/", "a.txt")).toBe("/tmp/a.txt");
  });

  it("joins against a filesystem root without doubling slashes", () => {
    expect(toAbsolutePath("/", "a.txt")).toBe("/a.txt");
  });

  it("uses backslashes for a Windows cwd", () => {
    const windows = "C:\\Users\\lionad\\project";
    expect(toAbsolutePath(windows, "src/a.ts")).toBe(`${windows}\\src\\a.ts`);
  });

  it("treats a drive-rooted candidate as absolute", () => {
    expect(toAbsolutePath("C:\\project", "D:\\other\\a.ts")).toBe("D:\\other\\a.ts");
  });

  it("returns the candidate as-is when there is no cwd", () => {
    expect(toAbsolutePath("", "src/a.ts")).toBe("src/a.ts");
  });
});

describe("isAbsolutePath", () => {
  it("recognises posix, drive-letter and UNC paths", () => {
    expect(isAbsolutePath("/a")).toBe(true);
    expect(isAbsolutePath("C:/a")).toBe(true);
    expect(isAbsolutePath("C:\\a")).toBe(true);
    expect(isAbsolutePath("\\\\server\\share")).toBe(true);
    expect(isAbsolutePath("a/b")).toBe(false);
  });
});

describe("isTypedAbsolutePath", () => {
  it("treats the tilde spellings a reader types as absolute", () => {
    expect(isTypedAbsolutePath("~")).toBe(true);
    expect(isTypedAbsolutePath("~/notes/todo.md")).toBe(true);
    expect(isTypedAbsolutePath("~\\notes")).toBe(true);
    expect(isTypedAbsolutePath("~user/notes")).toBe(false);
  });

  it("accepts the platform absolute spellings and rejects relative words", () => {
    expect(isTypedAbsolutePath("/etc/hosts")).toBe(true);
    expect(isTypedAbsolutePath("C:\\Users\\lionad")).toBe(true);
    expect(isTypedAbsolutePath("\\\\server\\share")).toBe(true);
    expect(isTypedAbsolutePath("src/client/panel.ts")).toBe(false);
    expect(isTypedAbsolutePath("panel")).toBe(false);
  });
});

describe("hexRefQuery", () => {
  it("accepts a bare hex spelling of four or more digits, case-folded", () => {
    expect(hexRefQuery("face")).toBe("face");
    expect(hexRefQuery("9393130AB")).toBe("9393130ab");
    expect(hexRefQuery(`  ${"f".repeat(40)}`)).toBe("f".repeat(40));
  });

  it("rejects anything that could still be a word or a path", () => {
    expect(hexRefQuery("abc")).toBeUndefined();
    expect(hexRefQuery("faces")).toBeUndefined();
    expect(hexRefQuery("face/off")).toBeUndefined();
    expect(hexRefQuery("face off")).toBeUndefined();
    expect(hexRefQuery("f".repeat(41))).toBeUndefined();
    expect(hexRefQuery("")).toBeUndefined();
  });
});

describe("tildeForm", () => {
  it("spells a home path back into the tilde form a query would use", () => {
    expect(tildeForm("/Users/lionad/notes/todo.md", "/Users/lionad")).toBe("~/notes/todo.md");
    expect(tildeForm("/Users/lionad/notes/", "/Users/lionad")).toBe("~/notes/");
    expect(tildeForm("/Users/lionad", "/Users/lionad")).toBe("~");
  });

  it("leaves paths outside home unspelled", () => {
    expect(tildeForm("/opt/homebrew/x", "/Users/lionad")).toBeUndefined();
    expect(tildeForm("/Users/lionadother/x", "/Users/lionad")).toBeUndefined();
    expect(tildeForm("/x", "")).toBeUndefined();
  });
});

describe("separatorOf", () => {
  it("infers from the spelling and defaults to a slash", () => {
    expect(separatorOf("C:\\a\\b")).toBe("\\");
    expect(separatorOf("/a/b")).toBe("/");
  });
});

describe("composeInsertion", () => {
  it("adds nothing in an empty draft", () => {
    expect(composeInsertion("", 0, "/a/b.ts")).toBe("/a/b.ts");
  });

  it("separates from a preceding word", () => {
    expect(composeInsertion("看看这个", 4, "/a/b.ts")).toBe(" /a/b.ts");
  });

  it("does not pad after existing whitespace", () => {
    expect(composeInsertion("look at ", 8, "/a/b.ts")).toBe("/a/b.ts");
  });

  it("pads both sides when inserted inside a word", () => {
    expect(composeInsertion("abcd", 2, "/a/b.ts")).toBe(" /a/b.ts ");
  });

  it("does not pad against a closing bracket", () => {
    expect(composeInsertion("()", 1, "/a/b.ts")).toBe("/a/b.ts");
  });

  it("does not pad after an opening bracket", () => {
    expect(composeInsertion("(", 1, "/a/b.ts")).toBe("/a/b.ts");
  });

  it("skips the trailing pad for a directory path", () => {
    expect(composeInsertion("abcd", 2, "/a/b/")).toBe(" /a/b/");
  });

  it("clamps an out-of-range caret instead of throwing", () => {
    // Clamped to the end: separated from the preceding word.
    expect(composeInsertion("abc", 99, "/x")).toBe(" /x");
    // Clamped to the start: separated from the following word.
    expect(composeInsertion("abc", -3, "/x")).toBe("/x ");
  });
});

describe("displayPath", () => {
  it("keeps a directory's trailing slash and strips ./", () => {
    expect(displayPath({ path: "./src", kind: "directory" })).toBe("src/");
    expect(displayPath({ path: "src/", kind: "directory" })).toBe("src/");
    expect(displayPath({ path: "./src/a.ts", kind: "file" })).toBe("src/a.ts");
  });
});

describe("escapesWorkspace", () => {
  it("names a leading parent step as an escape, not a mid-path dot segment", () => {
    expect(escapesWorkspace("..")).toBe(true);
    expect(escapesWorkspace("../")).toBe(true);
    expect(escapesWorkspace("../sibling")).toBe(true);
    expect(escapesWorkspace("..\\win")).toBe(true);
    expect(escapesWorkspace("a/../b")).toBe(false);
    expect(escapesWorkspace("./src")).toBe(false);
    expect(escapesWorkspace("src")).toBe(false);
    expect(escapesWorkspace("")).toBe(false);
  });
});

import { describe, expect, it } from "vitest";

import { rankBy, rankRows, scoreText, scoreTerms } from "../src/client/ranking.ts";
import type { PanelRow } from "../src/client/rows.ts";

/**
 * Ranking is the panel's one promise ("the first row is the one you meant"), so
 * these assertions are about the bands, not about exact scores: any band change
 * that alters the order of these fixtures is a behaviour change worth noticing.
 */

describe("scoreText", () => {
  it("treats the empty query as no filter", () => {
    expect(scoreText("", "anything")).toBe(0);
    expect(scoreText("   ", "anything")).toBe(0);
  });

  it("ranks exact above prefix above substring above subsequence", () => {
    const exact = scoreText("goal", "goal");
    const prefix = scoreText("goal", "goal-mode");
    const substring = scoreText("goal", "the-goal-mode");
    const subsequence = scoreText("gm", "goal-mode");

    expect(exact).not.toBeNull();
    expect(prefix).not.toBeNull();
    expect(substring).not.toBeNull();
    expect(subsequence).not.toBeNull();
    expect(exact!).toBeGreaterThan(prefix!);
    expect(prefix!).toBeGreaterThan(substring!);
    expect(substring!).toBeGreaterThan(subsequence!);
  });

  it("prefers a boundary match over a mid-word one", () => {
    const boundary = scoreText("panel", "src/panel.ts");
    const midWord = scoreText("panel", "srccommandpanel.ts");
    expect(boundary!).toBeGreaterThan(midWord!);
  });

  it("folds case and ignores surrounding whitespace", () => {
    expect(scoreText("  GOAL  ", "goal")).toBe(1000);
  });

  it("returns null when the characters are not there in order", () => {
    expect(scoreText("xyz", "goal-mode")).toBeNull();
    // In-order is required: "lg" is not a subsequence of "goal".
    expect(scoreText("lg", "goal")).toBeNull();
  });

  it("penalises a scattered subsequence", () => {
    const tight = scoreText("gm", "gm");
    const scattered = scoreText("gm", "g-a-b-c-d-e-f-m");
    expect(tight!).toBeGreaterThan(scattered!);
  });
});

describe("scoreTerms", () => {
  it("discounts the detail so a description cannot outrank a label", () => {
    const onLabel = scoreTerms("compact", { label: "/compact", detail: "压缩会话历史" });
    const onDetail = scoreTerms("compact", { label: "/other", detail: "compact" });
    expect(onLabel!).toBeGreaterThan(onDetail!);
  });
});

describe("rankBy", () => {
  const rows = ["/goal", "/compact", "/model"];

  it("keeps provider order for an empty query", () => {
    expect(rankBy(rows, row => ({ label: row }), "")).toEqual(rows);
  });

  it("drops non-matching rows and puts the prefix match first", () => {
    expect(rankBy(rows, row => ({ label: row }), "mod")).toEqual(["/model"]);
  });
});

describe("rankRows", () => {
  const builtin = (label: string): PanelRow => ({
    key: `mode:${label}`,
    label,
    group: "面板",
    action: { kind: "open-mode", mode: "navigate" },
  });
  const command = (label: string): PanelRow => ({
    key: `command:${label}`,
    label,
    group: "指令",
    action: { kind: "execute-command", name: label, needsInput: false },
  });

  it("keeps groups contiguous and in first-seen order", () => {
    const rows = [builtin("文件导航"), command("/goal"), builtin("切换"), command("/compact")];
    const ranked = rankRows(rows, "");
    expect(ranked.map(row => row.group)).toEqual(["面板", "面板", "指令", "指令"]);
    expect(ranked.map(row => row.label)).toEqual(["文件导航", "切换", "/goal", "/compact"]);
  });

  it("keeps the panel section first when both sections survive", () => {
    const rows = [builtin("open files"), command("/open"), builtin("switch")];
    const ranked = rankRows(rows, "open");
    expect(ranked.map(row => row.group)).toEqual(["面板", "指令"]);
    expect(ranked.map(row => row.label)).toEqual(["open files", "/open"]);
  });

  it("drops a whole section when nothing in it matches", () => {
    const rows = [builtin("切换"), command("/goal"), command("/model")];
    const ranked = rankRows(rows, "m");
    expect(ranked.map(row => row.group)).toEqual(["指令"]);
    expect(ranked.map(row => row.label)).toEqual(["/model"]);
  });

  it("matches a row through its alias", () => {
    const row: PanelRow = {
      key: "file:1",
      label: "src/client/panel.ts",
      alias: "panel.ts",
      action: { kind: "insert-path", absolutePath: "/x/src/client/panel.ts" },
    };
    expect(rankRows([row], "panel.ts")).toHaveLength(1);
  });
});

