    await vi.waitFor(() => expect(h.sidebar.openResource).toHaveBeenCalledWith(PANEL_FILE_ADDRESS, { kind: "text" }));
    expect(linkOfTarget(PANEL_FILE)).toBeUndefined();
    expect(h.input.notify).not.toHaveBeenCalled();
