import { Context } from "@deepseek-ai/cordis";
import { remoteMethods } from "@deepseek-ai/dsh-typert-protocol";
import { afterEach, describe, expect, it, vi } from "vitest";

import { HostShutdownService } from "../src/host/shutdown-remote.ts";
import {
  currentShellChannel,
  requestShutdown,
  shellOwnsProcess,
  shutdownAvailable,
  type ShellChannel,
} from "../src/host/shutdown.ts";
import { SHUTDOWN_SERVICE } from "../src/shared.ts";

/** A launcher-owned process: no parent IPC channel (`dsh` / `dsh web`). */
const TERMINAL: ShellChannel = { send: undefined, connected: false };

/** A shell-owned process: the Desktop spawns the Host with an IPC channel. */
const SHELL: ShellChannel = { send: () => true, connected: true };

/** Mount the service the way `apply` does, with the channel given explicitly. */
function mount(ctx: Context, channel: ShellChannel = TERMINAL): HostShutdownService {
  return new HostShutdownService(ctx, { channel });
}

describe("shellOwnsProcess", () => {
  it("answers true only for an open IPC channel to a parent", () => {
    expect(shellOwnsProcess(SHELL)).toBe(true);
    expect(shellOwnsProcess({ send: () => true, connected: false })).toBe(false);
    expect(shellOwnsProcess({ connected: true })).toBe(false);
    expect(shellOwnsProcess(TERMINAL)).toBe(false);
  });

  it("reads the live process's own channel facts", () => {
    // Whichever pool runs this suite, the answer mirrors the process verbatim:
    // the host half captures exactly this snapshot at mount.
    expect(currentShellChannel()).toEqual({
      send: typeof process.send === "function" ? process.send : undefined,
      connected: process.connected,
    });
  });
});

describe("shutdownAvailable", () => {
  it("answers true only for a callable appExit", () => {
    expect(shutdownAvailable({ get: () => () => undefined }, TERMINAL)).toBe(true);
    expect(shutdownAvailable({ get: () => "quit" }, TERMINAL)).toBe(false);
    expect(shutdownAvailable({ get: () => undefined }, TERMINAL)).toBe(false);
    expect(shutdownAvailable({}, TERMINAL)).toBe(false);
  });

  it("answers false without throwing when the guarded read throws", () => {
    expect(
      shutdownAvailable(
        {
          get: () => {
            throw new Error("guard");
          },
        },
        TERMINAL,
      ),
    ).toBe(false);
  });

  it("probes softly, exactly the way the request path does", () => {
    const get = vi.fn(() => undefined);
    shutdownAvailable({ get }, TERMINAL);
    expect(get).toHaveBeenCalledWith("appExit", false);
  });

  it("answers false for a shell-owned host even though appExit is in hand", () => {
    // The Desktop combination: the profile boot always provides appExit, but a
    // self-initiated exit is read by the shell as a failure, not as a quit.
    const get = vi.fn(() => () => undefined);
    expect(shutdownAvailable({ get }, SHELL)).toBe(false);
    // The shell answer short-circuits: no point poking the tree at all.
    expect(get).not.toHaveBeenCalled();
  });
});

describe("requestShutdown", () => {
  afterEach(() => {
    vi.useRealTimers();
  });

  it("answers requested before it fires appExit with 0", () => {
    vi.useFakeTimers();
    const appExit = vi.fn();
    const get = vi.fn(() => appExit);

    expect(requestShutdown({ get }, TERMINAL)).toBe("requested");
    expect(get).toHaveBeenCalledTimes(1);
    expect(get).toHaveBeenCalledWith("appExit", false);
    // The answer has to be on the wire first: in-line exit disposes the tree
    // (web server included) and drops the RPC response.
    expect(appExit).not.toHaveBeenCalled();
    vi.advanceTimersByTime(0);
    expect(appExit).toHaveBeenCalledTimes(1);
    expect(appExit).toHaveBeenCalledWith(0);
  });

  it("answers unavailable when the context has no get", () => {
    expect(requestShutdown({}, TERMINAL)).toBe("unavailable");
  });

  it("answers unavailable when get finds no appExit", () => {
    expect(requestShutdown({ get: () => undefined }, TERMINAL)).toBe("unavailable");
  });

  it("answers unavailable when appExit is not a function", () => {
    expect(requestShutdown({ get: () => "quit" }, TERMINAL)).toBe("unavailable");
  });

  it("answers unavailable without throwing when get throws", () => {
    const get = () => {
      throw new Error("boom");
    };
    expect(requestShutdown({ get }, TERMINAL)).toBe("unavailable");
  });

  it("answers unavailable and never fires appExit for a shell-owned host", () => {
    vi.useFakeTimers();
    const appExit = vi.fn();
    const get = vi.fn(() => appExit);

    expect(requestShutdown({ get }, SHELL)).toBe("unavailable");
    vi.advanceTimersByTime(0);
    expect(appExit).not.toHaveBeenCalled();
  });

  it("does not dedupe: the same context fires appExit on every call", () => {
    vi.useFakeTimers();
    const appExit = vi.fn();
    const ctx = { get: () => appExit };

    expect(requestShutdown(ctx, TERMINAL)).toBe("requested");
    expect(requestShutdown(ctx, TERMINAL)).toBe("requested");
    vi.advanceTimersByTime(0);
    expect(appExit).toHaveBeenCalledTimes(2);
  });
});

describe("HostShutdownService", () => {
  it("publishes the capability probe and the request endpoint, waiting on no host service", () => {
    expect(HostShutdownService.inject).toEqual([]);
    const markers = remoteMethods(mount(new Context()));
    expect(markers.map(marker => marker.exportName ?? marker.method).sort()).toEqual(["available", "request"]);
    expect(SHUTDOWN_SERVICE).toBe("hostShutdown");
  });

  it("answers the capability probe without touching appExit", async () => {
    const ctx = new Context();
    const appExit = vi.fn();
    ctx.provide("appExit", appExit);
    const service = mount(ctx);

    await expect(service.available()).resolves.toBe(true);
    expect(appExit).not.toHaveBeenCalled();
  });

  it("answers the capability probe false on a host that cannot quit", async () => {
    await expect(mount(new Context()).available()).resolves.toBe(false);
  });

  it("answers the capability probe false when a parent shell owns the process", async () => {
    const ctx = new Context();
    const appExit = vi.fn();
    ctx.provide("appExit", appExit);

    await expect(mount(ctx, SHELL).available()).resolves.toBe(false);
  });

  /**
   * The Gateway does not call a Remote method on the Service instance: it reads
   * the method off a tracked Context proxy and invokes it with that proxy as
   * `this`. A real `#private` field is unreachable there — every remote call
   * died with "Cannot read from private field" while direct calls passed — so
   * this case pins the receiver shape the live host actually uses.
   */
  it("reads its mount-time facts through a proxy receiver, the way the Gateway invokes it", async () => {
    const ctx = new Context();
    const appExit = vi.fn();
    ctx.provide("appExit", appExit);
    const service = mount(ctx);
    const receiver = new Proxy(service, {
      get: (target, prop, inner) => Reflect.get(target, prop, inner),
    });

    await expect(Reflect.apply(receiver.available, receiver, [])).resolves.toBe(true);
    expect(appExit).not.toHaveBeenCalled();
  });

  it("answers requested, then fires the host context's appExit with 0", async () => {
    vi.useFakeTimers();
    const ctx = new Context();
    const appExit = vi.fn();
    ctx.provide("appExit", appExit);
    const service = mount(ctx);

    await expect(service.request()).resolves.toBe("requested");
    expect(appExit).not.toHaveBeenCalled();
    vi.advanceTimersByTime(0);
    expect(appExit).toHaveBeenCalledTimes(1);
    expect(appExit).toHaveBeenCalledWith(0);
    vi.useRealTimers();
  });

  it("refuses to fire a shell-owned host's appExit through the endpoint", async () => {
    vi.useFakeTimers();
    const ctx = new Context();
    const appExit = vi.fn();
    ctx.provide("appExit", appExit);
    const service = mount(ctx, SHELL);

    await expect(service.request()).resolves.toBe("unavailable");
    vi.advanceTimersByTime(0);
    expect(appExit).not.toHaveBeenCalled();
    vi.useRealTimers();
  });

  it("answers unavailable on a host context without appExit, firing nothing", async () => {
    await expect(mount(new Context()).request()).resolves.toBe("unavailable");
  });

  it("keeps answering across calls: no dedup at the endpoint either", async () => {
    vi.useFakeTimers();
    const ctx = new Context();
    const appExit = vi.fn();
    ctx.provide("appExit", appExit);
    const service = mount(ctx);

    await expect(service.request()).resolves.toBe("requested");
    await expect(service.request()).resolves.toBe("requested");
    vi.advanceTimersByTime(0);
    expect(appExit).toHaveBeenCalledTimes(2);
    vi.useRealTimers();
  });
});

import { describe, expect, it, vi } from "vitest";

import { copyFor } from "../src/client/copy.ts";
import { rankRows } from "../src/client/ranking.ts";
import { loadRows, type LoadRequest, type SourceServices } from "../src/client/sources.ts";
import type { GitExplorerRemote } from "../src/client/dsh.ts";
import {
  COMMIT_FOCUS,
  SESSION_A,
  SESSION_ARCHIVED,
  SESSION_B,
  SESSION_BLANK,
  SESSION_C,
  SESSION_SUBAGENT,
  fakeCommands,
  fakeFileReferences,
  fakeGitExplorer,
  fakePathExplorer,
  fakeSessions,
  fakeWorkspaces,
  sessionList,
  workspaceSnapshot,
} from "./fixtures.ts";

const copy = copyFor("zh");
const now = 5_000_000;
const signal = new AbortController().signal;

function services(overrides: Partial<SourceServices> = {}): SourceServices {
  const list = sessionList([SESSION_A, SESSION_B, SESSION_C, SESSION_BLANK, SESSION_SUBAGENT, SESSION_ARCHIVED]);
  return {
    fileReferences: () => fakeFileReferences(),
    commands: () => fakeCommands(),
    pathExplorer: () => fakePathExplorer(),
    sessions: () => fakeSessions(list),
    workspaces: () => fakeWorkspaces(workspaceSnapshot()),
    now: () => now,
    ...overrides,
  };
}

function request(overrides: Partial<LoadRequest> = {}): LoadRequest {
  return {
    mode: "navigate",
    level: "root",
    scope: null,
    query: "",
    sessionId: SESSION_A.id,
    copy,
    signal,
    ...overrides,
  };
}

describe("loadRows: navigate", () => {
  it("returns file rows with an absolute payload built from the session cwd", async () => {
    const result = await loadRows(
      services({
        fileReferences: () =>
          fakeFileReferences({
            files: [
              { path: "src/client/panel.ts", kind: "file" },
              { path: "src", kind: "directory" },
            ],
          }),
      }),
      request(),
    );

    expect(result.status).toBe("ready");
    expect(result.rows.map(row => row.action)).toEqual([
      { kind: "insert-path", absolutePath: `${SESSION_A.cwd}/src/client/panel.ts` },
      { kind: "insert-path", absolutePath: `${SESSION_A.cwd}/src/` },
    ]);
  });

  it("explains the missing session instead of querying without one", async () => {
    const result = await loadRows(services(), request({ sessionId: null }));
    expect(result.status).toBe("error");
    expect(result.message).toBe(copy.noticeNoSession);
  });

  it("surfaces a host failure by its code", async () => {
    const result = await loadRows(
      services({ fileReferences: () => fakeFileReferences({ fileError: "gateway/not-found" }) }),
      request(),
    );
    expect(result).toMatchObject({ status: "error", message: "gateway/not-found" });
  });

  it("does not fail when a service is missing", async () => {
    const result = await loadRows(services({ fileReferences: () => undefined }), request());
    expect(result.status).toBe("error");
    expect(result.message).toBe(copy.failed);
  });
});

describe("loadRows: navigate with an absolute query", () => {
  it("asks the filesystem service instead of the workspace index", async () => {
    const list = vi.fn(async () => ({ ok: true as const, value: [] }));
    const result = await loadRows(
      services({
        fileReferences: () => ({ list }),
        pathExplorer: () =>
          fakePathExplorer({
            home: "/Users/lionad",
            entries: [{ path: "/Users/lionad/notes/todo.md", kind: "file", exists: true }],
          }),
      }),
      request({ query: "/Users/lionad/notes/tod" }),
    );

    expect(list).not.toHaveBeenCalled();
    expect(result.status).toBe("ready");
    expect(result.rows.map(row => row.label)).toEqual(["/Users/lionad/notes/todo.md"]);
    expect(result.rows[0]?.origin).toBe("filesystem");
  });

  it("needs no session to browse the filesystem", async () => {
    const result = await loadRows(
      services({
        pathExplorer: () =>
          fakePathExplorer({ home: "/tmp", entries: [{ path: "/tmp/notes", kind: "directory", exists: true }] }),
      }),
      request({ query: "/tmp/", sessionId: null }),
    );

    expect(result.status).toBe("ready");
    expect(result.rows.map(row => row.label)).toEqual(["/tmp/notes/"]);
  });

  it("reports a missing filesystem service like any missing service", async () => {
    const result = await loadRows(
      services({ pathExplorer: () => undefined }),
      request({ query: "/tmp/" }),
    );
    expect(result.status).toBe("error");
    expect(result.message).toBe(copy.failed);
  });

  it("surfaces a filesystem failure by its code", async () => {
    const result = await loadRows(
      services({ pathExplorer: () => fakePathExplorer({ error: "gateway/not-found" }) }),
      request({ query: "/tmp/" }),
    );
    expect(result).toMatchObject({ status: "error", message: "gateway/not-found" });
  });
});

describe("loadRows: navigate with a hex query", () => {
  it("attaches the commit group ahead of the workspace files", async () => {
    const query = vi.fn(async () => ({
      ok: true as const,
      value: { ok: true as const, page: { commits: [COMMIT_FOCUS] } },
    }));
    const result = await loadRows(
      services({
        fileReferences: () => fakeFileReferences({ files: [{ path: "src/panel.ts", kind: "file" }] }),
        gitExplorer: () => ({ query } satisfies GitExplorerRemote),
      }),
      request({ query: "  9393130AB " }),
    );

    expect(query).toHaveBeenCalledWith(
      { sessionId: SESSION_A.id, ref: "9393130ab", limit: 5 },
      expect.anything(),
    );
    expect(result.status).toBe("ready");
    expect(result.rows[0]?.group).toBe(copy.groupCommits);
    expect(result.rows[0]?.label).toBe(COMMIT_FOCUS.subject);
    expect(result.rows.some(row => row.group !== copy.groupCommits)).toBe(true);
  });

  it("issues no commit query when no gitExplorer face answers, and shows no error", async () => {
    const result = await loadRows(services({ gitExplorer: () => undefined }), request({ query: "9393130" }));

    expect(result.status).toBe("ready");
    expect(result.rows.some(row => row.group === copy.groupCommits)).toBe(false);
    expect(result.message).toBeUndefined();
  });

  it("degrades a refused prefix and a failed transport to no commit rows, silently", async () => {
    for (const gitExplorer of [
      fakeGitExplorer({ error: "git-failed" }),
      { query: async () => ({ ok: false as const, error: { code: "rpc-error" } }) } satisfies GitExplorerRemote,
    ]) {
      const result = await loadRows(
        services({ gitExplorer: () => gitExplorer }),
        request({ query: "9393130" }),
      );
      expect(result.status).toBe("ready");
      expect(result.rows.some(row => row.group === copy.groupCommits)).toBe(false);
      expect(result.message).toBeUndefined();
    }
  });

  it("keeps a non-hex query on the workspace plane alone", async () => {
    const query = vi.fn();
    await loadRows(
      services({ gitExplorer: () => ({ query } as unknown as GitExplorerRemote) }),
      request({ query: "panel" }),
    );
    expect(query).not.toHaveBeenCalled();
  });
});

describe("loadRows: command", () => {
  it("returns an empty plane with no session, because the panel builds its own rows", async () => {
    const result = await loadRows(services(), request({ mode: "command", sessionId: null }));
    expect(result.status).toBe("ready");
    expect(result.rows).toEqual([]);
  });

  it("returns the host catalogue as its own plane, labelled like a command", async () => {
    const result = await loadRows(
      services({
        commands: () => fakeCommands({ commands: [{ name: "goal", description: "设定目标" }] }),
      }),
      request({ mode: "command" }),
    );
    expect(result.rows.map(row => row.label)).toEqual(["/goal"]);
    expect(result.rows[0]?.group).toBe(copy.groupCommands);
  });

  it("reports a failed catalogue as a warning with an empty plane", async () => {
    const result = await loadRows(
      services({ commands: () => fakeCommands({ commandError: "session/writer-held" }) }),
      request({ mode: "command" }),
    );
    expect(result.status).toBe("ready");
    expect(result.rows).toEqual([]);
    expect(result.warning).toBe("session/writer-held");
  });
});

describe("loadRows: switch", () => {
  it("returns workspaces at the top level, closing with the two fixed rows", async () => {
    const result = await loadRows(services(), request({ mode: "switch" }));
    expect(result.status).toBe("ready");
    expect(result.rows.map(row => row.label)).toEqual([
      "dsh-plugins",
      "other",
      copy.allSessions,
      copy.ungrouped,
      copy.newSession,
      copy.archivedSessions,
    ]);
  });

  it("closes a workspace's sessions with a new-session row and an archived-sessions row", async () => {
    const result = await loadRows(
      services(),
      request({ mode: "switch", level: "sessions", scope: { kind: "workspace", workspaceId: "ws-one" } }),
    );
    expect(result.rows.map(row => row.label)).toEqual(["重构命令面板", copy.newSession, copy.archivedSessions]);
    expect(result.rows.at(-2)?.action).toEqual({
      kind: "create-session",
      scope: "workspace",
      workspaceId: "ws-one",
    });
    expect(result.rows.at(-1)?.action).toEqual({ kind: "drill-archived" });
    // ws-one's only archived session is sess-archived in the fixture.
    expect(result.rows.at(-1)?.hint).toBe(copy.sessionsCount(1));
  });

  it("needs no session and no remote at all", async () => {
    const result = await loadRows(
      services({
        fileReferences: () => undefined,
        commands: () => undefined,
        sessions: () => fakeSessions(sessionList([SESSION_A])),
      }),
      request({ mode: "switch", sessionId: null }),
    );
    expect(result.status).toBe("ready");
  });

  it("merges cross-workspace session rows once the root query is non-empty", async () => {
    const result = await loadRows(services(), request({ mode: "switch", query: "调研" }));
    expect(result.status).toBe("ready");
    // The loader returns the merged unranked plane — the title lives on no
    // workspace row, so only this addition can answer a session-title query.
    const merged = result.rows.find(row => row.label === SESSION_B.displayTitle);
    expect(merged?.action).toEqual({ kind: "open-session", sessionId: SESSION_B.id });
    // Ranked the way the runtime projects it, the title reaches the session
    // without the drill: workspace and aggregate rows stay silent.
    expect(rankRows(result.rows, "调研").map(row => row.label)).toEqual([SESSION_B.displayTitle]);
  });

  it("keeps a workspace query answered by its row first, its sessions below", async () => {
    const result = await loadRows(services(), request({ mode: "switch", query: "dsh-plugins" }));
    const ranked = rankRows(result.rows, "dsh-plugins").map(row => row.label);
    expect(ranked.indexOf("dsh-plugins")).toBeLessThan(ranked.indexOf(SESSION_A.displayTitle));
    // The other workspace's session rides in only via its own title, and
    // "dsh-plugins" is not part of it.
    expect(ranked).not.toContain(SESSION_B.displayTitle);
  });
});

describe("loadRows: navigate with a parent-step query", () => {
