describe("reorderChildren", () => {
  it("reorders the root", () => {
    const tree = treeOf(node("file", "a"), node("file", "b"), node("file", "c"));
    expect(rootIds(reorderChildren(tree, null, ["c", "a", "b"]))).toEqual(["c", "a", "b"]);
  });

  it("reorders inside a group", () => {
