  });

  it("places the row after the copy and remote rows", () => {
    const entries = buildContextMenu(
      {
        row: fileRow(),
        notices: { workspace: true },
        capabilities: capabilities(),
        absolutePath: "/w/docs/a.md",
        createParent: "docs",
        remoteLinks: undefined,
