  });

  it("keeps the create rows above the reveal row", () => {
    const entries = buildContextMenu(
      {
        row: fileRow(),
        notices: { workspace: true },
        capabilities: capabilities(),
        absolutePath: "/workspace/docs/guides/a.md",
