/**
 * The remote rows of the context menu.
 *
 * One level of submenu is the host `Menu`'s hard limit, so "copy remote address"
 * is a top-level row with the remotes under it rather than a row nested inside
 * "copy path". These tests pin that shape, plus the two ways a row can be
 * unavailable: no remote at all, and a remote whose URL the client could not
 * parse.
 */
import { describe, expect, it } from "vitest";

import {
  MENU_ACTION,
  buildContextMenu,
  type ContextMenuEntry,
  type ContextMenuRow,
} from "../src/client/context-menu.ts";
import type { RemoteLink } from "../src/client/remote-url.ts";
import type { WorkspaceCapabilities } from "../src/host/types.ts";

const t = (key: string): string => key;

function fileRow(): ContextMenuRow {
  return { type: "entry", path: "docs/a.md", name: "a.md", kind: "file" };
}

function capabilities(): WorkspaceCapabilities {
  return { fileManager: "finder", canReveal: true };
}

/** Two links, as the builder would produce for one repository. */
function links(): readonly RemoteLink[] {
  return [
    { id: "copy.remote.origin", label: "origin · GitHub", url: "https://github.com/acme/app/blob/main/a.md" },
    { id: "copy.remote.upstream", label: "upstream · GitHub", url: "https://github.com/acme/up/app/blob/main/a.md" },
  ];
}

/** One row by action id. */
function entry(entries: readonly ContextMenuEntry[], id: string): ContextMenuEntry {
  const found = entries.find(candidate => candidate.id === id);
  if (found === undefined) throw new Error(`the menu has no ${id} row`);
  return found;
}

describe("buildContextMenu remote rows", () => {
  it("lists one submenu row per remote", () => {
    const entries = buildContextMenu(
      {
        row: fileRow(),
        notices: { workspace: true },
        capabilities: capabilities(),
        absolutePath: "/repo/a.md",
        createParent: "docs",
        remoteLinks: links(),
        bookmarkTarget: undefined,
      },
      t,
    );
    const remote = entry(entries, MENU_ACTION.copyRemote);
    expect(remote.label).toBe("menu.copy.remote");
    expect(remote.disabled).not.toBe(true);
    expect(remote.submenu?.map(child => child.id)).toEqual(["copy.remote.origin", "copy.remote.upstream"]);
    expect(remote.submenu?.map(child => child.label)).toEqual(["origin · GitHub", "upstream · GitHub"]);
  });

  it("disables the row with a reason when the repository has no remote", () => {
    const entries = buildContextMenu(
      {
        row: fileRow(),
        notices: { workspace: true },
        capabilities: capabilities(),
        absolutePath: "/repo/a.md",
        createParent: "docs",
        remoteLinks: [],
        bookmarkTarget: undefined,
      },
      t,
    );
    const remote = entry(entries, MENU_ACTION.copyRemote);
    expect(remote.disabled).toBe(true);
    expect(remote.reason).toBe("menu.copy.remote.reason");
    // No submenu: an empty card would look like a bug.
    expect(remote.submenu).toBeUndefined();
  });

  it("disables the row when the channel never answered", () => {
    const entries = buildContextMenu(
      {
        row: fileRow(),
        notices: { workspace: true },
        capabilities: capabilities(),
        absolutePath: "/repo/a.md",
        createParent: "docs",
        remoteLinks: undefined,
        bookmarkTarget: undefined,
      },
      t,
    );
    expect(entry(entries, MENU_ACTION.copyRemote).disabled).toBe(true);
  });

  it("keeps the remote row out of the copy submenu, one level deep", () => {
    // The host `Menu` opens exactly one level. Nesting this row inside "copy
    // path" would make it a second level and it would silently never open.
    const entries = buildContextMenu(
      {
        row: fileRow(),
        notices: { workspace: true },
        capabilities: capabilities(),
        absolutePath: "/repo/a.md",
        createParent: "docs",
        remoteLinks: links(),
        bookmarkTarget: undefined,
      },
      t,
    );
    const copy = entry(entries, "menu.copy");
    expect(copy.submenu?.map(child => child.id)).toEqual([MENU_ACTION.copyAbsolute, MENU_ACTION.copyRelative]);
    expect(entries.map(candidate => candidate.id)).toContain(MENU_ACTION.copyRemote);
  });

  it("places the remote row after the copy submenu", () => {
    const entries = buildContextMenu(
      {
        row: fileRow(),
        notices: { workspace: true },
        capabilities: capabilities(),
        absolutePath: "/repo/a.md",
        createParent: "docs",
        remoteLinks: links(),
        bookmarkTarget: undefined,
      },
      t,
    );
    expect(entries.map(candidate => candidate.id)).toEqual([
      MENU_ACTION.createFile,
      MENU_ACTION.createFolder,
      MENU_ACTION.reveal,
      "menu.copy",
      MENU_ACTION.copyRemote,
      MENU_ACTION.reference,
      MENU_ACTION.addBookmark,
    ]);
  });

  it("does not offer the remote row on the blank area", () => {
    // The blank area has no path, so there is nothing to link to.
    const entries = buildContextMenu(
      {
        row: undefined,
        notices: { workspace: true },
        capabilities: capabilities(),
        absolutePath: undefined,
        createParent: "",
        remoteLinks: links(),
        bookmarkTarget: undefined,
      },
      t,
    );
    expect(entries.some(candidate => candidate.id === MENU_ACTION.copyRemote)).toBe(false);
  });

  it("keeps the action id prefix stable for the view's dispatch", () => {
    expect(MENU_ACTION.copyRemote).toBe("copy.remote");
  });
});

/**
 * The context menu's content, decided without React or the DOM.
 *
 * These tests pin the product decision behind the slice: every row kind gets a
 * menu, the reveal row names the platform's own file manager, and a row that
 * cannot run says why instead of disappearing. Action ids are asserted as
 * literals because the view dispatches on them; a rename here without the view
 * would turn every click into a no-op.
 */
import { describe, expect, it } from "vitest";

import {
  MENU_ACTION,
  buildContextMenu,
  type ContextMenuEntry,
  type ContextMenuRow,
} from "../src/client/context-menu.ts";
import type { WorkspaceCapabilities } from "../src/host/types.ts";

/** Identity translator: labels come back as their keys, which is what we assert. */
const t = (key: string): string => key;

function fileRow(): ContextMenuRow {
  return { type: "entry", path: "docs/a.md", name: "a.md", kind: "file" };
}

function directoryRow(): ContextMenuRow {
  return { type: "entry", path: "docs", name: "docs", kind: "directory" };
}

function capabilities(fileManager: WorkspaceCapabilities["fileManager"]): WorkspaceCapabilities {
  return { fileManager, canReveal: fileManager !== null };
}

/** The reveal row of a built menu. */
function revealEntry(entries: readonly ContextMenuEntry[]): ContextMenuEntry {
  const entry = entries.find(candidate => candidate.id === MENU_ACTION.reveal);
  if (entry === undefined) throw new Error("the menu has no reveal row");
  return entry;
}

/** The copy submenu's rows. */
function copyEntries(entries: readonly ContextMenuEntry[]): readonly ContextMenuEntry[] {
  return entries.find(candidate => candidate.submenu !== undefined)?.submenu ?? [];
}

describe("buildContextMenu", () => {
  it("gives a file row the reveal row and both copy rows", () => {
    const entries = buildContextMenu(
      {
        row: fileRow(),
        notices: { workspace: true },
        capabilities: capabilities("finder"),
        absolutePath: "/workspace/docs/a.md",
        createParent: "docs",
        remoteLinks: undefined,
        bookmarkTarget: undefined,
        inputTarget: { session: true, insertReference: true, source: true },
      },
      t,
    );

    expect(entries.map(entry => entry.id)).toEqual([
      MENU_ACTION.createFile,
      MENU_ACTION.createFolder,
      MENU_ACTION.reveal,
      "menu.copy",
      MENU_ACTION.copyRemote,
      MENU_ACTION.reference,
      MENU_ACTION.addBookmark,
    ]);
    expect(copyEntries(entries).map(entry => entry.id)).toEqual([
      MENU_ACTION.copyAbsolute,
      MENU_ACTION.copyRelative,
    ]);
    // The remote and add-bookmark rows are disabled here because this input
    // reports no remote channel and no bookmark target; the rows this test is
    // about are the reveal and copy ones.
    const scoped = entries.filter(
      entry => entry.id !== MENU_ACTION.copyRemote && entry.id !== MENU_ACTION.addBookmark,
    );
    expect(scoped.every(entry => entry.disabled !== true)).toBe(true);
  });

  it("gives a directory row the same menu as a file row", () => {
    const input = {
      notices: { workspace: true as const },
      capabilities: capabilities("finder"),
      absolutePath: "/workspace/docs",
      createParent: "docs",
      remoteLinks: undefined,
      bookmarkTarget: undefined,
    };
    const forDirectory = buildContextMenu({ ...input, row: directoryRow() }, t);
    const forFile = buildContextMenu({ ...input, row: fileRow() }, t);
    expect(forDirectory.map(entry => entry.id)).toEqual(forFile.map(entry => entry.id));
  });

  it("offers only the create rows on the tree's blank area", () => {
    const entries = buildContextMenu(
      {
        row: undefined,
        notices: { workspace: true },
        capabilities: capabilities("finder"),
        absolutePath: undefined,
        createParent: "",
        remoteLinks: undefined,
        bookmarkTarget: undefined,
      },
      t,
    );
    expect(entries.map(entry => entry.id)).toEqual([MENU_ACTION.createFile, MENU_ACTION.createFolder]);
    // No row means nothing to reveal or copy: those actions need a target.
    expect(entries.some(entry => entry.id === MENU_ACTION.reveal)).toBe(false);
    expect(entries.some(entry => entry.submenu !== undefined)).toBe(false);
  });

  it("names the file manager the host reported", () => {
    const label = (fileManager: WorkspaceCapabilities["fileManager"]): string =>
      revealEntry(
        buildContextMenu(
          {
            row: fileRow(),
            notices: { workspace: true },
            capabilities: capabilities(fileManager),
            absolutePath: "/w/a.md",
            createParent: "docs",
            remoteLinks: undefined,
            bookmarkTarget: undefined,
          },
          t,
        ),
      ).label;

    expect(label("finder")).toBe("menu.reveal.finder");
    expect(label("explorer")).toBe("menu.reveal.explorer");
    expect(label("directory")).toBe("menu.reveal.directory");
  });

  it("disables the reveal row with a reason when the host has no file manager", () => {
    const entry = revealEntry(
      buildContextMenu(
        {
          row: fileRow(),
          notices: { workspace: true },
          capabilities: capabilities(null),
          absolutePath: "/w/a.md",
          createParent: "docs",
          remoteLinks: undefined,
          bookmarkTarget: undefined,
        },
        t,
      ),
    );
    expect(entry.disabled).toBe(true);
    expect(entry.reason).toBe("menu.reveal.reason");
    // The label still names a file manager so the row reads as an action.
    expect(entry.label).toBe("menu.reveal.directory");
  });

  it("disables the reveal row when the workspace channel never answered", () => {
    const entry = revealEntry(
      buildContextMenu(
        {
          row: fileRow(),
          notices: { workspace: false },
          capabilities: undefined,
          absolutePath: undefined,
          createParent: "docs",
          remoteLinks: undefined,
          bookmarkTarget: undefined,
        },
        t,
      ),
    );
    expect(entry.disabled).toBe(true);
    expect(entry.reason).toBe("menu.reveal.reason");
  });

  it("keeps the relative copy available without an absolute path", () => {
    const entries = buildContextMenu(
      {
        row: fileRow(),
        notices: { workspace: true },
        capabilities: capabilities("finder"),
        absolutePath: undefined,
        createParent: "docs",
        remoteLinks: undefined,
        bookmarkTarget: undefined,
      },
      t,
    );
    const [absolute, relative] = copyEntries(entries);
    expect(absolute?.disabled).toBe(true);
    expect(absolute?.reason).toBe("menu.copy.absolute.reason");
    expect(relative?.disabled).not.toBe(true);
  });

  it("keeps the action ids stable for the view's dispatch", () => {
    expect(MENU_ACTION).toEqual({
      createFile: "create.file",
      createFolder: "create.folder",
      reveal: "reveal",
      copyAbsolute: "copy.absolute",
      copyRelative: "copy.relative",
      copyRemote: "copy.remote",
      addBookmark: "add.bookmark",
      reference: "reference.input",
    });
  });
});

import { describe, expect, it } from "vitest";

import { surfaceTranslator, SURFACE_KEY_PREFIX, EN, ZH } from "../src/client/copy.ts";

/**
 * The keys the shared renderers ask their translator for.
 *
 * Listed rather than imported because the surfaces call them as literals; a
 * surface that starts asking for a new one would show its raw key, and this list
 * is the only place that failure is visible without opening a model.
 */
const SURFACE_KEYS = [
  "state.loading",
  "state.decoding",
  "state.failed",
  "state.retry",
  "state.unsupported",
  "raster.title",
  "raster.noPages",
  "raster.pageMissing",
  "raster.emptyPage",
  "raster.page",
  "raster.previous",
  "raster.next",
  "scene3d.reset",
  "scene3d.wireframe",
  "scene3d.facts",
  "cad.fit",
  "cad.layers",
  "image.title",
];

describe("surface dictionary", () => {
  it("answers every key the shared renderers ask for, in both languages", () => {
    for (const key of SURFACE_KEYS) {
      expect(ZH[SURFACE_KEY_PREFIX + key], `zh ${key}`).toBeTypeOf("string");
      expect(EN[SURFACE_KEY_PREFIX + key], `en ${key}`).toBeTypeOf("string");
    }
  });

  it("keeps the two languages on the same key set", () => {
    expect(Object.keys(ZH).sort()).toEqual(Object.keys(EN).sort());
  });

  it("ships the diff-stat and branch keys in both languages", () => {
    expect(ZH["row.binary"]).toBe("bin");
    expect(EN["row.binary"]).toBe("bin");
    expect(ZH["foot.branch"]).toBeTypeOf("string");
    expect(EN["foot.branch"]).toBeTypeOf("string");
  });

  it("rebinds the surface vocabulary onto this package's namespace", () => {
    const t = surfaceTranslator((key: string) => `ns:${key}`);
    expect(t("state.loading")).toBe(`ns:${SURFACE_KEY_PREFIX}state.loading`);
    // The tree's own loading message is a different key, so the two never meet.
    expect(t("state.loading")).not.toBe("ns:state.loading");
  });
});

