    await session.reload();
    session.setDraft("draft");

    expect(store.revision()).toBeGreaterThan(before + 1);
    expect(calls).toBeGreaterThan(1);

    off();
    const settled = calls;
    session.setDraft("after unsubscribe");
    expect(calls).toBe(settled);
    session.dispose();
  });
});

