/**
 * The bookmark endpoints on the host workspace service.
 *
 * Two promises are under test. A host with a storage domain round-trips a tree
 * through `save` and `load`, keyed by the workspace's canonical path so two
 * sessions in one workspace share it. And a host without one answers `no-storage`
 * rather than failing: that code is what tells the client to keep its own copy in
 * localStorage instead of showing the reader an error they cannot act on.
 */
import { Context } from "@deepseek-ai/cordis";
import { remoteMethods } from "@deepseek-ai/dsh-typert-protocol";
import { describe, expect, it, vi } from "vitest";

import type { BookmarkTree } from "../src/bookmarks.ts";
import type { BookmarkStorageDomainFace, BookmarkTableFace } from "../src/host/bookmarks.ts";
import type { FsTargetFace } from "../src/host/types.ts";
import { FsExplorerWorkspaceService } from "../src/index.ts";

/** One valid tree, small enough to read in a failure message. */
function tree(): BookmarkTree {
  return {
    version: 1,
    updatedAt: "2026-11-03T00:00:00.000Z",
    roots: [
      {
        id: "g1",
        kind: "group",
        name: "Work",
        createdAt: 1,
        children: [{ id: "f1", kind: "file", name: "a.md", path: "docs/a.md", createdAt: 2 }],
      },
    ],
  };
}

/** A target as `resolve` hands it back. */
function targetOf(path: string): FsTargetFace {
  return { targetKey: `tk:${path}`, displayPath: path };
}

/** The filesystem slice the bookmark endpoints touch: resolve and processPath. */
function fakeFs(): {
  readonly resolve: ReturnType<typeof vi.fn>;
  readonly stat: ReturnType<typeof vi.fn>;
  readonly contains: ReturnType<typeof vi.fn>;
  readonly processPath: ReturnType<typeof vi.fn>;
} {
  return {
    resolve: vi.fn(async (path: string) => targetOf(path)),
    stat: vi.fn(async () => ({ type: "directory" as const })),
    contains: vi.fn(() => true),
    processPath: vi.fn((target: FsTargetFace) => target.displayPath),
  };
}

/** One in-memory table, shaped like the host's. */
function fakeTable(initial: Record<string, unknown> = {}): BookmarkTableFace & {
  readonly rows: Map<string, unknown>;
} {
  const rows = new Map<string, unknown>(Object.entries(initial));
  return {
    rows,
    get: (key: string) => rows.get(key),
    put: async (key: string, value: unknown) => {
      rows.set(key, value);
    },
    delete: async (key: string) => {
      rows.delete(key);
    },
    entries: () => rows.entries(),
  };
}

/** A storage domain over one fake table. */
function fakeDomain(table: BookmarkTableFace): BookmarkStorageDomainFace {
  return {
    open: async () => ({ table: () => table, close: async () => undefined }),
  };
}

/** A context with a filesystem, one session rooted at `/workspace`, and an optional domain. */
function contextWith(options: { readonly domain?: BookmarkStorageDomainFace } = {}): Context {
  const ctx = new Context();
  ctx.provide("fs", fakeFs());
  ctx.provide("sessions", { get: () => ({ header: { cwd: "/workspace" } }) });
  if (options.domain !== undefined) ctx.provide("storageDomain", options.domain);
  return ctx;
}

describe("bookmark endpoints", () => {
  it("publishes both endpoints beside the workspace ones", () => {
    const service = new FsExplorerWorkspaceService(contextWith());
    expect(remoteMethods(service).map(marker => marker.exportName ?? marker.method)).toEqual([
      "capabilities",
      "info",
      "reveal",
      "create",
      "ignored",
      "loadBookmarks",
      "saveBookmarks",
    ]);
  });

  it("answers a null tree for a workspace with no stored bookmarks", async () => {
    const service = new FsExplorerWorkspaceService(contextWith({ domain: fakeDomain(fakeTable()) }));
    await expect(service.loadBookmarks({ sessionId: "s1" })).resolves.toEqual({ ok: true, tree: null });
  });

  it("round-trips a tree through save and load", async () => {
    const table = fakeTable();
    const service = new FsExplorerWorkspaceService(contextWith({ domain: fakeDomain(table) }));
    await expect(service.saveBookmarks({ sessionId: "s1", tree: tree() })).resolves.toEqual({ ok: true });
    await expect(service.loadBookmarks({ sessionId: "s1" })).resolves.toEqual({ ok: true, tree: tree() });
  });

  it("keys the record by the workspace's canonical path", async () => {
    // Two sessions in one workspace must share one record, which is what makes
    // the bookmark bar the same in both.
    const table = fakeTable();
    const ctx = contextWith({ domain: fakeDomain(table) });
    const service = new FsExplorerWorkspaceService(ctx);
    await service.saveBookmarks({ sessionId: "s1", tree: tree() });
    expect([...table.rows.keys()]).toEqual(["/workspace"]);
    await expect(service.loadBookmarks({ sessionId: "s2" })).resolves.toEqual({ ok: true, tree: tree() });
  });

  it("answers no-storage when the host has no storage domain", async () => {
    const service = new FsExplorerWorkspaceService(contextWith());
    await expect(service.loadBookmarks({ sessionId: "s1" })).resolves.toMatchObject({
      ok: false,
      error: { code: "no-storage" },
    });
    await expect(service.saveBookmarks({ sessionId: "s1", tree: tree() })).resolves.toMatchObject({
      ok: false,
      error: { code: "no-storage" },
    });
  });

  it("answers no-workspace before touching storage", async () => {
    const table = fakeTable();
    const ctx = new Context();
    ctx.provide("fs", fakeFs());
    ctx.provide("storageDomain", fakeDomain(table));
    const service = new FsExplorerWorkspaceService(ctx);
    await expect(service.loadBookmarks({ sessionId: "ghost" })).resolves.toMatchObject({
      ok: false,
      error: { code: "no-workspace" },
    });
    expect(table.rows.size).toBe(0);
  });

  it("reads a corrupt record as a null tree instead of failing", async () => {
    const table = fakeTable({ "/workspace": { version: 1, roots: "not an array" } });
    const service = new FsExplorerWorkspaceService(contextWith({ domain: fakeDomain(table) }));
    await expect(service.loadBookmarks({ sessionId: "s1" })).resolves.toEqual({ ok: true, tree: null });
  });

  it("refuses to save a tree the parser rejects", async () => {
    const table = fakeTable();
    const service = new FsExplorerWorkspaceService(contextWith({ domain: fakeDomain(table) }));
    const broken = { version: 1, roots: [{ id: "", kind: "file", name: "x", path: "x", createdAt: 1 }], updatedAt: "t" };
    await expect(
      service.saveBookmarks({ sessionId: "s1", tree: broken as unknown as BookmarkTree }),
    ).resolves.toMatchObject({ ok: false, error: { code: "io-error" } });
    expect(table.rows.size).toBe(0);
  });

  it("reports a storage failure as io-error", async () => {
    const domain: BookmarkStorageDomainFace = {
      open: async () => ({
        table: () => ({
          get: () => undefined,
          put: async () => {
            throw new Error("disk full");
          },
          delete: async () => undefined,
          entries: () => new Map<string, unknown>().entries(),
        }),
        close: async () => undefined,
      }),
    };
    const service = new FsExplorerWorkspaceService(contextWith({ domain }));
    await expect(service.saveBookmarks({ sessionId: "s1", tree: tree() })).resolves.toMatchObject({
      ok: false,
      error: { code: "io-error" },
    });
  });
});

/**
 * The bookmark tree's wire contract and its storage domain.
 *
 * Two things are load-bearing here. `parseBookmarkTree` is the only gate between
 * a JSON blob and the model, so every field it accepts has to be one the model
 * can actually use, and a record it rejects must be rejected with a sentence a
 * human can act on rather than a stack trace. And the domain spec has to be the
 * shape `storageDomain.open()` reads: a bare schema instead of a `valueSchema`
 * wrapper stays invisible while the table is empty and turns the first boot
 * after a record lands into a fatal load failure.
 */
import { describe, expect, it, vi } from "vitest";

import {
  BOOKMARK_DOMAIN_NAME,
  BOOKMARK_DOMAIN_SPEC,
  BOOKMARK_TABLE_NAME,
  parseBookmarkTree,
  type BookmarkTree,
} from "../src/bookmarks.ts";
import {
  openBookmarkStore,
  type BookmarkStorageDomainFace,
  type BookmarkTableFace,
} from "../src/host/bookmarks.ts";

/** One valid tree, deep enough to exercise the nested branch. */
function validTree(): BookmarkTree {
  return {
    version: 1,
    updatedAt: "2026-11-03T00:00:00.000Z",
    roots: [
      {
        id: "g1",
        kind: "group",
        name: "Work",
        createdAt: 1,
        children: [
          { id: "f1", kind: "file", name: "a.md", path: "docs/a.md", createdAt: 2 },
          { id: "d1", kind: "folder", name: "docs", path: "docs", createdAt: 3 },
        ],
      },
      { id: "f2", kind: "file", name: "README", path: "README.md", createdAt: 4 },
    ],
  };
}

/** A tree with one field replaced, for the rejection cases. */
function withRoots(roots: unknown): unknown {
  return { ...validTree(), roots };
}

describe("parseBookmarkTree", () => {
  it("accepts a valid tree and hands back a copy", () => {
    const input = validTree();
    const parsed = parseBookmarkTree(input);
    expect(parsed).toEqual(input);
    // A copy, not the same object: the store hands the parsed value to the
    // model, and the model's operations must not reach back into the caller's.
    expect(parsed).not.toBe(input);
    expect(parsed.roots[0]).not.toBe(input.roots[0]);
  });

  it("accepts an empty tree", () => {
    expect(parseBookmarkTree({ version: 1, roots: [], updatedAt: "2026-11-03T00:00:00.000Z" })).toEqual({
      version: 1,
      roots: [],
      updatedAt: "2026-11-03T00:00:00.000Z",
    });
  });

  it("rejects a non-object", () => {
    for (const value of [null, undefined, 42, "tree", []]) {
      expect(() => parseBookmarkTree(value), JSON.stringify(value)).toThrowError(/object/u);
    }
  });

  it("rejects a version other than 1", () => {
    expect(() => parseBookmarkTree({ ...validTree(), version: 2 })).toThrowError(/version/u);
    expect(() => parseBookmarkTree({ ...validTree(), version: "1" })).toThrowError(/version/u);
  });

  it("rejects roots that are not an array", () => {
    expect(() => parseBookmarkTree(withRoots({}))).toThrowError(/roots/u);
    expect(() => parseBookmarkTree(withRoots(undefined))).toThrowError(/roots/u);
  });

  it("rejects a missing updatedAt", () => {
    const { updatedAt: _omitted, ...without } = validTree();
    expect(() => parseBookmarkTree(without)).toThrowError(/updatedAt/u);
  });

  it("rejects an unknown kind", () => {
    expect(() =>
      parseBookmarkTree(withRoots([{ id: "x", kind: "symlink", name: "x", path: "x", createdAt: 1 }])),
    ).toThrowError(/kind/u);
  });

  it("rejects a node missing a field", () => {
    expect(() => parseBookmarkTree(withRoots([{ id: "x", kind: "file", name: "x", createdAt: 1 }]))).toThrowError(
      /path/u,
    );
    expect(() => parseBookmarkTree(withRoots([{ kind: "file", name: "x", path: "x", createdAt: 1 }]))).toThrowError(
      /id/u,
    );
    expect(() => parseBookmarkTree(withRoots([{ id: "x", kind: "file", path: "x", createdAt: 1 }]))).toThrowError(
      /name/u,
    );
  });

  it("rejects an empty id, name or path", () => {
    expect(() => parseBookmarkTree(withRoots([{ id: "", kind: "file", name: "x", path: "x", createdAt: 1 }]))).toThrowError(
      /id/u,
    );
    expect(() =>
      parseBookmarkTree(withRoots([{ id: "x", kind: "file", name: "  ", path: "x", createdAt: 1 }])),
    ).toThrowError(/name/u);
    expect(() => parseBookmarkTree(withRoots([{ id: "x", kind: "file", name: "x", path: "", createdAt: 1 }]))).toThrowError(
      /path/u,
    );
  });

  it("rejects a non-numeric createdAt", () => {
    expect(() =>
      parseBookmarkTree(withRoots([{ id: "x", kind: "file", name: "x", path: "x", createdAt: "1" }])),
    ).toThrowError(/createdAt/u);
  });

  it("rejects a group whose children are not an array", () => {
    expect(() =>
      parseBookmarkTree(withRoots([{ id: "g", kind: "group", name: "g", createdAt: 1, children: {} }])),
    ).toThrowError(/children/u);
  });

  it("rejects a group without children", () => {
    expect(() => parseBookmarkTree(withRoots([{ id: "g", kind: "group", name: "g", createdAt: 1 }]))).toThrowError(
      /children/u,
    );
  });

  it("rejects a duplicate id anywhere in the tree", () => {
    const duplicated = withRoots([
      { id: "same", kind: "file", name: "a", path: "a", createdAt: 1 },
      { id: "same", kind: "file", name: "b", path: "b", createdAt: 2 },
    ]);
    expect(() => parseBookmarkTree(duplicated)).toThrowError(/duplicate|already/u);
  });

  it("rejects a duplicate id across nesting levels", () => {
    const duplicated = withRoots([
      {
        id: "g",
        kind: "group",
        name: "g",
        createdAt: 1,
        children: [{ id: "g", kind: "file", name: "a", path: "a", createdAt: 2 }],
      },
    ]);
    expect(() => parseBookmarkTree(duplicated)).toThrowError(/duplicate|already/u);
  });

  it("rejects nesting deeper than 32", () => {
    /**
     * A chain of `groups` nested groups with one leaf at the bottom.
     *
     * Depth counts from 1 at the root, so a leaf under 31 groups sits at depth
     * 32 and one under 32 groups sits at 33.
     */
    const chain = (groups: number): unknown => {
      let node: unknown = { id: "leaf", kind: "file", name: "leaf", path: "leaf", createdAt: 1 };
      for (let index = groups; index >= 1; index -= 1) {
        node = { id: `g${String(index)}`, kind: "group", name: `g${String(index)}`, createdAt: 1, children: [node] };
      }
      return node;
    };
    // Depth 32 is the last accepted level; 33 is refused.
    expect(() => parseBookmarkTree(withRoots([chain(31)]))).not.toThrow();
    expect(() => parseBookmarkTree(withRoots([chain(32)]))).toThrowError(/deep|depth/u);
  });
});

describe("BOOKMARK_DOMAIN_SPEC", () => {
