import { describe, expect, it } from "vitest";

import { families } from "dsh-preview-viewers/formats.ts";

import { renderMarkdown } from "../src/client/markdown.ts";
import {
  classifyPreviewFailure,
  createPreviewLoader,
  describePage,
  extensionsOfFamily,
  familyOf,
  IDLE_PREVIEW,
  isBinaryFamily,
  isMarkdownFile,
  languageFor,
  normalizePreviewPage,
} from "../src/client/preview.ts";

interface ReadCall {
  readonly path: string;
  readonly offset: number;
  readonly limit: number;
}

function reader(pages: readonly unknown[], calls: ReadCall[] = []) {
  let index = 0;
  return {
    calls,
    read: async (path: string, range: { offset?: number; limit?: number }) => {
      calls.push({ path, offset: range.offset ?? 0, limit: range.limit ?? 0 });
      const page = pages[Math.min(index, pages.length - 1)];
      index += 1;
      return page;
    },
  };
}

describe("languageFor", () => {
  it("maps the common suffixes to language ids", () => {
    expect(languageFor("a.ts")).toBe("javascript");
    expect(languageFor("a.tsx")).toBe("javascript");
    expect(languageFor("a.jsx")).toBe("javascript");
    expect(languageFor("a.json")).toBe("json");
    expect(languageFor("a.md")).toBe("markdown");
    expect(languageFor("README.MD")).toBe("markdown");
    expect(languageFor("a.css")).toBe("css");
    expect(languageFor("a.html")).toBe("html");
    expect(languageFor("a.yml")).toBe("yaml");
    expect(languageFor("a.yaml")).toBe("yaml");
    expect(languageFor("src/deep/a.ts")).toBe("javascript");
    expect(languageFor("LICENSE")).toBe("plaintext");
  });

  it("treats only markdown ids as the reading mode", () => {
    expect(isMarkdownFile("docs/a.md")).toBe(true);
    expect(isMarkdownFile("a.ts")).toBe(false);
  });
});

describe("family routing", () => {
  it("maps every catalogued suffix to its family", () => {
    expect(familyOf("model.glb")).toBe("scene3d");
    expect(familyOf("model.gltf")).toBe("scene3d");
    expect(familyOf("model.obj")).toBe("scene3d");
    expect(familyOf("model.stl")).toBe("scene3d");
    expect(familyOf("model.3mf")).toBe("scene3d");
    expect(familyOf("scan.tif")).toBe("raster");
    expect(familyOf("scan.tiff")).toBe("raster");
    expect(familyOf("photo.avif")).toBe("raster");
    expect(familyOf("drawing.dxf")).toBe("cad");
  });

  it("reads the suffix from the basename, whatever its case", () => {
    expect(familyOf("assets/deep/MODEL.GLB")).toBe("scene3d");
    expect(familyOf("a.b/scan.TIFF")).toBe("raster");
    expect(familyOf("drawing.DXF")).toBe("cad");
  });

  it("claims nothing for a name it does not own", () => {
    expect(familyOf("a.ts")).toBeNull();
    expect(familyOf("README")).toBeNull();
    expect(familyOf("archive.glb.bak")).toBeNull();
    expect(familyOf(".glb")).toBeNull();
  });

  it("routes exactly the family suffixes and leaves the text mapping alone", () => {
    for (const family of families()) {
      for (const suffix of extensionsOfFamily(family)) {
        expect(familyOf(`x.${suffix}`)).toBe(family);
        expect(isBinaryFamily(`x.${suffix}`)).toBe(true);
        // The text pager's table never claimed these; if it started to, the
        // binary branch would be shadowed by a language id nobody can render.
        expect(languageFor(`x.${suffix}`)).toBe("plaintext");
      }
    }
    expect(isBinaryFamily("a.ts")).toBe(false);
    expect(isBinaryFamily("a.md")).toBe(false);
  });

  it("routes an image to the image family instead of the text pager's binary refusal", () => {
    // The pager asks the host for lines and refuses anything that is not UTF-8,
    // so a png reaching it would spend a read to arrive at "not a text file".
    // Claiming the suffix before the pager runs is the whole point of the
    // family, so this is asserted per suffix rather than through the catalogue
    // loop above, which would pass even if the family were empty.
    for (const suffix of ["png", "jpg", "jpeg", "gif", "webp", "bmp", "ico", "svg"]) {
      expect(isBinaryFamily(`shots/hero.${suffix}`), suffix).toBe(true);
      expect(familyOf(`shots/hero.${suffix}`), suffix).toBe("image");
    }
    // The suffixes the pager does handle stay with it.
    expect(isBinaryFamily("notes.md")).toBe(false);
    expect(isBinaryFamily("src/main.ts")).toBe(false);
  });
});

describe("createPreviewLoader", () => {  it("reads one page, advances the offset and stops at eof", async () => {
    const files = reader([
      { text: "l1\nl2", lines: 2, totalLines: 4, eof: false },
      { text: "l3\nl4", lines: 2, totalLines: 4, eof: true },
    ]);
    const loader = createPreviewLoader({ files, maxLines: 200 });
    await loader.open("a.ts");
    expect(files.calls).toEqual([{ path: "a.ts", offset: 0, limit: 200 }]);
    expect(loader.getSnapshot()).toMatchObject({ status: "ready", offset: 1, lines: 2, eof: false });
    expect(describePage(loader.getSnapshot())).toEqual({ range: "1–2", total: "4" });

    await loader.next();
    expect(files.calls[1]).toEqual({ path: "a.ts", offset: 3, limit: 200 });
    expect(loader.getSnapshot()).toMatchObject({ status: "ready", offset: 3, lines: 2, eof: true });

    await loader.next();
    expect(files.calls).toHaveLength(2);
  });

  it("returns to the previous page start without guessing the page size", async () => {
    const files = reader([
      { text: "a\nb", lines: 2, eof: false },
      { text: "c\nd", lines: 2, eof: false },
    ]);
    const loader = createPreviewLoader({ files, maxLines: 2 });
    await loader.open("a.txt");
    await loader.next();
    expect(files.calls[1]?.offset).toBe(3);
    await loader.prev();
    // Page one omits `offset` so the host's 1-based default applies.
    expect(files.calls[2]?.offset).toBe(0);
    expect(loader.getSnapshot().offset).toBe(1);
  });

  it("classifies a deleted file and retries the same page", async () => {
    let attempt = 0;
    const loader = createPreviewLoader({
      files: {
        read: async () => {
          attempt += 1;
          if (attempt === 1) throw Object.assign(new Error("ENOENT: no such file"), { code: "ENOENT" });
          return { text: "ok", lines: 1, eof: true };
        },
      },
      maxLines: 10,
    });
    await loader.open("gone.ts");
    expect(loader.getSnapshot().status).toBe("failed");
    expect(loader.getSnapshot().failure?.kind).toBe("deleted");
    await loader.retry();
    expect(loader.getSnapshot().status).toBe("ready");
  });

  it("abandons a page that settles after a newer selection", async () => {
    let release: (() => void) | undefined;
    const loader = createPreviewLoader({
      files: {
        read: (path) => {
          if (path === "slow.ts") {
            return new Promise(resolve => {
              release = () => resolve({ text: "slow", lines: 1, eof: true });
            });
          }
          return { text: "fast", lines: 1, eof: true };
        },
      },
      maxLines: 10,
    });
    const slow = loader.open("slow.ts");
    await loader.open("fast.ts");
    release?.();
    await slow;
    expect(loader.getSnapshot()).toMatchObject({ status: "ready", path: "fast.ts", text: "fast" });
    expect(loader.getSnapshot()).not.toEqual(IDLE_PREVIEW);
  });
});

describe("normalizePreviewPage", () => {
  it("folds the Remote envelope and keeps the host's offset", () => {
    const page = normalizePreviewPage(
      { ok: true, value: { text: "a\nb\nc", lines: 3, offset: 201, eof: true, absolutePath: "/x", version: "v" } },
      201,
    );
    expect(page).toEqual({ text: "a\nb\nc", lines: 3, offset: 201, eof: true });
  });

  it("derives the line count when the host omits it", () => {
    expect(normalizePreviewPage({ text: "a\nb", eof: false }, 1)).toMatchObject({ lines: 2, offset: 1 });
    expect(normalizePreviewPage({ text: "", lines: 0, eof: true }, 5)).toMatchObject({ lines: 0, eof: true });
  });

  it("keeps the first-parent marker a deleted-file page carries", () => {
    expect(normalizePreviewPage({ text: "kept", lines: 1, offset: 1, eof: true, source: "first-parent" }, 1)).toMatchObject({
      source: "first-parent",
    });
    expect(normalizePreviewPage({ text: "kept", lines: 1, offset: 1, eof: true }, 1)).not.toHaveProperty("source");
  });

  it("throws the host's error code and detail", () => {
    expect(() =>
      normalizePreviewPage({ ok: false, error: { code: "workspace-file/not-regular-file", message: "symlink" } }, 1),
    ).toThrowError(/symlink/u);
    try {
      normalizePreviewPage(
        { ok: false, error: { code: "workspace-file/not-regular-file", message: "not a regular file", details: { kind: "symlink" } } },
        1,
      );
    } catch (error) {
      expect(classifyPreviewFailure(error)).toMatchObject({ kind: "symlink" });
    }
  });
});

describe("classifyPreviewFailure", () => {
  it("separates deleted, denied and symlink failures", () => {
    expect(classifyPreviewFailure(Object.assign(new Error("ENOENT"), { code: "ENOENT" })).kind).toBe("deleted");
    expect(classifyPreviewFailure(Object.assign(new Error("EACCES: permission denied"), { code: "EACCES" })).kind).toBe("denied");
    expect(classifyPreviewFailure({ code: "workspace-file/not-regular-file", detail: "symlink" }).kind).toBe("symlink");
    expect(classifyPreviewFailure(new Error("workspace-file/not-text")).kind).toBe("binary");
    expect(classifyPreviewFailure(new Error("something odd")).kind).toBe("unknown");
  });

  it("separates the commit-only refusals from working-tree failures", () => {
    expect(classifyPreviewFailure({ code: "git/submodule", message: "这是一个子模块，没有可预览的文本内容" }).kind).toBe("submodule");
    expect(classifyPreviewFailure({ code: "git/binary", message: "该提交版本中的文件是二进制，无法预览" }).kind).toBe("commit-binary");
    // A working-tree binary keeps the plain binary copy, not the commit one.
    expect(classifyPreviewFailure({ code: "workspace-file/not-text", message: "not UTF-8" }).kind).toBe("binary");
  });
});

describe("renderMarkdown", () => {
  it("returns an element tree with no raw HTML or event attributes", () => {
    const tree = renderMarkdown(
      ["# 标题", "", "- 一项", "- 另一项", "", "```ts", "const x = 1", "```", "", '<img src=x onerror="alert(1)">', "", "<script>alert(2)</script>"].join(
        "\n",
      ),
    );
    const types = new Set<string>();
    const texts: string[] = [];
    const walk = (node: unknown): void => {
      if (node === null || node === undefined || typeof node !== "object") {
        if (typeof node === "string") texts.push(node);
        return;
      }
      if (Array.isArray(node)) {
        for (const child of node) walk(child);
        return;
      }
      const element = node as { type?: unknown; props?: Record<string, unknown> };
      if (typeof element.type === "string") types.add(element.type);
      const props = element.props ?? {};
      expect(props).not.toHaveProperty("dangerouslySetInnerHTML");
      expect(Object.keys(props).some(key => /^on[A-Z]/u.test(key))).toBe(false);
      walk(props.children);
    };
    walk(tree);
    for (const want of ["h1", "ul", "code", "p"]) expect(types.has(want)).toBe(true);
    expect(texts.join("")).toContain('<img src=x onerror="alert(1)">');
    expect(texts.join("")).toContain("<script>alert(2)</script>");
  });

  it("keeps links to safe schemes only", () => {
    const tree = renderMarkdown("[ok](https://example.com) [bad](javascript:alert(1))");
    const anchors: Record<string, unknown>[] = [];
    const walk = (node: unknown): void => {
      if (node === null || typeof node !== "object") return;
      if (Array.isArray(node)) {
        for (const child of node) walk(child);
        return;
      }
      const element = node as { type?: unknown; props?: Record<string, unknown> };
      if (element.type === "a") anchors.push(element.props ?? {});
      walk(element.props?.children);
    };
    walk(tree);
    expect(anchors).toHaveLength(1);
    expect(anchors[0]?.href).toBe("https://example.com");
  });
});

/**
 * File references: the payload's three spellings, the source that gives a chip
 * its send-time identity, the two-channel writer's state machine, and the two
 * menus that offer the row.
 *
 * The writer is exercised through an injected deps object rather than a host,
 * because the interesting behaviour is entirely in the order it tries the
 * channels and in what it does when the composer refuses. The menus are called
 * directly: they are pure functions of their input, which is the whole reason
 * they live outside React.
 */
import { describe, expect, it, vi } from "vitest";

import {
  FS_REFERENCE_SOURCE,
  createFsReferenceSource,
  fsRefClipboardText,
  fsRefModelText,
  fsReferencePayload,
  insertFsReference,
  normalizeReferencePath,
  openFsReference,
  referenceBlockReason,
  referenceLabel,
  registerFsReferenceSource,
  type FsInsertionDeps,
  type FsReferenceInsert,
  type FsReferenceSeam,
  type FsReferenceSpan,
} from "../src/client/reference.ts";
import { createReferenceResolver } from "../src/client/entry.ts";
import {
  MENU_ACTION,
  TAB_MENU_ACTION,
  buildContextMenu,
  buildTabMenu,
  tabReferenceBlockReason,
  type ContextMenuEntry,
  type ContextMenuRow,
} from "../src/client/context-menu.ts";
import type { PanelEntry } from "../src/client/panels.ts";

/** Identity translator: labels come back as their keys, which is what we assert. */
const t = (key: string): string => key;

function fileRow(): ContextMenuRow {
  return { type: "entry", path: "src/client/view.tsx", name: "view.tsx", kind: "file" };
}

function directoryRow(): ContextMenuRow {
  return { type: "entry", path: "src/client", name: "client", kind: "directory" };
}

function panel(path: string, extra: Partial<PanelEntry> = {}): PanelEntry {
  return { key: path, path, line: 1, absolute: false, ...extra };
}

/** The reference row of a built menu. */
function referenceEntry(entries: readonly ContextMenuEntry[]): ContextMenuEntry | undefined {
  return entries.find(candidate => candidate.id === MENU_ACTION.reference);
}

