// @vitest-environment jsdom
/**
 * The tree's search, as the reader meets it.
 *
 * Two properties decide whether this feature is usable at all, and neither is
 * visible from the pure functions alone: the search input must sit outside the
 * container that owns the tree's key handler (or every typed letter is eaten by
 * the prefix jump), and the results must come from the workspace index when the
 * host has one, saying so when it does not.
 */
import { act, createElement } from "react";
import { createRoot, type Root } from "react-dom/client";
import { afterEach, beforeEach, describe, expect, it } from "vitest";

import { createFsExplorerView, type WorkbenchFace } from "../src/client/view.tsx";

(globalThis as { IS_REACT_ACT_ENVIRONMENT?: boolean }).IS_REACT_ACT_ENVIRONMENT = true;

const t = (key: string): string => key;

const workbench: WorkbenchFace = {
  version: 1,
  currentSessionId: () => "s1",
  openViewOrSwitch: () => ({ opened: true, focused: true }),
};

/** The listing the tree reads; enough rows that search has something to filter. */
function files(): {
  list: () => Promise<unknown>;
  read: () => Promise<unknown>;
} {
  // Keys are the paths the view's ledger sends on the wire: `"."` for the root
  // and the workspace-relative path for everything else.
  const levels: Record<string, { name: string; kind: "file" | "directory" }[]> = {
    ".": [
      { name: "README.md", kind: "file" },
      { name: "src", kind: "directory" },
    ],
    src: [{ name: "tree.tsx", kind: "file" }],
  };
  return {
    list: async (_sessionId?: string, path?: string) => ({
      entries: levels[path ?? "."] ?? [],
    }),
    read: async () => ({ text: "# readme", offset: 1, total: 1, eof: true }),
  };
}

describe("tree search", () => {
  let host: HTMLDivElement;
  let root: Root;

  beforeEach(() => {
    host = document.createElement("div");
    document.body.append(host);
    root = createRoot(host);
  });

  afterEach(async () => {
    await act(async () => {
      root.unmount();
    });
    host.remove();
  });

  /** Mount the view; `face` is the optional workspace index. */
  async function show(face?: { list: (agentId: string, query: string, signal?: AbortSignal) => Promise<unknown> }): Promise<void> {
    const View = createFsExplorerView({
      workbench,
      version: 1,
      t,
      files,
      status: () => undefined,
      ...(face === undefined ? {} : { fileReferences: () => face }),
    });
    await act(async () => {
      root.render(createElement(View, { sessionId: "s1" }));
    });
    // The root listing plus a paint.
    await act(async () => {
      await Promise.resolve();
      await Promise.resolve();
      await Promise.resolve();
    });
  }

  async function openSearch(): Promise<void> {
    await act(async () => {
      host.querySelector<HTMLElement>('[data-testid="fs-search-open"]')?.dispatchEvent(
        new MouseEvent("click", { bubbles: true }),
      );
    });
  }

  function searchInput(): HTMLInputElement | null {
    return host.querySelector<HTMLInputElement>('[data-testid="fs-tree-search-input"]');
  }

  async function type(value: string): Promise<void> {
    const input = host.querySelector<HTMLInputElement>('[data-testid="fs-tree-search-input"]');
    if (input === null) throw new Error("no search input");
    const setter = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, "value")?.set;
    await act(async () => {
      setter?.call(input, value);
      input.dispatchEvent(new Event("input", { bubbles: true }));
    });
    await act(async () => {
      await Promise.resolve();
      await Promise.resolve();
    });
  }

  function scopes(): string | null {
    return host.querySelector('[data-testid="fs-tree-search-scope"]')?.getAttribute("data-origin") ?? null;
  }

  function resultPaths(): (string | null)[] {
    return [...host.querySelectorAll<HTMLElement>('[data-testid="fx-row"]')].map(row => row.getAttribute("title"));
  }

  it("puts the search input inside the tree pane but outside the tree's scroll container", async () => {
    await show();

    const input = host.querySelector('[data-testid="fs-tree-search-input"]');
    const pane = host.querySelector(".fx-tree-pane");
    const scroll = host.querySelector('[data-testid="fs-tree-scroll"]');

    expect(input).not.toBeNull();
    expect(pane?.contains(input)).toBe(true);
    // This is the property that keeps the prefix jump from eating typed letters.
    expect(scroll?.contains(input)).toBe(false);
  });

  it("shows the bar from the first paint without taking the keyboard", async () => {
    // The bar has to exist before anyone asks for it: jump navigation labels a
    // target that is already in the DOM, and a field that appears only after a
    // click cannot be labelled. Staying out of focus is the other half, because
    // arriving in the pane parks the keyboard on the tree.
    await show();

    expect(searchInput()).not.toBeNull();
    expect(document.activeElement?.getAttribute("data-testid")).toBe("fs-tree-scroll");
  });

  it("puts the caret in the field when the header asks for it", async () => {
    await show();
    await openSearch();

    expect(document.activeElement).toBe(searchInput());
  });

  it("searches the workspace index and labels the scope as the index", async () => {
    const asked: string[] = [];
    await show({
      list: async (_agentId, query) => {
        asked.push(query);
        return { ok: true, value: [{ path: "src/deep/hidden.ts", kind: "file" }] };
      },
    });
    await openSearch();
    await type("hidden");

    expect(asked).toEqual(["hidden"]);
    expect(resultPaths()).toEqual(["src/deep/hidden.ts"]);
    expect(scopes()).toBe("index");
  });

  it("shows the directory prefix beside a flat result row", async () => {
    await show({
      list: async () => ({ ok: true, value: [{ path: "src/deep/hidden.ts", kind: "file" }] }),
    });
    await openSearch();
    await type("hidden");

    expect(host.querySelector('[data-testid="fx-row-dir"]')?.textContent).toBe("src/deep");
  });

  it("falls back to the listed rows and says the scope is narrower", async () => {
    await show();
    await openSearch();
    await type("readme");

    expect(resultPaths()).toEqual(["README.md"]);
    // The degenerate case a reader must be able to notice: a smaller answer.
    expect(scopes()).toBe("loaded");
  });

  it("restores the tree when the query is cleared", async () => {
    await show();
    await openSearch();
    await type("readme");
    expect(resultPaths()).toEqual(["README.md"]);

    await type("");
    expect(resultPaths()).toContain("src");
    expect(host.querySelector('[data-testid="fs-tree-search-scope"]')).toBeNull();
  });

  it("survives an index that never answers", async () => {
    // A refusal envelope is not an error state here; it is an empty answer.
    await show({ list: async () => ({ ok: false, error: { code: "denied" } }) });
    await openSearch();
    await type("readme");

    expect(resultPaths()).toEqual([]);
    expect(scopes()).toBe("index");
  });

  it("closes on Escape and hands the keyboard back to the tree", async () => {
    await show();
    await openSearch();
    await type("readme");

    await act(async () => {
      host
        .querySelector('[data-testid="fs-tree-search-input"]')
        ?.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true }));
    });

    // The bar stays as furniture; what Escape drops is the query, so the tree is
    // back and the keyboard with it.
    expect(searchInput()?.value).toBe("");
    expect(resultPaths()).toContain("src");
    expect(document.activeElement?.getAttribute("data-testid")).toBe("fs-tree-scroll");
  });

  it("steps the result cursor with the arrow keys", async () => {
    await show({
      list: async () => ({
        ok: true,
        value: [
          { path: "a.ts", kind: "file" },
          { path: "b.ts", kind: "file" },
        ],
      }),
    });
    await openSearch();
    await type(".ts");

    const input = host.querySelector('[data-testid="fs-tree-search-input"]');
    await act(async () => {
      input?.dispatchEvent(new KeyboardEvent("keydown", { key: "ArrowDown", bubbles: true }));
    });
    await act(async () => {
      input?.dispatchEvent(new KeyboardEvent("keydown", { key: "ArrowDown", bubbles: true }));
    });

    // The caret stays in the field: the reader is still typing, so the result
    // cursor moves without stealing focus from the input.
    expect(document.activeElement).toBe(input);
    const cursor = host.querySelector('[data-testid="fx-row"][data-cursor="true"]');
    expect(cursor?.getAttribute("title")).toBe("b.ts");
  });
});

/**
 * The tree's search, driven without a renderer.
 *
 * The two paths answer different questions and must not be confused: the index
 * path answers "which file in this workspace", the fallback answers "which file
 * I have already seen listed". What is worth pinning is that the panel can tell
 * the two apart, because it puts that difference on screen.
 */
import { describe, expect, it } from "vitest";

import type { TreeLevel } from "../src/client/model.ts";
import {
  createFileReferencesResolver,
  filterListedEntries,
  isFileReferencesFace,
  listedEntries,
  normalizeReferences,
  referenceRows,
  resultDirectory,
  revealChain,
  searchQuery,
} from "../src/client/tree-search.ts";

/** A ready level holding the given names. */
function ready(names: readonly { readonly name: string; readonly kind: "directory" | "file" }[]): TreeLevel {
  return { status: "ready", nodes: names, truncated: false, total: names.length };
}

describe("resolving the workspace index", () => {
  it("finds the face on the context directly", () => {
    const face = { list: async () => ({ ok: true as const, value: [] }) };
    const resolve = createFileReferencesResolver({ fileReferences: face });
    expect(resolve?.()).toBe(face);
  });

  it("finds it under the dotted remote namespace", () => {
    const face = { list: async () => ({ ok: true as const, value: [] }) };
    const resolve = createFileReferencesResolver({ get: name => (name === "remote.fileReferences" ? face : undefined) });
    expect(resolve?.()).toBe(face);
  });

  it("answers undefined rather than throwing on an unmounted stub", () => {
    const resolve = createFileReferencesResolver({
      get: () => {
        throw new Error("service not mounted");
      },
    });
    expect(resolve?.()).toBeUndefined();
  });

  it("re-reads the context, so a late mount starts working", () => {
    let face: unknown;
    const resolve = createFileReferencesResolver({ get: name => (name === "remote.fileReferences" ? face : undefined) });
    expect(resolve?.()).toBeUndefined();
    const mounted = { list: async () => ({ ok: true as const, value: [] }) };
    face = mounted;
    expect(resolve?.()).toBe(mounted);
  });

  it("rejects a stub without the list method", () => {
    expect(isFileReferencesFace({})).toBe(false);
    expect(isFileReferencesFace({ list: "nope" })).toBe(false);
    expect(isFileReferencesFace(null)).toBe(false);
  });
});

describe("normalizing an index answer", () => {
  it("unwraps the Remote envelope", () => {
    expect(normalizeReferences({ ok: true, value: [{ path: "a/b.ts", kind: "file" }] })).toEqual([
      { path: "a/b.ts", kind: "file" },
    ]);
  });

  it("accepts a bare array from a direct service", () => {
    expect(normalizeReferences([{ path: "a.ts", kind: "file" }])).toEqual([{ path: "a.ts", kind: "file" }]);
  });

  it("reads a refusal as no candidates", () => {
    expect(normalizeReferences({ ok: false, error: { code: "nope" } })).toEqual([]);
  });

  it("drops entries the row vocabulary cannot paint", () => {
    expect(
      normalizeReferences([
        { path: "keep.ts", kind: "file" },
        { path: "", kind: "file" },
        { path: "no-kind.ts" },
        { path: "weird.ts", kind: "socket" },
        null,
      ]),
    ).toEqual([{ path: "keep.ts", kind: "file" }]);
  });
});

describe("searchQuery", () => {
  it("trims and rejects an empty query", () => {
    expect(searchQuery("  docs  ")).toBe("docs");
    expect(searchQuery("   ")).toBeUndefined();
  });
});

describe("referenceRows", () => {
  it("builds flat entry rows from the index's own order", () => {
    const rows = referenceRows(
      [
        { path: "src/client/tree.tsx", kind: "file" },
        { path: "docs", kind: "directory" },
      ],
      undefined,
    );
    expect(rows.map(row => (row.type === "entry" ? [row.name, row.path, row.depth, row.kind] : null))).toEqual([
      ["tree.tsx", "src/client/tree.tsx", 0, "file"],
      ["docs", "docs", 0, "directory"],
    ]);
  });

  it("carries the file's Git status onto the result row", () => {
    const rows = referenceRows([{ path: "src/a.ts", kind: "file" }], {
      "src/a.ts": { status: "modified", additions: null, deletions: null },
    });
    expect(rows[0]?.type === "entry" ? rows[0].status : undefined).toBe("modified");
  });

  it("drops duplicate and empty paths", () => {
    const rows = referenceRows(
      [
        { path: "a.ts", kind: "file" },
        { path: "a.ts", kind: "file" },
        { path: "./b.ts", kind: "file" },
      ],
      undefined,
    );
    expect(rows.map(row => (row.type === "entry" ? row.path : ""))).toEqual(["a.ts", "b.ts"]);
  });
});

describe("resultDirectory", () => {
  it("answers the parent path a row would otherwise spell by indentation", () => {
    expect(resultDirectory("src/client/tree.tsx")).toBe("src/client");
    expect(resultDirectory("README.md")).toBe("");
  });
});

describe("the loaded-row fallback", () => {
  const levels = new Map<string, TreeLevel>([
    ["", ready([{ name: "src", kind: "directory" }, { name: "README.md", kind: "file" }])],
    ["src", ready([{ name: "tree.tsx", kind: "file" }, { name: "view.tsx", kind: "file" }])],
  ]);

  it("names every entry the ledger holds, not only the expanded ones", () => {
    const paths = listedEntries(levels).map(entry => entry.path);
    expect(paths).toEqual(["src", "README.md", "src/tree.tsx", "src/view.tsx"]);
  });

  it("filters by name, case-insensitively", () => {
    const entries = listedEntries(levels);
    expect(filterListedEntries(entries, "TREE").map(entry => entry.path)).toEqual(["src/tree.tsx"]);
    expect(filterListedEntries(entries, "readme").map(entry => entry.path)).toEqual(["README.md"]);
  });

  it("matches a row's own name, never its parent's", () => {
    // The directory row matches because `src` is its name; its children do not,
    // because `src` appears only in their directory part and their own rows
    // would then carry no visible reason for the hit.
    const entries = listedEntries(levels);
    expect(filterListedEntries(entries, "src").map(entry => entry.path)).toEqual(["src"]);
  });
});

describe("revealChain", () => {
  it("names the ancestors a result row needs opened", () => {
    expect(revealChain("src/client/tree.tsx")).toEqual(["src", "src/client"]);
    expect(revealChain("README.md")).toEqual([]);
  });
});

/**
 * Prefix jump decisions, driven without a renderer.
 *
 * The tree flattens to one list, so the interesting questions are which slice
 * one keystroke searches and how a run of characters folds into a name. Both
 * are pure, which is what keeps the keyboard gesture assertable.
 */
import { describe, expect, it } from "vitest";

import { firstChildIndex, flattenTree, type TreeLevel, type TreeRow } from "../src/client/model.ts";
import {
  entriesInScope,
  liveTypeaheadQuery,
  TYPEAHEAD_WINDOW_MS,
  typeaheadScopeKey,
  typeaheadStep,
  type TypeaheadInput,
} from "../src/client/typeahead.ts";

/** A ready level holding the given names, directories first by convention of the caller. */
function ready(names: readonly { readonly name: string; readonly kind: "directory" | "file" }[]): TreeLevel {
  return {
    status: "ready",
    nodes: names.map(entry => ({ name: entry.name, kind: entry.kind })),
    truncated: false,
    total: names.length,
  };
}

/**
 * The shape from the screenshot: `app` expanded over `assets` and `docs`,
 * `docs` itself expanded over three files.
 */
function fixture(): TreeRow[] {
  const levels = new Map<string, TreeLevel>([
    [
      "",
      ready([
        { name: "app", kind: "directory" },
        { name: "docs", kind: "directory" },
        { name: "README.md", kind: "file" },
      ]),
    ],
    [
      "app",
      ready([
        { name: "assets", kind: "directory" },
        { name: "content", kind: "directory" },
        { name: "docs", kind: "directory" },
        { name: "graphify-out", kind: "directory" },
      ]),
    ],
    [
      "app/docs",
      ready([
        { name: "a.md", kind: "file" },
        { name: "b.md", kind: "file" },
        { name: "data.md", kind: "file" },
      ]),
    ],
  ]);
  return flattenTree(levels, new Set(["app", "app/docs"]));
}

/** Index of one entry path, failing loudly when the fixture moved. */
function at(rows: readonly TreeRow[], path: string): number {
  const index = rows.findIndex(row => row.type === "entry" && row.path === path);
  if (index < 0) throw new Error(`missing ${path}`);
  return index;
}

/** A keystroke with the modifiers a plain character carries. */
function press(over: Partial<TypeaheadInput> & Pick<TypeaheadInput, "names" | "key">): TypeaheadInput {
  return {
    query: "",
    composing: false,
    alt: false,
    meta: false,
    ctrl: false,
    repeat: false,
    active: -1,
    ...over,
  };
}

/** Basenames of one scope, the list the step function actually compares. */
function namesOf(rows: readonly TreeRow[], key: string): string[] {
  return entriesInScope(rows, key).map(index => {
    const row = rows[index];
    if (row?.type !== "entry") throw new Error("scope pointed at a status row");
    return row.name;
  });
}

describe("typeahead scope", () => {
  const rows = fixture();

  it("searches a focused directory's own children, not its grandchildren", () => {
    const cursor = at(rows, "app");
    expect(typeaheadScopeKey(rows, cursor)).toBe("app");
    const indexes = entriesInScope(rows, "app");
    expect(indexes.map(index => (rows[index] as { path: string }).path)).toEqual([
      "app/assets",
      "app/content",
      "app/docs",
      "app/graphify-out",
    ]);
  });

  it("searches a focused file's siblings", () => {
    expect(typeaheadScopeKey(rows, at(rows, "app/docs/b.md"))).toBe("app/docs");
    expect(namesOf(rows, "app/docs")).toEqual(["a.md", "b.md", "data.md"]);
  });

  it("treats the workspace root as the scope when the cursor rests on a root row", () => {
    expect(typeaheadScopeKey(rows, at(rows, "README.md"))).toBe("");
    expect(namesOf(rows, "")).toEqual(["app", "docs", "README.md"]);
  });

  it("finds nothing under a directory that is collapsed, because its rows are not on screen", () => {
    expect(entriesInScope(rows, "docs")).toEqual([]);
    expect(entriesInScope(rows, "app/missing")).toEqual([]);
  });

  it("starts at the root when no cursor rests anywhere", () => {
    expect(typeaheadScopeKey(rows, undefined)).toBe("");
  });
});

describe("drill landing", () => {
  const rows = fixture();

  it("lands on the first child of a directory once it is open", () => {
    const child = firstChildIndex(rows, "app");
    expect(child).toBe(at(rows, "app/assets"));
    // Deeper levels answer with their own first row, not the parent's.
    expect(firstChildIndex(rows, "app/docs")).toBe(at(rows, "app/docs/a.md"));
  });

  it("waits rather than guessing when the directory is collapsed or unknown", () => {
    expect(firstChildIndex(rows, "docs")).toBeUndefined();
    expect(firstChildIndex(rows, "missing")).toBeUndefined();
  });

  it("keeps waiting while the opened directory only shows a placeholder row", () => {
    const loading: TreeRow[] = [
      { type: "entry", path: "app", name: "app", kind: "directory", depth: 0, expanded: true },
      { type: "status", key: "app:loading", path: "app", depth: 1, state: "loading" },
    ];
    expect(firstChildIndex(loading, "app")).toBeUndefined();
  });
});

describe("typeahead step", () => {
  const names = ["assets", "content", "docs", "graphify-out"];

  it("accumulates a prefix and stays on the row it already spells", () => {
    const first = typeaheadStep(press({ names, key: "d", active: -1 }));
    expect(first).toEqual({ kind: "jump", index: 2, query: "d" });
    // `do` still names `docs`, so the cursor does not leap past it.
    const second = typeaheadStep(press({ names, key: "o", query: "d", active: 2 }));
    expect(second).toEqual({ kind: "jump", index: 2, query: "do" });
    expect(typeaheadStep(press({ names, key: "c", query: "do", active: 2 }))).toEqual({
      kind: "jump",
      index: 2,
      query: "doc",
    });
    expect(typeaheadStep(press({ names, key: "s", query: "doc", active: 2 }))).toEqual({
      kind: "jump",
      index: 2,
      query: "docs",
    });
  });

  it("matches case-insensitively and wraps to the first hit when nothing later matches", () => {
    expect(typeaheadStep(press({ names, key: "G" }))).toEqual({ kind: "jump", index: 3, query: "g" });
    expect(typeaheadStep(press({ names, key: "a", active: 3 }))).toEqual({ kind: "jump", index: 0, query: "a" });
  });

  it("cycles to the next name when the same single character is typed again", () => {
    const doubled = ["data.md", "docs.md", "draft.md"];
    const first = typeaheadStep(press({ names: doubled, key: "d" }));
    expect(first).toEqual({ kind: "jump", index: 0, query: "d" });
    expect(typeaheadStep(press({ names: doubled, key: "d", query: "d", active: 0 }))).toEqual({
      kind: "jump",
      index: 1,
      query: "d",
    });
    expect(typeaheadStep(press({ names: doubled, key: "d", query: "d", active: 2 }))).toEqual({
      kind: "jump",
      index: 0,
      query: "d",
    });
  });

  it("keeps the prefix on a miss so one stray key does not throw the spelling away", () => {
    expect(typeaheadStep(press({ names, key: "z", query: "doc", active: 2 }))).toEqual({ kind: "miss" });
  });

  it("ignores chords, key repeat and an unfinished composition, and clears on Escape", () => {
    expect(typeaheadStep(press({ names, key: "d", meta: true })).kind).toBe("ignore");
    expect(typeaheadStep(press({ names, key: "d", ctrl: true })).kind).toBe("ignore");
    expect(typeaheadStep(press({ names, key: "d", alt: true })).kind).toBe("ignore");
    expect(typeaheadStep(press({ names, key: "d", repeat: true })).kind).toBe("ignore");
    expect(typeaheadStep(press({ names, key: "d", composing: true })).kind).toBe("ignore");
    expect(typeaheadStep(press({ names, key: "ArrowDown" })).kind).toBe("ignore");
    expect(typeaheadStep(press({ names, key: "Escape", query: "doc" }))).toEqual({ kind: "clear" });
  });
});

describe("typeahead window", () => {
  it("forgets the prefix once the pause has elapsed and keeps it just inside the window", () => {
    expect(liveTypeaheadQuery("doc", 1_000, 1_000 + TYPEAHEAD_WINDOW_MS)).toBe("doc");
    expect(liveTypeaheadQuery("doc", 1_000, 1_000 + TYPEAHEAD_WINDOW_MS + 1)).toBe("");
  });
});

