      fileManager: "directory",
      canReveal: true,
    });
  });

  it("names Explorer on WSL, where the Windows desktop takes the path", () => {
    expect(workspaceCapabilities(env({ platform: "linux", env: { WSL_DISTRO_NAME: "Ubuntu" } }))).toEqual({
