/**
 * The GFM table scanner: one case per rule the widget and planner depend on.
 *
 * The scanner decides which lines a widget replaces and where each cell starts,
 * so it is asserted against offsets in Node. Cases come from the GitHub
 * Flavored Markdown table extension, with the shapes this editor meets in real
 * files.
 */
import { describe, expect, it } from "vitest";

import { planTables, splitCells, tableIntersects, type TableBlock } from "../src/client/tables.ts";
import { splitLines } from "../src/client/lines.ts";

/** Cell contents as a reader would see them, for readable assertions. */
function cellTexts(text: string, table: TableBlock): string[][] {
  return [table.header, ...table.rows].map(row => row.cells.map(cell => text.slice(cell.from, cell.to)));
}

/** The first table of a document, failing the test when there is none. */
function only(text: string): TableBlock {
  const tables = planTables(text);
  expect(tables).toHaveLength(1);
  const table = tables[0];
  if (table === undefined) throw new Error("expected one table");
  return table;
}

describe("planTables", () => {
  it("reads a basic table with its header, alignment row and body", () => {
    const text = "| a | b |\n| --- | --- |\n| 1 | 2 |\n";
    const table = only(text);

    expect(table.from).toBe(0);
    expect(table.to).toBe(text.length - 1);
    expect([table.firstLine, table.lastLine]).toEqual([0, 2]);
    expect(table.alignments).toEqual(["none", "none"]);
    expect(cellTexts(text, table)).toEqual([
      ["a", "b"],
      ["1", "2"],
    ]);
  });

  it("accepts outer pipes in any combination", () => {
    const text = "a | b\n| --- | --- |\nc | d\n";
    const table = only(text);

    expect(cellTexts(text, table)).toEqual([
      ["a", "b"],
      ["c", "d"],
    ]);
  });

  it("keeps escaped pipes inside a cell and unescaped ones as boundaries", () => {
    const text = "| a \\| b | c |\n| --- | --- |\n| `x|y` | z |\n";
    const table = only(text);

    expect(cellTexts(text, table)[0]).toEqual(["a \\| b", "c"]);
    // GFM does not protect a pipe inside a code span, so that row splits into
    // three cells and the extra one is dropped when normalized to two columns.
    expect(cellTexts(text, table)[1]).toEqual(["`x", "y`"]);
  });

  it("trims spaces and tabs around every cell", () => {
    const text = "|\ta\t|\t b \t|\n| --- | --- |\n| 1 | 2 |\n";
    expect(cellTexts(text, only(text))[0]).toEqual(["a", "b"]);
  });

  it("reads the three alignment forms", () => {
    const text = "| a | b | c | d |\n| :--- | :---: | ---: | --- |\n";
    expect(only(text).alignments).toEqual(["left", "center", "right", "none"]);
  });

  it("requires the delimiter to carry a pipe and match the header width", () => {
    // No pipe: a setext heading, not a table.
    expect(planTables("a\n---\nb\n")).toEqual([]);
    // Header has two cells, delimiter one.
    expect(planTables("| a | b |\n| --- |\n| 1 | 2 |\n")).toEqual([]);
    // Spaces inside a delimiter cell are not valid.
    expect(planTables("| a |\n| : - : |\n")).toEqual([]);
    // A one-column table is still legal.
    expect(planTables("| a |\n| - |\n")).toHaveLength(1);
  });

  it("ends at the first blank line", () => {
    const text = "| a |\n| --- |\n| 1 |\n\nafter\n";
    const table = only(text);
    expect(table.lastLine).toBe(2);
    expect(table.to).toBe("| a |\n| --- |\n| 1 |".length);
  });

  it("ends at the next block-level structure", () => {
    const tail = ["# heading", "> quote", "- item", "1. item", "---", "```", "~~~", "    code", "<div>"];
    for (const line of tail) {
      const text = `| a |\n| --- |\n| 1 |\n${line}\n`;
      const tables = planTables(text);
      expect(tables, line).toHaveLength(1);
      expect(tables[0]?.lastLine, line).toBe(2);
    }
  });

  it("treats a body line without pipes as a row and pads it to the header width", () => {
    const text = "| a | b |\n| --- | --- |\nbar\n";
    expect(cellTexts(text, only(text))[1]).toEqual(["bar", ""]);
  });

  it("truncates a row that has more cells than the header", () => {
    const text = "| a | b |\n| --- | --- |\n| 1 | 2 | 3 |\n";
    expect(cellTexts(text, only(text))[1]).toEqual(["1", "2"]);
  });

  it("interrupts a paragraph when the header line follows it directly", () => {
    const text = "intro\n| a | b |\n| --- | --- |\n| 1 | 2 |\n";
    const table = only(text);
    expect(table.firstLine).toBe(1);
  });

  it("does not read a table inside a closed fence", () => {
    const text = "```md\n| a |\n| --- |\n| 1 |\n```\n";
    expect(planTables(text)).toEqual([]);
  });

  it("does not read a table inside the leading frontmatter", () => {
    const text = "---\n| a |\n| --- |\n| 1 |\n---\n";
    expect(planTables(text)).toEqual([]);
  });

  it("keeps offsets stable for CRLF input and for a table at end of file", () => {
    const text = "| a |\r\n| --- |\r\n| 1 |";
    const table = only(text);
    expect(text.slice(table.from, table.to)).toBe("| a |\r\n| --- |\r\n| 1 |");
    expect(cellTexts(text, table)).toEqual([
      ["a"],
      ["1"],
    ]);
  });

  it("finds several tables in document order", () => {
    const text = "| a |\n| --- |\n| 1 |\n\npara\n\n| b |\n| --- |\n| 2 |\n";
    const tables = planTables(text);
    expect(tables).toHaveLength(2);
    expect(tables[0]?.from).toBeLessThan(tables[1]?.from ?? 0);
    expect(tables[0]?.lastLine).toBeLessThan(tables[1]?.firstLine ?? 0);
  });
});

describe("splitCells", () => {
  it("treats a line without pipes as one cell", () => {
    const text = "hello\n";
    const line = splitLines(text)[0];
    if (line === undefined) throw new Error("missing line");
    expect(splitCells(text, line)).toEqual([{ from: 0, to: 5 }]);
  });

  it("does not create cells for the outer pipes", () => {
    const text = "| a | b |\n";
    const line = splitLines(text)[0];
    if (line === undefined) throw new Error("missing line");
    expect(splitCells(text, line).map(cell => text.slice(cell.from, cell.to))).toEqual(["a", "b"]);
  });
});

describe("tableIntersects", () => {
  const text = "| a |\n| --- |\n| 1 |\n";
  const table = only(text);

  it("is active for a cursor on the header, a body row, or a spanning selection", () => {
    expect(tableIntersects(table, { from: 0, to: 0 })).toBe(true);
    expect(tableIntersects(table, { from: 12, to: 12 })).toBe(true);
    expect(tableIntersects(table, { from: 0, to: text.length - 1 })).toBe(true);
  });

  it("is inactive for a cursor outside the table or no selection at all", () => {
    expect(tableIntersects(table, { from: text.length, to: text.length })).toBe(false);
    expect(tableIntersects(table, null)).toBe(false);
  });
});

// @vitest-environment jsdom
/**
 * The editable body as the text renderer mounts it.
 *
 * The Markdown path is covered by `body.test.ts`, which pins its exact
 * behaviour including the two mode-specific test ids. This file covers what the
 * second renderer adds: the same draft lifecycle over a non-Markdown path, the
 * decoration layer switched off, and the read-only degradation when the
 * deployment has no write channel.
 */
import { act, createElement } from "react";
import { createRoot, type Root } from "react-dom/client";
import { afterEach, beforeEach, describe, expect, it } from "vitest";

import { TextEditorBody, configureBody, isEditable } from "../src/client/body.tsx";
import { boot } from "../src/client/chunk-loader.ts";
import type {
  DocumentSessionFace,
  DocumentSnapshotFace,
  DocumentStoreFace,
  EditorBodyProps,
  RendererBodyProps,
} from "../src/client/contracts.ts";
import { translatorFor } from "../src/client/copy.ts";

(globalThis as { IS_REACT_ACT_ENVIRONMENT?: boolean }).IS_REACT_ACT_ENVIRONMENT = true;

/** Records the presentation flags the body handed the editor chunk. */
const seen: EditorBodyProps[] = [];

function FakeEditor(props: EditorBodyProps) {
  seen.push(props);
  return createElement(
    "div",
    { "data-testid": "fake-editor", "data-decorate": String(props.decorate) },
    createElement("span", { "data-testid": "fake-text" }, props.text),
    createElement(
      "button",
      { type: "button", "data-testid": "fake-type", onClick: () => props.onChange(`${props.text}!`) },
      "type",
    ),
    createElement("button", { type: "button", "data-testid": "fake-save", onClick: () => props.onSave?.() }, "save"),
  );
}

boot(
  Object.assign(() => {
    throw new Error("the test require only exposes async()");
  }, {
    async: async () => ({ renderer: "codemirror", EditorBody: FakeEditor }),
  }),
);

interface FakeSession extends DocumentSessionFace {
  reloads: number;
  saves: number;
}

/**
 * A store whose sessions answer one fixed document.
 * @param options - `writable: false` models an explorer half without the write channel.
 * @returns the store plus the sessions it handed out.
 */
function createStore(options: { readonly writable?: boolean } = {}): {
  store: DocumentStoreFace;
  sessions: FakeSession[];
  acquires: string[];
} {
  const sessions: FakeSession[] = [];
  const acquires: string[] = [];
  const writable = options.writable !== false;

  const store: DocumentStoreFace = {
    acquire(_sessionId, path) {
      acquires.push(path);
      let snapshot: DocumentSnapshotFace = {
        status: "idle",
        text: "",
        savedText: "",
        version: null,
        dirty: false,
        // Absent is how an older explorer half reports "no write channel".
        ...(writable ? { saving: false } : {}),
        conflict: false,
        error: null,
      };
      const listeners = new Set<() => void>();
      const publish = (): void => {
        for (const listener of [...listeners]) listener();
      };
      const session: FakeSession = {
        reloads: 0,
        saves: 0,
        getSnapshot: () => snapshot,
        subscribe(listener) {
          listeners.add(listener);
          return () => listeners.delete(listener);
        },
        setDraft(text) {
          snapshot = { ...snapshot, text, dirty: text !== snapshot.savedText };
          publish();
        },
        async save() {
          session.saves += 1;
          return { ok: true as const, version: snapshot.version };
        },
        async reload() {
          session.reloads += 1;
          snapshot = { ...snapshot, status: "loading" };
          publish();
          snapshot = {
            status: "ready",
            text: `// ${path}`,
            savedText: `// ${path}`,
            version: "v1",
            dirty: false,
            ...(writable ? { saving: false } : {}),
            conflict: false,
            error: null,
          };
          publish();
        },
        dispose() {},
      };
      sessions.push(session);
      return session;
    },
  };

  return { store, sessions, acquires };
}

function props(overrides: Partial<RendererBodyProps> = {}): RendererBodyProps {
  return {
    path: "src/main.ts",
    sessionId: "session-1",
    mode: "source",
    t: translatorFor("zh"),
    ...overrides,
  };
}

describe("TextEditorBody", () => {
  let host: HTMLDivElement;
  let root: Root;

  beforeEach(() => {
    seen.length = 0;
    host = document.createElement("div");
    document.body.append(host);
    root = createRoot(host);
  });

  afterEach(async () => {
    await act(async () => {
      root.unmount();
    });
    host.remove();
  });

  async function show(
    overrides: Partial<RendererBodyProps> = {},
    store: DocumentStoreFace = createStore().store,
    locale: string = "zh",
  ): Promise<void> {
    configureBody({ documents: () => store, t: translatorFor(locale) });
    await act(async () => {
      root.render(createElement(TextEditorBody, props(overrides)));
    });
    await act(async () => {
      await Promise.resolve();
      await Promise.resolve();
    });
  }

  function testId(id: string): HTMLElement | null {
    return host.querySelector<HTMLElement>(`[data-testid="${id}"]`);
  }

  it("mounts an editor over a non-Markdown text file", async () => {
    const { store, acquires } = createStore();
    await show({}, store);

    expect(acquires).toEqual(["src/main.ts"]);
    expect(testId("fs-text-editor")).not.toBeNull();
    expect(testId("fake-text")?.textContent).toBe("// src/main.ts");
  });

  it("switches the decoration layer off", async () => {
    // The planner behind that layer understands Markdown only; running it over
    // TypeScript would hide characters it mistook for markers.
    const { store } = createStore();
    await show({}, store);

    expect(seen.at(-1)?.decorate).toBe(false);
  });

  it("keeps the mono editor surface whatever mode the pane reports", async () => {
    // The pane defaults to `reading` and only offers the toggle for Markdown, so
    // a code file must not inherit the prose typography from that default.
    const { store } = createStore();
    await show({ mode: "reading" }, store);

    expect(testId("fs-text-editor")?.className).toBe("fmd-source-editor");
  });

  it("pushes an edit into the shared draft and saves through the same session", async () => {
    const { store, sessions } = createStore();
    await show({}, store);

    await act(async () => {
      testId("fake-type")?.dispatchEvent(new MouseEvent("click", { bubbles: true }));
    });
    expect(sessions[0]?.getSnapshot().dirty).toBe(true);

    await act(async () => {
      testId("fake-save")?.dispatchEvent(new MouseEvent("click", { bubbles: true }));
    });
    expect(sessions[0]?.saves).toBe(1);
  });

  it("does not read while the panel is hidden", async () => {
    const { store, sessions } = createStore();
    await show({ visible: false }, store);

    expect(sessions[0]?.reloads).toBe(0);
    expect(testId("fs-text-editor")).toBeNull();
  });

  it("degrades to a read-only view when the deployment has no write channel", async () => {
    // An editor here would accept keystrokes and drop them, which is worse than
    // saying plainly that the file cannot be saved.
    const { store } = createStore({ writable: false });
    await show({}, store);

    expect(testId("fs-md-readonly")).not.toBeNull();
    expect(testId("fs-md-readonly-note")?.textContent).toContain("只读");
    expect(testId("fs-text-source")?.textContent).toBe("// src/main.ts");
    expect(testId("fake-editor")).toBeNull();
  });

  it("translates the read-only note instead of hard-coding one language", async () => {
    // The rest of this body routes every message through `t`, so a literal here
    // would show Chinese to an English reader. Asserting only the Chinese text
    // cannot catch that: it passes whether the string is translated or typed in.
    const { store } = createStore({ writable: false });
    await show({}, store, "en");

    const note = testId("fs-md-readonly-note")?.textContent ?? "";
    expect(note).not.toBe("");
    expect(note).not.toMatch(/[\u4e00-\u9fff]/u);
    expect(note.toLowerCase()).toContain("read-only");
  });

  it("keeps the read failure path for a file the channel refused", async () => {
    configureBody({ documents: () => undefined, t: translatorFor("zh") });
    await act(async () => {
      root.render(createElement(TextEditorBody, props()));
    });

    expect(testId("fs-md-unavailable")).not.toBeNull();
  });
});

describe("isEditable", () => {
  const base: DocumentSnapshotFace = {
    status: "ready",
    text: "x",
    savedText: "x",
    version: "v1",
    dirty: false,
    saving: false,
    error: null,
  };

  it("accepts a ready snapshot from a channel that can write", () => {
    expect(isEditable(base)).toBe(true);
  });

  it("refuses a ready snapshot from a channel with no write member", () => {
    const { saving: _saving, ...withoutSaving } = base;
