      author: "Alice",
      time: 1700000000,
      subject: "merge branch 'x'",
    });
    expect(commits[1]?.parents).toEqual([]);
    expect(commits[1]?.subject).toBe("subject with | pipe");
    expect(commits[2]?.subject).toBe("root");
