import { execFileSync } from "node:child_process";
import { existsSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

import { describe, expect, it } from "vitest";

import type { GitRunner, GitRunResult } from "../src/host/git.ts";
import { collectCommit } from "../src/host/detail.ts";
import { collectQuery } from "../src/host/query.ts";
import { collectShow } from "../src/host/show.ts";
import { collectSnapshot } from "../src/host/snapshot.ts";

const repoRoot = resolve(dirname(fileURLToPath(import.meta.url)), "../../..");
const hasGit = existsSync(resolve(repoRoot, ".git"));

/**
 * Local runner for the smoke test only: it mirrors the host subprocess contract
 * with `execFileSync`, so the parsers meet the same bytes a real repository
 * produces without booting the Harness.
 */
const localRunner: GitRunner = {
  async run(args): Promise<GitRunResult> {
    const argv = ["git", ...args];
    try {
      const stdout = execFileSync("git", args, { cwd: repoRoot, encoding: "utf8", maxBuffer: 64 * 1024 * 1024 });
      return { argv, exitCode: 0, stdout, stderr: "", timedOut: false, cancelled: false, stdoutLossy: false };
    } catch (error) {
      const failed = error as { status?: number; stderr?: string };
      return {
        argv,
        exitCode: failed.status ?? 1,
        stdout: "",
        stderr: failed.stderr ?? String(error),
        timedOut: false,
        cancelled: false,
        stdoutLossy: false,
      };
    }
  },
};

describe.runIf(hasGit)("real repository smoke", () => {
  it("snapshots this checkout with edges that match the parents", async () => {
    const result = await collectSnapshot({ runner: localRunner, cwd: repoRoot, maxCommits: 150 });
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    const { snapshot } = result;
    expect(snapshot.isRepository).toBe(true);
    expect(snapshot.commits.length).toBeGreaterThan(0);
    expect(snapshot.lanes).toHaveLength(snapshot.commits.length);
    const parents = new Map(snapshot.commits.map(commit => [commit.hash, commit.parents]));
    for (const row of snapshot.lanes) {
      expect(row.edges).toHaveLength(parents.get(row.hash)?.length ?? 0);
      for (const edge of row.edges) expect(parents.get(edge.from)).toContain(edge.to);
    }
  });

  it("carries the raw status and per-path line counts for the view", async () => {
    const result = await collectSnapshot({ runner: localRunner, cwd: repoRoot, maxCommits: 10 });
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(result.snapshot.status).toContain("# branch.oid ");
    const changed = new Set(result.snapshot.changes.map(change => change.path));
    for (const stat of result.snapshot.stats) expect(changed.has(stat.path)).toBe(true);
  });

  it("reads the HEAD commit detail against its first parent", async () => {
    const head = execFileSync("git", ["rev-parse", "HEAD"], { cwd: repoRoot, encoding: "utf8" }).trim();
    const subject = execFileSync("git", ["log", "-1", "--pretty=format:%s", head], { cwd: repoRoot, encoding: "utf8" });
    const changed = execFileSync("git", ["diff-tree", "--no-commit-id", "--name-only", "-r", "--root", "-m", "--first-parent", head], {
      cwd: repoRoot,
      encoding: "utf8",
    })
      .split("\n")
      .filter(Boolean);
    const result = await collectCommit({ runner: localRunner, cwd: repoRoot }, { hash: head });
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(result.detail.subject).toBe(subject);
    expect(result.detail.files.map(file => file.path)).toEqual(changed);
  });

  it("reads the HEAD package.json first screen byte-for-byte from the commit", async () => {
    const head = execFileSync("git", ["rev-parse", "HEAD"], { cwd: repoRoot, encoding: "utf8" }).trim();
    const expected = execFileSync("git", ["cat-file", "-p", `${head}:package.json`], { cwd: repoRoot, encoding: "utf8" });
    const expectedLines = (expected.endsWith("\n") ? expected.slice(0, -1) : expected).split("\n");
    const firstScreen = expectedLines.slice(0, 40);

    const result = await collectShow(
      { runner: localRunner, cwd: repoRoot, maxBytes: 4 * 1024 * 1024 },
      { hash: head, path: "package.json", offset: 1, limit: 40 },
    );
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(result.page.source).toBe("commit");
    expect(result.page.revision).toBe(
      execFileSync("git", ["rev-parse", `${head}:package.json`], { cwd: repoRoot, encoding: "utf8" }).trim(),
    );
    expect(result.page.text.split("\n")[0]).toBe(firstScreen[0]);
    expect(result.page.text).toBe(firstScreen.join("\n"));
    expect(result.page.lines).toBe(firstScreen.length);
    expect(result.page.eof).toBe(firstScreen.length === expectedLines.length);
  });

  it("pages history and reports hasMore from a limit-plus-one fetch", async () => {
    const result = await collectQuery({ runner: localRunner, cwd: repoRoot, defaultLimit: 200 }, { limit: 5 });
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(result.page.commits).toHaveLength(5);
    expect(result.page.lanes).toHaveLength(5);
  });

  it("searches commit messages against the messages git itself reports", async () => {
    // The panel's search is a repository-wide grep, so the assertion is against
    // git's own answer for the same pattern rather than against a fixture: this
    // is the one place the literal-match flag meets real commit messages.
    const wanted = "fix";
    // Same traversal flags the host builds: a different order would make this a
    // test of git's defaults rather than of the search.
    const expected = execFileSync(
      "git",
      ["log", "--topo-order", "-F", `--grep=${wanted}`, "--pretty=format:%H", "-n", "20", "--all"],
      { cwd: repoRoot, encoding: "utf8" },
    )
      .split("\n")
      .filter(Boolean);
    const result = await collectQuery({ runner: localRunner, cwd: repoRoot, defaultLimit: 200 }, { search: wanted, limit: 20 });
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(result.page.commits.map(commit => commit.hash)).toEqual(expected);
  });
});

