/**
 * `/mcp-timeout` spec: one command that resolves a target, validates a value,
 * and writes the shadow namespace — plus the one action that writes the mcp
 * row directly (reset), because a removal is a decision, not a sync.
 *
 * The contract under test: targets resolve by entry id or unique serverName;
 * unknown or ambiguous targets answer with the candidate list; a set writes the
 * merged shadow map through the settings service (never the mcp row); reset
 * strips the row's override AND the shadow key; values below the floor are
 * refused with the floor named.
 */
import { describe, expect, it } from "vitest";
import { createMcpTimeoutCommand, MIN_TIMEOUT_MS, type McpTimeoutDeps, type SettingsServiceLike } from "../src/command.ts";
import type { ConfigEditorLike, McpEntryLike } from "../src/inventory.ts";

function makeDeps(rows: Array<{ id: string; serverName?: string; override?: Record<string, unknown>; inherited?: Record<string, unknown> }>) {
  const entryOf = new Map(rows.map(row => [row.id, { options: { id: row.id, name: "@deepseek-ai/dsh-mcp-client" } } as McpEntryLike]));
  const edits: Array<{ id: string; change: (current: Record<string, unknown>) => Record<string, unknown> }> = [];
  const updates: Array<{ ns: string; patch: Record<string, unknown> }> = [];
  let shadow: Record<string, number> = {};
  const settings: SettingsServiceLike = {
    describe: () => [{ ns: "more-config", value: { mcpTimeouts: Object.entries(shadow).map(([id, timeoutMs]) => ({ id, timeoutMs })) } }],
    update: async (ns, patch) => {
      updates.push({ ns, patch: patch as Record<string, unknown> });
      shadow = Object.fromEntries((patch as { mcpTimeouts: Array<{ id: string; timeoutMs: number }> }).mcpTimeouts.map(entry => [entry.id, entry.timeoutMs]));
    },
  };
  const configEditor: ConfigEditorLike & McpTimeoutDeps["configEditor"] = {
    entries: () => [...entryOf.values()],
    configuration: () =>
      rows.map(row => ({
        entry: entryOf.get(row.id)!,
        inherited: { serverName: row.serverName, ...(row.inherited ?? {}) },
        override: row.override ?? {},
      })),
    edit: async (entry, change) => {
      const row = rows.find(candidate => candidate.id === entry.options.id)!;
      edits.push({ id: entry.options.id, change: change as (current: Record<string, unknown>) => Record<string, unknown> });
      row.override = change({ ...(row.override ?? {}) }, row.inherited ?? {});
    },
  };
  return { deps: { ns: "more-config", settings, configEditor } as McpTimeoutDeps, updates, edits, entryOf };
}

function run(deps: McpTimeoutDeps, rawInput: string) {
  return createMcpTimeoutCommand(deps).handler({ agent: {}, rawInput });
}

describe("/mcp-timeout", () => {
  it("refuses usage errors with the argument shape", async () => {
    const { deps } = makeDeps([{ id: "mcp-kimi-tools", serverName: "kimi" }]);
    for (const input of ["", "kimi", "kimi abc"]) {
      const result = await run(deps, input);
      expect(result.kind).toBe("error");
      expect(result.text).toContain("mcp-timeout");
    }
  });

  it("resolves the target by entry id or unique serverName", async () => {
    const { deps, updates, edits } = makeDeps([{ id: "mcp-kimi-tools", serverName: "kimi" }]);
    await run(deps, "kimi 660000");
    // A set writes the shadow only; the mcp row stays the reconciler's.
    expect(edits).toHaveLength(0);
    expect(updates).toHaveLength(1);
    expect(updates).toEqual([{ ns: "more-config", patch: { mcpTimeouts: [{ id: "mcp-kimi-tools", timeoutMs: 660000 }] } }]);

    await run(deps, "mcp-kimi-tools 360000");
    expect(updates[1]).toEqual({ ns: "more-config", patch: { mcpTimeouts: [{ id: "mcp-kimi-tools", timeoutMs: 360000 }] } });
  });

  it("merges into the existing shadow map instead of replacing it", async () => {
    const { deps, updates } = makeDeps([
      { id: "mcp-kimi-tools", serverName: "kimi" },
      { id: "mcp-web", serverName: "websearch" },
    ]);
    await run(deps, "kimi 660000");
    await run(deps, "websearch 120000");
    const second = updates[1];
    if (second === undefined) throw new Error("second update missing");
    expect(second).toEqual({ ns: "more-config", patch: { mcpTimeouts: [{ id: "mcp-kimi-tools", timeoutMs: 660000 }, { id: "mcp-web", timeoutMs: 120000 }] } });
  });

  it("answers an unknown target with the candidate list and current values", async () => {
    const { deps } = makeDeps([{ id: "mcp-kimi-tools", serverName: "kimi", override: { toolCallTimeoutMs: 660000 } }]);
    const result = await run(deps, "ghost 60000");
    expect(result.kind).toBe("error");
    expect(result.text).toContain("mcp-kimi-tools");
    expect(result.text).toContain("kimi");
    expect(result.text).toContain("660000");
  });

  it("refuses ambiguous serverName matches", async () => {
    const { deps } = makeDeps([
      { id: "mcp-a", serverName: "dup" },
      { id: "mcp-b", serverName: "dup" },
    ]);
    const result = await run(deps, "dup 60000");
    expect(result.kind).toBe("error");
    expect(result.text).toContain("mcp-a");
    expect(result.text).toContain("mcp-b");
  });

  it("refuses values below the floor, naming the floor", async () => {
    const { deps } = makeDeps([{ id: "mcp-kimi-tools", serverName: "kimi" }]);
    for (const value of ["0", "500", "60"]) {
      const result = await run(deps, `kimi ${value}`);
      expect(result.kind).toBe("error");
      expect(result.text).toContain(String(MIN_TIMEOUT_MS));
    }
  });

  it("reports already-current values without writing", async () => {
    const { deps, updates } = makeDeps([{ id: "mcp-kimi-tools", serverName: "kimi" }]);
    await run(deps, "kimi 660000");
    const second = await run(deps, "kimi 660000");
    expect(second.kind).toBe("success");
    expect(updates).toHaveLength(1);
  });

  it("resets the shadow key before the row override", async () => {
    const order: string[] = [];
    const base = makeDeps([{ id: "mcp-kimi-tools", serverName: "kimi", override: { toolCallTimeoutMs: 660000 } }]);
    const deps = {
      ns: base.deps.ns,
      settings: { ...base.deps.settings, update: async (...args: Parameters<typeof base.deps.settings.update>) => { order.push("update"); return base.deps.settings.update(...args); } },
      configEditor: { ...base.deps.configEditor, edit: async (...args: Parameters<typeof base.deps.configEditor.edit>) => { order.push("edit"); return base.deps.configEditor.edit(...args); } },
    } as typeof base.deps;
    const result = await run(deps, "kimi default");
    expect(result.kind).toBe("success");
    expect(order).toEqual(["update", "edit"]);
  });

  it("a failed row edit after the shadow removal answers with the half-done state", async () => {
    const base = makeDeps([{ id: "mcp-kimi-tools", serverName: "kimi", override: { toolCallTimeoutMs: 660000 } }]);
    const deps = {
      ...base.deps,
      configEditor: { ...base.deps.configEditor, edit: async () => { throw new Error("overridden by home patch"); } },
    } as typeof base.deps;
    const result = await run(deps, "kimi default");
    expect(result.kind).toBe("error");
    expect(result.text).toContain("shadow");
    expect(result.text).toContain("overridden by home patch");
    expect(base.updates).toHaveLength(1);
    expect(base.updates[0]?.patch).toEqual({ mcpTimeouts: [] });
  });

  it("reset removes the row override and the shadow key", async () => {
    const { deps, updates, edits } = makeDeps([{ id: "mcp-kimi-tools", serverName: "kimi", override: { toolCallTimeoutMs: 660000 } }]);
    const result = await run(deps, "kimi default");
    expect(result.kind).toBe("success");
    expect(edits).toHaveLength(1);
    const [edit] = edits;
    if (edit === undefined) throw new Error("edit missing");
    expect(edit.id).toBe("mcp-kimi-tools");
    expect(edit.change({ toolCallTimeoutMs: 660000, command: "node" })).toEqual({ command: "node" });
    expect(updates).toHaveLength(1);
    expect(updates).toEqual([{ ns: "more-config", patch: { mcpTimeouts: [] } }]);
  });
});

/**
 * `readMcpInventory` spec: project the profile's mcp-client rows into the flat
 * view the command, the reconciler and later the panel all read.
 *
 * The contract under test: only rows whose package is the mcp client appear;
 * each row's serverName and timeout come from the override layer first, then
 * the inherited layer, then the client's own 60s default; the entry handle is
 * passed through untouched for a later `configEditor.edit`.
 */
import { describe, expect, it } from "vitest";
import { DEFAULT_TOOL_CALL_TIMEOUT_MS, readMcpInventory, type ConfigEditorLike } from "../src/inventory.ts";

function editorWith(rows: Array<{ id: string; name: string; inherited?: Record<string, unknown>; override?: Record<string, unknown> }>): ConfigEditorLike {
  const entryOf = new Map(rows.map(row => [row.id, { options: { id: row.id, name: row.name } }]));
  return {
    entries: () => [...entryOf.values()],
    configuration: () =>
      rows
        .filter(row => entryOf.has(row.id))
        .map(row => ({ entry: entryOf.get(row.id)!, inherited: row.inherited ?? {}, override: row.override ?? {} })),
  };
}

const KIMI = { id: "mcp-kimi-tools", name: "@deepseek-ai/dsh-mcp-client" };

describe("readMcpInventory", () => {
  it("lists only mcp-client rows", () => {
    const editor = editorWith([
      KIMI,
      { id: "ui-chat", name: "@deepseek-ai/dsh-client-ui-chat" },
    ]);
    const rows = readMcpInventory(editor);
    expect(rows.map(row => row.id)).toEqual(["mcp-kimi-tools"]);
  });

  it("resolves serverName and timeout from the override layer first", () => {
    const editor = editorWith([{
      ...KIMI,
      inherited: { serverName: "kimi", toolCallTimeoutMs: 60000 },
      override: { serverName: "kimi2", toolCallTimeoutMs: 660000 },
    }]);
    const [first] = readMcpInventory(editor);
    if (first === undefined) throw new Error("inventory row missing");
    expect(first.serverName).toBe("kimi2");
    expect(first.effectiveTimeoutMs).toBe(660000);
    expect(first.overrideTimeoutMs).toBe(660000);
  });

  it("falls back to the inherited layer, then the 60s default", () => {
    const inheritedOnly = editorWith([{ ...KIMI, inherited: { serverName: "kimi", toolCallTimeoutMs: 120000 } }]);
    const [inheritedRow] = readMcpInventory(inheritedOnly);
    if (inheritedRow === undefined) throw new Error("inventory row missing");
    expect(inheritedRow.effectiveTimeoutMs).toBe(120000);

    const bare = editorWith([{ ...KIMI, inherited: { serverName: "kimi" } }]);
    const [bareRow] = readMcpInventory(bare);
    if (bareRow === undefined) throw new Error("inventory row missing");
    expect(bareRow.effectiveTimeoutMs).toBe(DEFAULT_TOOL_CALL_TIMEOUT_MS);
    expect(bareRow.overrideTimeoutMs).toBeUndefined();
  });

  it("carries the entry handle through for configEditor.edit", () => {
    const editor = editorWith([KIMI]);
    const [row] = readMcpInventory(editor);
    if (row === undefined) throw new Error("inventory row missing");
    expect(row.entry).toBe(editor.entries()[0]);
  });
});

/**
 * `planSync` spec: the reconciler's whole decision procedure as a pure
 * function of the shadow map and the live inventory.
 *
 * The contract under test: a shadow row becomes a set only when the effective
 * timeout differs (idempotence when equal, including the inherited-default
 * case); rows the user overrode by hand without a shadow key are reported,
 * never written; shadow keys without a matching row are reported as unknown so
 * callers can surface an actionable error.
 */
import { describe, expect, it } from "vitest";
import { planSync } from "../src/plan.ts";
import type { McpInventoryRow } from "../src/inventory.ts";

function row(overrides: Partial<McpInventoryRow> & { id: string }): McpInventoryRow {
  return {
    serverName: overrides.id,
    effectiveTimeoutMs: 60000,
    entry: { options: { id: overrides.id } },
    ...overrides,
  } as McpInventoryRow;
}

describe("planSync", () => {
  it("sets the override when the effective timeout differs", () => {
    const plan = planSync({ "mcp-kimi-tools": 660000 }, [row({ id: "mcp-kimi-tools", effectiveTimeoutMs: 60000 })]);
    expect(plan.sets).toEqual([{ id: "mcp-kimi-tools", timeoutMs: 660000 }]);
    expect(plan.unknownKeys).toEqual([]);
  });

  it("skips writes when the effective timeout already equals the target", () => {
    const viaOverride = planSync({ "mcp-kimi-tools": 660000 }, [row({ id: "mcp-kimi-tools", effectiveTimeoutMs: 660000, overrideTimeoutMs: 660000 })]);
    expect(viaOverride.sets).toEqual([]);

    // Effective from the inherited default, target equal: no override row is
    // created, keeping the patch free of no-op config.
    const viaDefault = planSync({ "mcp-kimi-tools": 60000 }, [row({ id: "mcp-kimi-tools", effectiveTimeoutMs: 60000 })]);
    expect(viaDefault.sets).toEqual([]);
  });

  it("reports overridden rows that no shadow key owns, without writing them", () => {
    const plan = planSync({}, [row({ id: "mcp-kimi-tools", effectiveTimeoutMs: 660000, overrideTimeoutMs: 660000 })]);
    expect(plan.sets).toEqual([]);
    expect(plan.unmanaged).toEqual([{ id: "mcp-kimi-tools", timeoutMs: 660000 }]);
  });

  it("a shadow key whose value differs from its own override still plans a set", () => {
    const plan = planSync({ "mcp-kimi-tools": 360000 }, [row({ id: "mcp-kimi-tools", effectiveTimeoutMs: 660000, overrideTimeoutMs: 660000 })]);
    expect(plan.sets).toEqual([{ id: "mcp-kimi-tools", timeoutMs: 360000 }]);
    expect(plan.unmanaged).toEqual([]);
  });

  it("collects shadow keys that match no row as unknown, in stable order", () => {
    const plan = planSync({ "ghost-a": 5000, "mcp-kimi-tools": 660000 }, [row({ id: "mcp-kimi-tools" })]);
    expect(plan.unknownKeys).toEqual(["ghost-a"]);
    expect(plan.sets).toEqual([{ id: "mcp-kimi-tools", timeoutMs: 660000 }]);
  });
});

