  it("switches to the file tab and shows one row per changed file", async () => {
    const { runtime } = fakeRuntime({
      compare: () =>
        ({
          ok: true,
          compare: snapshot({
            files: {
              files: [
                file({ path: "toast-example.tsx", additions: 86, deletions: 0 }),
                file({ path: "add.ts", additions: 82, deletions: 26 }),
