        if (call === 2) return slowFirst.promise;
        return {
          ok: true,
          compare: snapshot({
            files: {
              files: [file({ path: call === 1 ? "first.ts" : "newest.ts" })],
              summary: { files: 1, additions: 1, deletions: 0 },
            },
