/**
 * Parse-level tests for the mesh containers this viewport reads.
 *
 * These drive the real loaders against real bytes, which is where a format
 * regression actually shows up: the viewport around them is identical for all
 * five suffixes, so the per-format risk is entirely in parsing.
 */
import { describe, expect, it } from "vitest";
import { DRACOLoader } from "three/addons/loaders/DRACOLoader.js";

import { loaderFor, meshKindOf, releasePartialViewport } from "../src/scene3d.ts";

/** The smallest Draco seam these tests need; nothing here decodes Draco. */
const draco = new DRACOLoader();

/** Encode ASCII text as the bytes a file read would return. */
function bytesOf(text: string): ArrayBuffer {
  const encoded = new TextEncoder().encode(text);
  return encoded.buffer.slice(encoded.byteOffset, encoded.byteOffset + encoded.byteLength) as ArrayBuffer;
}

/** One quad, in the OBJ dialect Blender and most exporters emit. */
const OBJ_QUAD = [
  "# test quad",
  "v 0 0 0",
  "v 1 0 0",
  "v 1 1 0",
  "v 0 1 0",
  "f 1 2 3 4",
  "",
].join("\n");

/** One triangle, as ASCII STL. */
const STL_TRIANGLE = [
  "solid test",
  "  facet normal 0 0 1",
  "    outer loop",
    "      vertex 0 0 0",
    "      vertex 1 0 0",
    "      vertex 0 1 0",
    "    endloop",
    "  endfacet",
  "endsolid test",
  "",
].join("\n");

describe("mesh loaders", () => {
  it("reads an OBJ into a group with one mesh", async () => {
    const parsed = await loaderFor("/tmp/quad.obj", draco).load(bytesOf(OBJ_QUAD));
    const group = parsed as { children: unknown[] };
    expect(Array.isArray(group.children)).toBe(true);
    expect(group.children.length).toBe(1);
  });

  it("reads an ASCII STL into a geometry with one triangle", async () => {
    const parsed = await loaderFor("/tmp/triangle.stl", draco).load(bytesOf(STL_TRIANGLE));
    const geometry = parsed as { getAttribute: (name: string) => { count: number } | undefined };
    expect(geometry.getAttribute("position")?.count).toBe(3);
  });

  it("refuses a 3MF it cannot parse instead of resolving empty", async () => {
    // A zip-shaped header with no parts: the loader must reject, because a
    // resolved-but-empty scene would render as a blank viewport.
    const notAZip = bytesOf("not a 3mf archive");
    await expect(loaderFor("/tmp/broken.3mf", draco).load(notAZip)).rejects.toThrow();
  });

  it("rejects a suffix no loader reads", async () => {
    expect(meshKindOf("/tmp/a.png")).toBeNull();
    await expect(loaderFor("/tmp/a.png", draco).load(bytesOf("x"))).rejects.toThrow();
  });

  it("rejects a glTF whose external buffer was not supplied", async () => {
    // A .gltf that names its buffer by URI cannot be parsed without that file.
    // Serving the sibling is proven in a real browser, where blob URLs and fetch
    // exist; stubbing them here would test the stub. What this pins is the
    // failure mode: a rejection, never a silently empty scene that a reader would
    // see as a blank pane.
    const gltf = JSON.stringify({
      asset: { version: "2.0" },
      scenes: [{ nodes: [0] }],
      scene: 0,
      nodes: [{ mesh: 0 }],
      meshes: [{ primitives: [{ attributes: { POSITION: 0 } }] }],
      buffers: [{ uri: "tri.bin", byteLength: 42 }],
      bufferViews: [{ buffer: 0, byteOffset: 0, byteLength: 42 }],
      accessors: [{ bufferView: 0, componentType: 5126, count: 3, type: "VEC3", min: [0, 0, 0], max: [1, 1, 0] }],
    });
    await expect(loaderFor("/tmp/model.gltf", draco).load(bytesOf(gltf))).rejects.toThrow();
  });
});

describe("partial viewport teardown", () => {
  /**
   * Stand-in recorder for the two objects a failed mount already owns.
   * @returns the calls made, in order.
   */
  function parts(): { calls: string[]; value: Parameters<typeof releasePartialViewport>[0] } {
    const calls: string[] = [];
    return {
      calls,
      value: {
        renderer: {
          dispose: () => calls.push("renderer.dispose"),
          forceContextLoss: () => calls.push("forceContextLoss"),
          domElement: { remove: () => calls.push("detach") },
        },
        draco: { dispose: () => calls.push("draco.dispose") },
      },
    };
  }

  it("releases every resource a failed mount already created", () => {
    // A mount that throws after creating its renderer must not leave the context
    // behind. Browsers cap concurrent contexts and drop the oldest, so the
    // symptom is not a leak in this preview but a blank canvas in another one.
    const { calls, value } = parts();
    releasePartialViewport(value);
    expect(calls).toEqual(["draco.dispose", "renderer.dispose", "forceContextLoss", "detach"]);
  });

  it("drops the context before detaching the canvas", () => {
    // Detaching first leaves the context alive with nothing to draw into.
    const { calls, value } = parts();
    releasePartialViewport(value);
    expect(calls.indexOf("forceContextLoss")).toBeLessThan(calls.indexOf("detach"));
  });
});

/**
 * The mount lifecycle shared by every engine surface.
 *
 * These cover the part of a preview that no screenshot shows and that unit tests
 * missed once already: a failed preview has to stay recoverable. The surfaces
 * render the canvas host through a failure, so these rules are what makes the
 * retry button do anything.
 */
import { describe, expect, it } from "vitest";

import { UNREPORTED, canAttempt, failureMessage, prepareAttempt, shouldSettle } from "../src/mount.ts";

describe("mount lifecycle", () => {
  it("refuses to attempt without a container", () => {
    // The failure of a retry is a missing element, not a missing engine. This is
    // the guard that used to run before the container existed on the failure
    // path, which is what made retry a dead button.
    expect(canAttempt(null)).toBe(false);
  });

  it("allows an attempt once the container exists", () => {
    const container = { tagName: "DIV" } as unknown as HTMLElement;
    expect(canAttempt(container)).toBe(true);
  });

  it("clears the element before a retry so two viewports do not stack", () => {
    // A retry re-enters the same effect on the same element, and the previous
    // failed attempt may already have appended a canvas.
    let cleared = 0;
    const container = { tagName: "DIV" } as unknown as HTMLElement;
    prepareAttempt({ container, clear: () => (cleared += 1) });
    expect(cleared).toBe(1);
  });

  it("surfaces an Error's own message", () => {
    expect(failureMessage(new Error("WebGL context lost"))).toBe("WebGL context lost");
  });

  it("surfaces a thrown string, which is what loaders give", () => {
    // three's loaders reject with bare strings in several paths, and rendering
    // that through String() is the only way the panel shows anything useful.
    expect(failureMessage("Failed to load buffer")).toBe("Failed to load buffer");
  });

  it("names the failure when the value carries no message", () => {
    // A DOMException has a message, but a rejected object or an empty string does
    // not. An empty detail line reads like the preview silently broke.
    expect(failureMessage(undefined)).toBe("the preview failed without a message");
    expect(failureMessage(null)).toBe("the preview failed without a message");
    expect(failureMessage("")).toBe("the preview failed without a message");
    expect(failureMessage({ code: 1 })).toBe("the preview failed without a message");
  });

  it("reports each attempt once and every retry again", () => {
    // The host keys its displayed version on the revision it handed out and only
    // advances that bookkeeping after a successful report, so a retry within the
    // same revision must report. Guarding on the revision alone swallowed it and
    // left the host with no version for a preview that was on screen.
    const fresh = UNREPORTED;
    expect(shouldSettle(fresh, 7, 0)).toBe(true);

    const afterFirstFailure = { revision: 7, attempt: 0 };
    expect(shouldSettle(afterFirstFailure, 7, 0)).toBe(false);
    expect(shouldSettle(afterFirstFailure, 7, 1)).toBe(true);
    expect(shouldSettle(afterFirstFailure, 8, 0)).toBe(true);
  });

  it("does not report the same retry twice", () => {
    // A surface that settles both on load and on error must not double-report:
    // the second report would land after the host already recorded the first.
    const settled = { revision: 3, attempt: 2 };
    expect(shouldSettle(settled, 3, 2)).toBe(false);
    expect(shouldSettle(settled, 3, 3)).toBe(true);
  });
});

