/**
 * The client wiring that turns the pure row builder into a command contribution.
 *
 * The wiring owns what the pure part cannot: reading the live catalogs, pairing
 * the archive set with the session list, opening the popup on the project scope,
 * and re-opening it onto the wider scope when a scope row is picked. Everything
 * asserted here is about that seam between the harness services and the pure
 * functions in `resume.ts`.
 */
import { describe, expect, it, vi } from "vitest";

import { createResumeContribution, type ResumeWiringContext } from "../src/client/resume-command.ts";

/** A context whose catalogs, popup and navigator are inspectable. */
function context(options: {
  ids?: string[];
  byId?: Record<string, { displayTitle?: string; running?: boolean; blank?: boolean; cwd?: string; origin?: "subagent" }>;
  archived?: string[];
  withPopup?: boolean;
  search?: string;
}) {
  const ids = options.ids ?? [];
  const byId = options.byId ?? {};
  const archived = options.archived ?? [];
  const openSession = vi.fn();
  const open = vi.fn();
  const scoped = vi.fn();
  const setSearch = vi.fn();
  const search = options.search ?? "";
  const reachable = options.withPopup !== false;
  const ctx: ResumeWiringContext = {
    commandUi: {
      register: () => () => {},
      ...(reachable
        ? {
            popupFor: () => ({
              open,
              setSearch,
              state: { getSnapshot: () => ({ open: true, search }) },
            }),
          }
        : {}),
    },
    sessions: {
      list: { getSnapshot: () => ({ ids, byId }) },
      scope: id => {
        scoped(id);
        return reachable ? { id } : undefined;
      },
    },
    workspaces: { list: { getSnapshot: () => ({ archivedSessionIds: archived }) } },
    uiWorkspace: { openSession },
  };
  return { ctx, openSession, open, scoped, setSearch };
}

/** The rows one open of the popup would show. */
async function rows(ctx: ResumeWiringContext, sessionId: string) {
  return createResumeContribution(ctx).ui.options({ sessionId }, new AbortController().signal);
}

describe("the /resume contribution", () => {
  it("registers under the bare name the slash menu keys on", () => {
    expect(createResumeContribution(context({}).ctx).name).toBe("resume");
  });

  it("offers a popupSelect, because choosing a session is choosing one row from a set", () => {
    expect(createResumeContribution(context({}).ctx).ui.kind).toBe("popupSelect");
  });

  it("is always available: every session, including a blank one, has somewhere to switch to", () => {
    expect(createResumeContribution(context({}).ctx).available({ sessionId: "s1" })).toBe(true);
  });

  it("reads the catalog at open time, not at registration time", async () => {
    // The catalog is live: sessions finish, get created and disappear while the
    // plugin is registered. Capturing rows at registration would show a stale list.
    const { ctx } = context({ ids: [], byId: {} });
    const contribution = createResumeContribution(ctx);
    const live = { ids: ["s9"], byId: { s9: { displayTitle: "appeared later" } } };
    (ctx.sessions.list as { getSnapshot: () => unknown }).getSnapshot = () => live;

    const options = await contribution.ui.options({ sessionId: "s1" }, new AbortController().signal);

    expect(options.map(option => option.id)).toContain("s9");
  });

  it("opens on the project scope, so the first thing shown is the current work", async () => {
    const { ctx } = context({
      ids: ["s1", "s2"],
      byId: { s1: { displayTitle: "here", cwd: "/work/app" }, s2: { displayTitle: "elsewhere", cwd: "/work/other" } },
    });

    expect((await rows(ctx, "s1")).map(row => row.id)).toEqual(["scope:project", "scope:all", "s1"]);
  });

  it("badges the project scope as the one in use on a fresh open", async () => {
    const { ctx } = context({ ids: ["s1"], byId: { s1: { displayTitle: "only", cwd: "/work/app" } } });

    expect((await rows(ctx, "s1"))[0]?.badge).toBe("当前");
  });

  it("hides archived sessions, matching the sidebar that hides them", async () => {
    const { ctx } = context({
      ids: ["s1", "s2"],
      byId: { s1: { displayTitle: "kept" }, s2: { displayTitle: "archived" } },
      archived: ["s2"],
    });

    expect((await rows(ctx, "s1")).map(row => row.id)).toEqual(["scope:project", "scope:all", "s1"]);
  });

  it("switches through the workspace navigator on a session pick", async () => {
    const { ctx, openSession } = context({ ids: ["s2"], byId: { s2: { displayTitle: "second" } } });

    await createResumeContribution(ctx).ui.onSelect({ id: "s2", label: "second" }, { sessionId: "s1" });

    expect(openSession).toHaveBeenCalledExactlyOnceWith("s2");
  });

  it("treats the invoking session as current, so picking it does not remount the conversation", async () => {
    const { ctx, openSession } = context({ ids: ["s1"], byId: { s1: { displayTitle: "first" } } });

    await createResumeContribution(ctx).ui.onSelect({ id: "s1", label: "first" }, { sessionId: "s1" });

    expect(openSession).not.toHaveBeenCalled();
  });

  it("re-opens the popup onto the wider scope instead of navigating when a scope row is picked", async () => {
    const { ctx, openSession, open } = context({ ids: ["s1"], byId: { s1: { displayTitle: "only" } } });

    await createResumeContribution(ctx).ui.onSelect({ id: "scope:all", label: "全部会话" }, { sessionId: "s1" });

    expect(openSession).not.toHaveBeenCalled();
    expect(open).toHaveBeenCalledTimes(1);
    expect(open.mock.calls[0]?.[0]).toBe("resume");
  });

  it("loads the rows of the scope it re-opens onto", async () => {
    const { ctx, open } = context({
      ids: ["s1", "s2"],
      byId: { s1: { displayTitle: "here", cwd: "/work/app" }, s2: { displayTitle: "elsewhere", cwd: "/work/other" } },
    });
    const contribution = createResumeContribution(ctx);

    await contribution.ui.onSelect({ id: "scope:all", label: "全部会话" }, { sessionId: "s1" });

    const spec = open.mock.calls[0]?.[1] as { options(session: { sessionId: string }, signal: AbortSignal): Promise<Array<{ id: string }>> };
    expect((await spec.options({ sessionId: "s1" }, new AbortController().signal)).map(row => row.id)).toEqual([
      "scope:project",
      "scope:all",
      "s1",
      "s2",
    ]);
  });

  it("does not re-open onto the scope already showing, which would only discard the search", async () => {
    const { ctx, open } = context({ ids: ["s1"], byId: { s1: { displayTitle: "only" } } });

    await createResumeContribution(ctx).ui.onSelect({ id: "scope:project", label: "当前项目" }, { sessionId: "s1" });

    expect(open).not.toHaveBeenCalled();
  });

  it("still navigates when the shell cannot be reached to re-open", async () => {
    // A popup controller is absent only outside a retained session scope; the
    // command must degrade to the plain pick rather than swallow the click.
    const { ctx, openSession } = context({ ids: ["s2"], byId: { s2: { displayTitle: "second" } }, withPopup: false });

    await createResumeContribution(ctx).ui.onSelect({ id: "s2", label: "second" }, { sessionId: "s1" });

    expect(openSession).toHaveBeenCalledExactlyOnceWith("s2");
  });

  it("carries the search text across a scope switch, so the same filter keeps applying", async () => {
    // The re-opened shell is fresh state: without replaying the query the user's
    // filter is silently dropped and they have to type it again to keep looking
    // at the same subset in the other scope.
    const { ctx, setSearch } = context({ ids: ["s1"], byId: { s1: { displayTitle: "only" } }, search: "deploy" });

    await createResumeContribution(ctx).ui.onSelect({ id: "scope:all", label: "全部会话" }, { sessionId: "s1" });

    expect(setSearch).toHaveBeenCalledExactlyOnceWith("deploy");
  });

  it("does not touch the search when there is nothing to carry over", () => {
    const { ctx, setSearch } = context({ ids: ["s1"], byId: { s1: { displayTitle: "only" } } });

    createResumeContribution(ctx).ui.onSelect({ id: "scope:all", label: "全部会话" }, { sessionId: "s1" });

    expect(setSearch).not.toHaveBeenCalled();
  });

  it("localizes the search copy it hands the shell", () => {
    expect(createResumeContribution(context({}).ctx).ui.searchLabels()).toEqual({
      placeholder: "搜索会话",
      empty: "还没有可切换的会话",
      noResults: "没有匹配的会话",
    });
  });

  it("uses fuzzy search, because session titles are read as names not as query text", () => {
    expect(createResumeContribution(context({}).ctx).ui.searchMode).toBe("fuzzy-label");
  });
});

/**
 * `/resume` row construction, scope tabs and switch dispatch.
 *
 * The command is a session switch, not a model continuation: picking a row must
 * be the same single navigation action the sidebar performs when the user clicks
 * that session. So the rows are derived from the client's own session catalog and
 * the pick goes straight to the workspace navigator — there is no separate
 * "resume" state to keep consistent with the sidebar.
 *
 * Scope is a tab over the row set: the picker opens on the project in use and the
 * scope rows switch it to every session. Archived sessions belong to neither tab —
 * the sidebar deliberately hides them, so they are never loaded and search cannot
 * reach them.
 */
import { describe, expect, it, vi } from "vitest";

import {
  DEFAULT_SCOPE,
  RESUME_COMMAND_NAME,
  RESUME_SCOPES,
  SCOPE_ROW_PREFIX,
  nextScope,
  resumeOptions,
  resumeRows,
  scopeOfRow,
  scopeRow,
  switchTo,
  type ResumeScope,
  type SessionListLike,
  type SessionRowLike,
} from "../src/client/resume.ts";

/** Build a catalog snapshot; only the fields the command reads are populated. */
function catalog(
  rows: Array<{
    id: string;
    title: string;
    running?: boolean;
    blank?: boolean;
    cwd?: string;
    origin?: "subagent";
  }>,
): SessionListLike {
  const byId: Record<string, SessionRowLike> = {};
  const ids: string[] = [];
  for (const row of rows) {
    ids.push(row.id);
    byId[row.id] = {
      displayTitle: row.title,
      running: row.running ?? false,
      blank: row.blank ?? false,
      ...(row.cwd !== undefined ? { cwd: row.cwd } : {}),
      ...(row.origin !== undefined ? { origin: row.origin } : {}),
    };
  }
  return { ids, byId };
}

/** Derive one scope's rows for a session whose directory is the app under test. */
function rowsOf(state: SessionListLike, currentSessionId: string, scope: ResumeScope, archived: string[] = [], currentCwd?: string) {
  return resumeRows(state, {
    currentSessionId,
    scope,
    archived,
    ...(currentCwd !== undefined ? { currentCwd } : {}),
  });
}

describe("/resume row construction", () => {
  it("is named resume, because the slash menu keys rows by bare name", () => {
    expect(RESUME_COMMAND_NAME).toBe("resume");
  });

  it("lists every listed session in host order", () => {
    const state = catalog([
      { id: "s3", title: "third" },
      { id: "s1", title: "first" },
      { id: "s2", title: "second" },
    ]);

    expect(rowsOf(state, "s1", "all").map(row => row.id)).toEqual(["s3", "s1", "s2"]);
  });

  it("labels rows with the human title so no raw session id reaches the menu", () => {
    const state = catalog([{ id: "s1", title: "重构剪贴板写入器" }]);

    expect(rowsOf(state, "s1", "all").map(row => row.label)).toEqual(["重构剪贴板写入器"]);
  });

  it("parks the highlight on the session in use, so an accept without looking keeps it", () => {
    // SelectOption.active is the shell's highlight anchor, not decoration: the row
    // marked active is what an accept gesture made without looking confirms.
    const state = catalog([
      { id: "s1", title: "first" },
      { id: "s2", title: "second" },
    ]);

    expect(rowsOf(state, "s2", "all").map(row => row.active ?? false)).toEqual([false, true]);
  });

  it("marks no row active when the current session is not in the catalog", () => {
    // A brand-new session can open before the host list projects it; nothing may
    // claim the highlight in that window or the user's first accept picks it.
    const state = catalog([{ id: "s1", title: "first" }]);

    expect(rowsOf(state, "unlisted", "all").every(row => row.active !== true)).toBe(true);
  });

  it("never offers a blank session, since switching to one is not resuming work", () => {
    const state = catalog([
      { id: "s1", title: "first" },
      { id: "s2", title: "draft", blank: true },
    ]);

    expect(rowsOf(state, "s1", "all").map(row => row.id)).toEqual(["s1"]);
  });

  it("surfaces running sessions as a badge rather than a filter", () => {
    const state = catalog([
      { id: "s1", title: "idle" },
      { id: "s2", title: "busy", running: true },
    ]);

    expect(rowsOf(state, "s1", "all").map(row => row.badge)).toEqual([undefined, "运行中"]);
  });

  it("yields no rows when the catalog is empty", () => {
    expect(rowsOf({ ids: [], byId: {} }, "s1", "all")).toEqual([]);
  });
});

describe("/resume scope tabs", () => {
  it("offers exactly two scopes, project first because it is the default", () => {
    expect(RESUME_SCOPES).toEqual(["project", "all"]);
    expect(DEFAULT_SCOPE).toBe("project");
  });

  it("labels the scopes in the user's terms, not as internal enums", () => {
    expect(RESUME_SCOPES.map(scope => scopeRow(scope, false).label)).toEqual(["当前项目", "全部会话"]);
  });

  it("badges the scope in use instead of marking it active", () => {
    // `active` is the shell's highlight anchor, so marking the scope in use there
    // would make an accept without looking re-pick that scope rather than confirm
    // the session the user is already in. A badge states the same fact safely.
    const rows = RESUME_SCOPES.map(scope => scopeRow(scope, scope === "project")).map(row => ({
      badge: row.badge,
      active: row.active ?? false,
    }));

    expect(rows).toEqual([
      { badge: "当前", active: false },
      { badge: undefined, active: false },
    ]);
  });

  it("groups scope rows apart from sessions so they never read as a session", () => {
    expect(scopeRow("all", false).group?.label).toBe("范围");
  });

  it("gives session rows their own section, so the scope heading stops reading as theirs", () => {
    // With sessions ungrouped they render straight under the 范围 heading, which
    // makes two switches and a session list look like one run-on list. A second
    // heading is the only block boundary the shell offers.
    const state = catalog([{ id: "s1", title: "only" }]);

    expect(rowsOf(state, "s1", "all")[0]?.group).toEqual({ name: "sessions", label: "会话" });
  });

  it("leaves the session row itself alone: same label, badge, anchor and order", () => {
    // Only the section heading is new. Everything a user reads inside the row
    // stays exactly what it was.
    const state = catalog([
      { id: "s1", title: "idle" },
      { id: "s2", title: "busy", running: true },
    ]);

    expect(rowsOf(state, "s2", "all")).toEqual([
      { id: "s1", label: "idle", group: { name: "sessions", label: "会话" } },
      { id: "s2", label: "busy", badge: "运行中", group: { name: "sessions", label: "会话" }, active: true },
    ]);
  });

  it("describes what each scope widens to, so the switches do not read as rows", () => {
    // A switch states its consequence; a session row states a title. Giving the
    // switches a trailing note is the difference the shell can render.
    expect(RESUME_SCOPES.map(scope => scopeRow(scope, false).detail)).toEqual(["只看本目录", "含其他项目"]);
  });

  it("does not promise a directory filter the row set cannot deliver", () => {
    // The project scope falls back to every session when the session in use has no
    // directory, so a switch that always said 只看本目录 would be lying exactly
    // where the fallback lives.
    const state = catalog([{ id: "s1", title: "only" }]);

    const [project] = resumeOptions(state, { currentSessionId: "s1", scope: "project", archived: [] });

    expect(project?.detail).toBe("无目录，等同全部");
  });

  it("recognises a scope row id and rejects a session id or a forged scope", () => {
    expect(scopeOfRow(`${SCOPE_ROW_PREFIX}all`)).toBe("all");
    expect(nextScope(`${SCOPE_ROW_PREFIX}project`)).toBe("project");
    expect(scopeOfRow("session-06195936")).toBeUndefined();
    expect(scopeOfRow(`${SCOPE_ROW_PREFIX}forged`)).toBeUndefined();
  });

  it("puts scope rows ahead of session rows, since the scope is chosen first", () => {
    const state = catalog([{ id: "s1", title: "only" }]);

    const options = resumeOptions(state, { currentSessionId: "s1", scope: "all", archived: [] });

    expect(options.map(row => row.id)).toEqual([`${SCOPE_ROW_PREFIX}project`, `${SCOPE_ROW_PREFIX}all`, "s1"]);
  });
});

describe("/resume scope filtering", () => {
  const state = catalog([
    { id: "o1", title: "other project", cwd: "/work/other" },
    { id: "p1", title: "project one", cwd: "/work/app" },
    { id: "p2", title: "project two", cwd: "/work/app" },
    { id: "n1", title: "no cwd" },
  ]);

  it("limits the project scope to the invoking session's own directory", () => {
    expect(rowsOf(state, "p1", "project", [], "/work/app").map(row => row.id)).toEqual(["p1", "p2"]);
  });

  it("shows every session in the all scope", () => {
    expect(rowsOf(state, "p1", "all", [], "/work/app").map(row => row.id)).toEqual(["o1", "p1", "p2", "n1"]);
  });

  it("drops archived sessions from both scopes, so search cannot resurrect them", () => {
    const archived = ["p2", "o1"];

    expect(rowsOf(state, "p1", "project", archived, "/work/app").map(row => row.id)).toEqual(["p1"]);
    expect(rowsOf(state, "p1", "all", archived, "/work/app").map(row => row.id)).toEqual(["p1", "n1"]);
  });

  it("drops subagent sessions, which are continuation addresses rather than resumable work", () => {
    const withChild = catalog([
      { id: "p1", title: "parent", cwd: "/work/app" },
      { id: "c1", title: "child", cwd: "/work/app", origin: "subagent" },
    ]);

    expect(rowsOf(withChild, "p1", "all").map(row => row.id)).toEqual(["p1"]);
  });

  it("keeps the host order inside a scope rather than re-sorting", () => {
    expect(rowsOf(state, "p1", "all").map(row => row.id)).toEqual(["o1", "p1", "p2", "n1"]);
  });

  it("falls back to every session when the invoking session has no directory", () => {
    // An empty picker would read as "you have no sessions" when the truth is
    // "this session has no project", so the project scope widens instead.
    expect(rowsOf(state, "n1", "project").map(row => row.id)).toEqual(["o1", "p1", "p2", "n1"]);
  });
});

describe("/resume switch dispatch", () => {
  it("opens the picked session through the same navigation call the sidebar uses", async () => {
    const openSession = vi.fn();

    await switchTo({ openSession }, { id: "s2" });

    expect(openSession).toHaveBeenCalledExactlyOnceWith("s2");
  });

  it("leaves the workspace alone when the pick names the session already in use", async () => {
    // Re-opening the current session is a navigation to where the user already is;
    // skipping it keeps the conversation's scroll and draft untouched.
    const openSession = vi.fn();

    await switchTo({ openSession }, { id: "s1" }, "s1");

    expect(openSession).not.toHaveBeenCalled();
  });

  it("reports a navigator failure instead of swallowing it", async () => {
    const openSession = vi.fn(() => {
      throw new Error("session vanished");
    });

    await expect(switchTo({ openSession }, { id: "s2" })).rejects.toThrow("session vanished");
  });
});

