/**
 * Which surface gets which command.
 *
 * `/copy` writes the clipboard of the machine this process runs on, so offering
 * it where a terminal is not the UI would put a command in the palette that
 * copies into a clipboard the user cannot paste from. The gate is the terminal
 * capability rather than the profile name, because a profile is just a label.
 */
import { describe, expect, it, vi } from "vitest";

import { apply, inject, name } from "../src/index.ts";

/** A context recording every command registration it receives. */
function context(services: { terminal: boolean; withCommands: boolean }) {
  const registered: Array<{ name: string }> = [];
  const commands = { register: (definition: { name: string }) => (registered.push(definition), () => {}) };
  return {
    registered,
    ctx: {
      logger: { info: () => {}, warn: () => {} },
      get: (service: string, strict?: boolean) => {
        if (service === "commands") return services.withCommands ? commands : undefined;
        if (services.terminal && (service === "tuiPluginHost" || service === "tuiToast")) return {};
        return undefined;
      },
    },
  };
}

/** Run apply and let its deferred registration finish. */
async function settle(fn: () => void): Promise<void> {
  vi.useFakeTimers();
  try {
    fn();
    vi.runAllTimers();
  } finally {
    vi.useRealTimers();
  }
}

describe("surface gating", () => {
  it("is named after the package the Loader mounts", () => {
    expect(name).toBe("dsh-slash-commands");
  });

  it("declares every service it reads, because Cordis refuses undeclared reads", () => {
    // Observed as a real failure: reading ctx.sessionTitle without this threw a
    // gateway error, and the swallowed exception surfaced in the GUI as an
    // unexplained command failure.
    expect(inject).toContain("commands");
    expect(inject).toContain("sessionTitle");
  });

  it("does not gate the whole row on the workspace registry", () => {
    // Observed on a real headless boot: declaring `workspaceRegistry` left the
    // whole plugin pending on compositions without the workspace domain, which
    // would have taken /rename and /copy down with it. The archive pair
    // resolves the registry softly per invocation instead, so a missing
    // service is one command's error message, not the row's silence.
    expect(inject).not.toContain("workspaceRegistry");
  });

  it("registers /rename on a non-terminal surface", async () => {
    const { registered, ctx } = context({ terminal: false, withCommands: true });

    await settle(() => apply(ctx as never));

    expect(registered.map(entry => entry.name)).toContain("rename");
  });

  it("registers /rename, /archive and /placeholder on a non-terminal surface", async () => {
    const { registered, ctx } = context({ terminal: false, withCommands: true });

    await settle(() => apply(ctx as never));

    expect(registered.map(entry => entry.name).sort()).toEqual(["archive", "placeholder", "rename"]);
  });

  it("does not offer /unarchive on a non-terminal surface", async () => {
    // The web/desktop slash menu gets /unarchive from the client half, whose
    // contribution gates it on the session actually being archived. Registering
    // the host command too would collide by name at candidate synthesis and
    // would show a dead row in every unarchived session.
    const { registered, ctx } = context({ terminal: false, withCommands: true });

    await settle(() => apply(ctx as never));

    expect(registered.some(entry => entry.name === "unarchive")).toBe(false);
  });

  it("does not offer /copy without a terminal", async () => {
    // The whole point: a web or desktop host would copy into its own machine's
    // clipboard, which the user never pastes from.
    const { registered, ctx } = context({ terminal: false, withCommands: true });

    await settle(() => apply(ctx as never));

    expect(registered.some(entry => entry.name === "copy")).toBe(false);
  });

  it("registers every command on a terminal surface", async () => {
    // The TUI has no client half, so /unarchive comes from the host registry
    // there, ungated: a TUI session stays open after being archived, so the
    // archived state is a normal posture and a constant row is honest.
    const { registered, ctx } = context({ terminal: true, withCommands: true });

    await settle(() => apply(ctx as never));

    expect(registered.map(entry => entry.name).sort()).toEqual([
      "archive",
      "copy",
      "placeholder",
      "rename",
      "unarchive",
    ]);
  });

  it("still registers nothing when no commands service is mounted", async () => {
    // /rename and the archive pair fail loudly but are caught and logged: a
    // composition can compose its surfaces differently, and that must not
    // stop the plugin from trying its other half.
    const { registered, ctx } = context({ terminal: false, withCommands: false });

    await settle(() => apply(ctx as never));

    expect(registered).toEqual([]);
  });
});

files.packages/dsh-slash-commands/test/unarchi:
/**
 * `/unarchive` as a client-side, state-gated command.
 *
 * The web/desktop slash menu must not offer a restore command for a session
 * that is not archived — that is dead weight in every session's palette. The
 * client contribution face is the only place that gates per-session state
 * (`available` runs per candidate pass), so the command lives here and the
 * host half registers it only where the client half does not run (the TUI),
 * where the archived state is a normal posture and a constant row is honest.
 */
import { describe, expect, it, vi } from "vitest";

import {
  createUnarchiveContribution,
  unarchiveAvailable,
  type UnarchiveContributionContext,
  type UnarchiveWorkspacesLike,
} from "../src/client/unarchive-contribution.ts";

/** A workspaces service recording unarchive calls, serving a fixed archive set. */
function workspaces(archivedSessionIds: readonly string[], options: { fail?: boolean } = {}) {
  const calls: string[] = [];
  const service: UnarchiveWorkspacesLike & { calls: string[] } = {
    calls,
    list: { getSnapshot: () => ({ archivedSessionIds }) },
    unarchiveSession: vi.fn(async sessionId => {
      if (options.fail) throw new Error("carrier fault");
      calls.push(sessionId);
    }),
  };
  return service;
}

function context(service: UnarchiveWorkspacesLike): UnarchiveContributionContext {
  return { workspaces: service };
}

describe("unarchive availability", () => {
  it("offers the command only for a session that is currently archived", () => {
    expect(unarchiveAvailable(["a", "b"], "b")).toBe(true);
    expect(unarchiveAvailable(["a", "b"], "c")).toBe(false);
  });

  it("offers nothing when the archive set is empty", () => {
    expect(unarchiveAvailable([], "a")).toBe(false);
  });
});

describe("the unarchive contribution", () => {
  it("is an action command named after the package's grammar", () => {
    const contribution = createUnarchiveContribution(context(workspaces(["a"])));

    expect(contribution.name).toBe("unarchive");
    expect(contribution.ui.kind).toBe("action");
  });

  it("reads the live archive set per availability check, not at registration", () => {
    // Sessions are archived and restored while the plugin stays mounted; a set
    // captured at registration would be stale by the second menu open.
    const service = workspaces([]);
    const contribution = createUnarchiveContribution(context(service));

    const before = contribution.available({ sessionId: "a" });
    (service.list.getSnapshot = () => ({ archivedSessionIds: ["a"] }));
    const after = contribution.available({ sessionId: "a" });

    expect(before).toBe(false);
    expect(after).toBe(true);
  });

  it("unarchives the invoking session when run", () => {
    const service = workspaces(["a"]);
    const contribution = createUnarchiveContribution(context(service));

    contribution.ui.run({ sessionId: "a" });

    expect(service.calls).toEqual(["a"]);
  });

  it("keeps a failing unarchive from throwing inside the menu", () => {
    const service = workspaces(["a"], { fail: true });
    const contribution = createUnarchiveContribution(context(service));

    expect(() => contribution.ui.run({ sessionId: "a" })).not.toThrow();
  });
});

