import { buildStatus } from "../src/index.ts"

const SIG = Symbol.for("dsh.subagent.deliverPrompt")

interface FakeAgent {
  id: string
  status: string
  session: { header: { origin?: string; parentSession?: string } }
}

function agent(id: string, patch: Partial<FakeAgent> = {}): FakeAgent {
