/** A complete event; tests override only the field under scrutiny. */
function keyEvent(overrides: Partial<GlobalKeyEvent> = {}): GlobalKeyEvent {
  return {
    code: "KeyE",
    ctrlKey: true,
    shiftKey: true,
    metaKey: false,
    altKey: false,
    defaultPrevented: false,
    preventDefault: () => {},
    ...overrides,
  };
}

